INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC4-2-u2-C1','sci',4,2,'u2',1,'숲과 물속에 사는 생물 — 숲에는 토끼·다람쥐·노루·소나무·강아지풀 등이, 물속에는 붕어·송사리·물방개·검정말·부들·거북·게 등이 삶 · 숲, 강이나 바다 같은 물속, 작은 연못, 생태 공원, 논과 밭, 개울가 등 우리 주변 여러 곳에 생물이 삶',ARRAY['[4과14-01] 생태계의 구성 요소를 조사하여 생물요소와 비생물요소로 분류할 수 있다(지도서 성취기준 원문 · W7 확인)']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC4-2-u2-C2','sci',4,2,'u2',1,'나뭇잎으로 숲과 물속 모습 표현하기 — 나뭇잎·나뭇가지·열매 등을 모음 → 흰 종이에 붙여 가며 꾸밈(밑그림 먼저, 큰 조각과 작은 조각 섞기, 모양과 색깔 함께) → 필요한 부분에 그림을 그려 완성(눈·코·입·털) → 표현한 모습을 발표함',ARRAY['[4과14-01] 생태계의 구성 요소를 조사하여 생물요소와 비생물요소로 분류할 수 있다(지도서 성취기준 원문 · W7 확인)']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC4-2-u2-C3','sci',4,2,'u2',1,'표현 활동에서 중요한 것과 지킬 것 — 땅에 떨어진 것으로 모으고 식물체에 붙은 부분을 무리하게 채취하지 않음 · 나뭇가지로 장난치지 않음 · 사실적으로 묘사할 필요 없음 · 완성도보다 함께 참여하는 것이 중요함 · 목표는 주변을 살펴보고 그곳에 사는 생물을 알아보는 것',ARRAY['[4과14-01] 생태계의 구성 요소를 조사하여 생물요소와 비생물요소로 분류할 수 있다(지도서 성취기준 원문 · W7 확인)']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC4-2-u2-C4','sci',4,2,'u2',2,'생태계의 뜻 — 한 지역에 살고 있는 생물들과 이들이 살아가는 데 영향을 주는 다양한 요소를 통틀어 생태계라고 함 · 숲·바다·강·호수 같은 생태계, 어항·연못·화단·공원 같은 작은 생태계, 습지·갯벌·사막·극지 생태계가 있음',ARRAY['[4과14-01] 생태계의 구성 요소를 조사하여 생물요소와 비생물요소로 분류할 수 있다(지도서 성취기준 원문 · W7 확인)']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC4-2-u2-C5','sci',4,2,'u2',2,'생물요소와 비생물요소 — 동물·식물처럼 살아 있는 요소 = 생물요소 · 햇빛·공기·물·온도·흙처럼 살아 있지 않은 요소 = 비생물요소 · 어느 쪽인지는 목록을 외워서가 아니라 살아 있는지 아닌지를 보고 정함',ARRAY['[4과14-01] 생태계의 구성 요소를 조사하여 생물요소와 비생물요소로 분류할 수 있다(지도서 성취기준 원문 · W7 확인)']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC4-2-u2-C6','sci',4,2,'u2',2,'생태계 구성 요소를 조사하고 분류하는 방법 — 그림 속 생태계를 이야기함 → 구성 요소를 조사함(누리망) → 생물인 것과 생물이 아닌 것으로 분류함(모둠이 의논한 뒤 붙임딱지를 하나씩, 평소에 쓰는 생물 이름) → 필요한 까닭을 이야기함 · 숲·강·바다에 사는 생물은 곳마다 다르지만 햇빛·공기·온도는 세 곳 모두에 있음',ARRAY['[4과14-01] 생태계의 구성 요소를 조사하여 생물요소와 비생물요소로 분류할 수 있다(지도서 성취기준 원문 · W7 확인)']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC4-2-u2-C7','sci',4,2,'u2',2,'비생물요소가 생물에게 필요한 까닭 — 햇빛 — 식물이 양분을 만드는 데 이용 · 공기 — 숨을 쉴 수 있게 함 · 물 — 생명을 유지하는 데 꼭 필요하고 물속 생물의 사는 공간 · 온도 — 살아가는 데 알맞은 환경 · 흙 — 식물이 뿌리를 내리는 곳, 땅속 생물의 사는 장소',ARRAY['[4과14-01] 생태계의 구성 요소를 조사하여 생물요소와 비생물요소로 분류할 수 있다(지도서 성취기준 원문 · W7 확인)']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC4-2-u2-C8','sci',4,2,'u2',2,'작은 곳·사람이 만든 곳의 생태계 — 텃밭·어항처럼 사람이 만들거나 작은 곳도 생물요소와 비생물요소를 모두 포함하면 생태계라고 할 수 있음',ARRAY['[4과14-01] 생태계의 구성 요소를 조사하여 생물요소와 비생물요소로 분류할 수 있다(지도서 성취기준 원문 · W7 확인)']::text[],8) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC4-2-u2-C9','sci',4,2,'u2',3,'생물요소를 역할에 따라 분류하기 — 생물은 양분을 얻는 방법과 생태계에서 맡은 역할이 서로 다름 · 양분은 영양이 되는 성분 · 하는 역할에 따라 생산자, 소비자, 분해자로 구분함 · 생물 카드에 손을 베이지 않게 조심하고 컴퓨터를 쓴 뒤 로그아웃함',ARRAY['[4과14-01] 생태계의 구성 요소를 조사하여 생물요소와 비생물요소로 분류할 수 있다(지도서 성취기준 원문 · W7 확인)']::text[],9) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC4-2-u2-C10','sci',4,2,'u2',3,'생산자 — 햇빛을 이용하여 스스로 양분을 만들고 다른 생물의 먹이가 됨 · 소나무, 강아지풀, 부들, 검정말 등',ARRAY['[4과14-01] 생태계의 구성 요소를 조사하여 생물요소와 비생물요소로 분류할 수 있다(지도서 성취기준 원문 · W7 확인)']::text[],10) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC4-2-u2-C11','sci',4,2,'u2',3,'소비자 — 생산자 또는 다른 생물을 먹어 양분을 얻음 · 왜가리, 고래, 메뚜기, 생이새우 등',ARRAY['[4과14-01] 생태계의 구성 요소를 조사하여 생물요소와 비생물요소로 분류할 수 있다(지도서 성취기준 원문 · W7 확인)']::text[],11) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC4-2-u2-C12','sci',4,2,'u2',3,'분해자 — 죽은 몸이나 배출물을 분해하여 양분을 얻음 · 분해 결과 생긴 물질을 생산자가 이용할 수 있게 함 · 곰팡이, 버섯, 세균, 물곰팡이 등 · 분해자도 살아 있는 생물요소',ARRAY['[4과14-01] 생태계의 구성 요소를 조사하여 생물요소와 비생물요소로 분류할 수 있다(지도서 성취기준 원문 · W7 확인)']::text[],12) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC4-2-u2-C13','sci',4,2,'u2',3,'버섯은 생산자가 아님 — 생김새가 식물과 비슷하고 나물처럼 무쳐 먹어 식물로 여기기 쉬움 · 햇빛이 잘 들지 않는 나무줄기나 밑동 부근에서 자람 · 식물과 다른 생물이며 스스로 양분을 만들지 못하고 죽은 몸이나 배출물을 분해하여 양분을 얻음',ARRAY['[4과14-01] 생태계의 구성 요소를 조사하여 생물요소와 비생물요소로 분류할 수 있다(지도서 성취기준 원문 · W7 확인)']::text[],13) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC4-2-u2-C14','sci',4,2,'u2',4,'먹이사슬 — 생물 사이의 먹이 관계가 사슬처럼 연결되어 있는 것 · 벼 → 메뚜기 → 개구리 → 뱀 → 새매 · 토끼풀 → 토끼 → 여우 → 호랑이 · 화살표는 잡아먹히는 생물로부터 잡아먹는 생물 방향으로 그림',ARRAY['[4과14-02] 생태계를 구성하는 생물요소들의 먹고 먹히는 관계를 조사하여 먹이그물로 표현할 수 있다(지도서 성취기준 원문 · W7 확인)']::text[],14) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC4-2-u2-C15','sci',4,2,'u2',4,'먹이그물 — 다양한 먹이사슬이 그물처럼 복잡하게 연결되어 있는 것 · 메뚜기는 벼만 먹지 않고 다른 풀(강아지풀·질경이)도 먹으며 개구리뿐 아니라 직박구리의 먹이도 됨 · 먹이사슬과 먹이그물은 같은 것이 아님',ARRAY['[4과14-02] 생태계를 구성하는 생물요소들의 먹고 먹히는 관계를 조사하여 먹이그물로 표현할 수 있다(지도서 성취기준 원문 · W7 확인)']::text[],15) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC4-2-u2-C16','sci',4,2,'u2',4,'먹이 관계가 복잡할 때의 좋은 점 — 먹이그물에서 메뚜기가 사라지면 개구리는 일시적으로 줄고 벼는 일시적으로 늘며 직접 관계가 없는 다람쥐·도토리는 크게 변하지 않음 · 먹이 관계가 복잡할수록 한 생물의 수가 변해도 다른 생물을 먹이로 먹을 수 있어 생태계가 큰 변화 없이 유지됨',ARRAY['[4과14-02] 생태계를 구성하는 생물요소들의 먹고 먹히는 관계를 조사하여 먹이그물로 표현할 수 있다(지도서 성취기준 원문 · W7 확인)']::text[],16) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC4-2-u2-C17','sci',4,2,'u2',4,'먹이 관계는 크기로 정해지지 않음 — 스라소니와 여우는 둘 다 토끼를 잡아먹지만 서로 잡아먹는 관계는 아님 · 골리앗타이거피시는 물 위로 뛰어올라 작은 새를 낚아채 새가 물고기를 먹는 것과 반대의 먹이사슬을 이룸',ARRAY['[4과14-02] 생태계를 구성하는 생물요소들의 먹고 먹히는 관계를 조사하여 먹이그물로 표현할 수 있다(지도서 성취기준 원문 · W7 확인)']::text[],17) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC4-2-u2-C18','sci',4,2,'u2',4,'먹이사슬 놀이와 먹이그물 모형 만들기 — 종이컵에 먹고 먹히는 차례로 생물을 그려 크기 순서대로 넣고 하나씩 열어 봄 · 놀이 말을 숲 그림판에 올리고 먹이 관계에 따라 화살표를 그려 모형을 완성함 · 셀로판테이프 날과 그림판 모서리에 손을 다치지 않게 조심함',ARRAY['[4과14-02] 생태계를 구성하는 생물요소들의 먹고 먹히는 관계를 조사하여 먹이그물로 표현할 수 있다(지도서 성취기준 원문 · W7 확인)']::text[],18) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC4-2-u2-C19','sci',4,2,'u2',5,'환경오염의 뜻과 종류 — 자연 생태계나 주변이 인간 활동으로 훼손되고 더럽혀지는 현상을 환경오염이라고 함 · 대기오염, 수질오염, 토양오염 등이 있음',ARRAY['[4과14-03] 인간 활동이 생태계에 미치는 영향을 조사하고, 생태계보전을 위해 할 수 있는 일을 토의하여 실천할 수 있다(지도서 성취기준 원문 · W7 확인)']::text[],19) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC4-2-u2-C20','sci',4,2,'u2',5,'환경오염의 원인 — 자동차 배기가스 — 대기오염·수질오염 · 바닷물에 섞인 쓰레기 — 수질오염 · 논밭의 농약 — 토양오염·수질오염 · 생활 쓰레기 매립 — 토양오염 · 기름 유출 — 수질오염 · 원인 하나가 꼭 한 가지 환경오염만 일으키는 것은 아님',ARRAY['[4과14-03] 인간 활동이 생태계에 미치는 영향을 조사하고, 생태계보전을 위해 할 수 있는 일을 토의하여 실천할 수 있다(지도서 성취기준 원문 · W7 확인)']::text[],20) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC4-2-u2-C21','sci',4,2,'u2',5,'환경오염이 생태계에 미치는 영향 — 주변 환경이 오염되면 생물이 숨 쉬기 어려워지고 생태계의 안정이 깨져 다양한 생물의 생존을 위협함 · 오염된 물을 마신 생물은 병에 걸릴 수 있음 · 흙이 오염되면 식물이 잘 자라지 못하고 흙 속 이로운 생물이 살기 어려움 · 작은 플라스틱은 생물의 몸속으로 들어오기도 함',ARRAY['[4과14-03] 인간 활동이 생태계에 미치는 영향을 조사하고, 생태계보전을 위해 할 수 있는 일을 토의하여 실천할 수 있다(지도서 성취기준 원문 · W7 확인)']::text[],21) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC4-2-u2-C22','sci',4,2,'u2',5,'생태계보전을 위한 노력 — 가까운 거리는 걷거나 자전거·대중교통 이용 · 일회용품 줄이고 분리배출 · 농약은 가능한 한 적게 · 음식물 남기지 않고 세제는 적당한 양만 · 물 절약, 물티슈 대신 손수건 · 꽃을 꺾지 않기 · 오염 물질의 양을 줄이고 자연 개발과 생태계보전을 위한 노력 사이에 균형을 이룸 · 농약·플라스틱은 과다 사용이 문제',ARRAY['[4과14-03] 인간 활동이 생태계에 미치는 영향을 조사하고, 생태계보전을 위해 할 수 있는 일을 토의하여 실천할 수 있다(지도서 성취기준 원문 · W7 확인)']::text[],22) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC4-2-u2-C23','sci',4,2,'u2',5,'환경오염을 조사하는 방법 — 누리망에서 대기오염·수질오염·토양오염을 검색함 · 조사한 정보의 출처를 확인하고 옳은 정보와 거짓 정보를 구분함 · 모둠별로 사례 하나를 골라 생태계에 미치는 영향을 조사하고 보전 노력을 토의함',ARRAY['[4과14-03] 인간 활동이 생태계에 미치는 영향을 조사하고, 생태계보전을 위해 할 수 있는 일을 토의하여 실천할 수 있다(지도서 성취기준 원문 · W7 확인)']::text[],23) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC4-2-u2-C24','sci',4,2,'u2',6,'생태계복원과 생태계 지킴이 — 복원은 원래대로 회복한다는 뜻 · 무분별한 개발과 환경오염, 무관심으로 원래 모습을 잃은 곳을 되살리고 잘 보전하는 사람이 생태계 지킴이 · 쓰레기로 가득했던 산도 새롭게 태어날 수 있음',ARRAY['[4과14-03] 인간 활동이 생태계에 미치는 영향을 조사하고, 생태계보전을 위해 할 수 있는 일을 토의하여 실천할 수 있다(지도서 성취기준 원문 · W7 확인)']::text[],24) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC4-2-u2-C25','sci',4,2,'u2',6,'생태계 지킴이 활동 차례 — 계획해요(보전이 필요한 까닭·갈 장소·모둠원 역할·지키는 방법) → 실행해요(장소를 찾아 사진 찍기 → 까닭과 해결 방법 토의 → 발표 자료 만들기) → 실천해요(발표 → 생각 나누기·칭찬 댓글 → 생활 속 실천) · 개인 정보를 누리망에 함부로 올리지 않음',ARRAY['[4과14-03] 인간 활동이 생태계에 미치는 영향을 조사하고, 생태계보전을 위해 할 수 있는 일을 토의하여 실천할 수 있다(지도서 성취기준 원문 · W7 확인)']::text[],25) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC4-2-u2-C26','sci',4,2,'u2',6,'지킴이 활동의 안전과 생명 존중 — 사진을 찍을 장소를 찾아갈 때 다치지 않게 조심함 · 방문한 곳에서는 여러 생물을 아끼고 사랑하는 마음을 가짐',ARRAY['[4과14-03] 인간 활동이 생태계에 미치는 영향을 조사하고, 생태계보전을 위해 할 수 있는 일을 토의하여 실천할 수 있다(지도서 성취기준 원문 · W7 확인)']::text[],26) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC4-2-u2-C27','sci',4,2,'u2',6,'좋은 발표 자료와 실천 방법 — 장소의 문제점이 잘 드러났는가, 우리가 실천할 수 있는 해결 방법인가, 그대로 실천하면 복원과 보전에 도움이 되는가를 살핌 · 꾸밈이 아니라 내용이 중요함 · 망가진 등산로 — 안내 팻말, 정해진 길로 다니기 캠페인, 흙을 덮어 관리, 등산로 보수',ARRAY['[4과14-03] 인간 활동이 생태계에 미치는 영향을 조사하고, 생태계보전을 위해 할 수 있는 일을 토의하여 실천할 수 있다(지도서 성취기준 원문 · W7 확인)']::text[],27) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC4-2-u2-C28','sci',4,2,'u2',6,'숲의 미로 — 팻말 ① 생물요소만 따라가요 · ② 지나간 길의 요소들끼리 올바른 먹이사슬을 이루어야 해요 · 팻말 없이 11가지 → ① 8가지(흙·물·햇빛이 빠짐) → ①과 ② 4가지(옥수수 → 메뚜기 → 참새 → 새매) · 생물요소라도 먹이사슬을 이루지 못하면(상어·노루·세균·곰팡이) 지날 수 없음',ARRAY['[4과14-02] 생태계를 구성하는 생물요소들의 먹고 먹히는 관계를 조사하여 먹이그물로 표현할 수 있다(지도서 성취기준 원문 · W7 확인)']::text[],28) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC4-2-u2-C29','sci',4,2,'u2',7,'먹을거리가 되는 곤충 — 예로부터 우리 조상들은 메뚜기나 누에 번데기를 훌륭한 먹거리로 즐겨 왔음 · 징그럽다고 생각하는 사람이 많지만 맛이 좋고 영양가가 아주 높음 · 주로 곤충의 원래 모습이 잘 드러나지 않는 형태로 만듦 · 우리나라가 먹을 수 있는 종류로 인정한 곤충만 먹음',ARRAY['[4과14-03] 인간 활동이 생태계에 미치는 영향을 조사하고, 생태계보전을 위해 할 수 있는 일을 토의하여 실천할 수 있다(지도서 성취기준 원문 · W7 확인)']::text[],29) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC4-2-u2-C30','sci',4,2,'u2',7,'친환경 미래 식량 — 곤충은 가축과 달리 기를 때 먹이를 훨씬 적게 먹고 온실 가스를 거의 배출하지 않음 · 온실 가스는 지구 표면의 온도를 상승시키는 원인이 되는 기체(이산화 탄소, 메탄 등) · 빈곤과 환경 문제를 동시에 해결해 줄 먹을거리로 관심을 받음',ARRAY['[4과14-03] 인간 활동이 생태계에 미치는 영향을 조사하고, 생태계보전을 위해 할 수 있는 일을 토의하여 실천할 수 있다(지도서 성취기준 원문 · W7 확인)']::text[],30) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC4-2-u2-C31','sci',4,2,'u2',7,'곤충 요리 전문가 — 맛이 좋고 영양가 높은 다양한 곤충을 찾아내고 새로운 요리 방법을 개발함 · 앞으로 미래 직업으로 자리 잡을 수도 있음',ARRAY['[4과14-03] 인간 활동이 생태계에 미치는 영향을 조사하고, 생태계보전을 위해 할 수 있는 일을 토의하여 실천할 수 있다(지도서 성취기준 원문 · W7 확인)']::text[],31) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-2-u2-X01','sci',4,'u2',ARRAY['SC4-2-u2-C1']::text[],'숲과 물속에 사는 생물을 뒤바꾸거나(숲에 붕어, 물속에 노루) 생물은 숲에만 산다고 여긴다','숲 · 물속 · 우리 주변') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-2-u2-X02','sci',4,'u2',ARRAY['SC4-2-u2-C2']::text[],'나뭇잎 표현 활동의 차례를 잘못 안다(색칠부터, 사진 찍기부터, 발표부터)','모으기 → 붙이기 → 그리기 → 발표') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-2-u2-X03','sci',4,'u2',ARRAY['SC4-2-u2-C3']::text[],'나무에 붙은 잎을 잡아당겨 모으거나 나뭇가지로 장난친다','땅에 떨어진 것') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-2-u2-X04','sci',4,'u2',ARRAY['SC4-2-u2-C3']::text[],'생물을 사진처럼 똑같이, 완성도 높게 만들어야 좋고 잘 만든 모둠이 이긴다고 여긴다','참여가 중요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-2-u2-X05','sci',4,'u2',ARRAY['SC4-2-u2-C4']::text[],'생태계를 생물만 모아 놓은 것이라 여기거나 아주 넓은 곳에만 있다고 여긴다','생물 + 영향을 주는 요소') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-2-u2-X06','sci',4,'u2',ARRAY['SC4-2-u2-C8']::text[],'사람이 만든 곳이나 작은 곳(텃밭·어항)은 생태계가 아니라고 여긴다','두 요소가 다 있으면 생태계') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-2-u2-X07','sci',4,'u2',ARRAY['SC4-2-u2-C5']::text[],'햇빛·물·공기처럼 살아 있지 않은 것을 생물요소로 여긴다(빛나서, 움직여서)','살아 있는지 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-2-u2-X08','sci',4,'u2',ARRAY['SC4-2-u2-C5']::text[],'식물이나 버섯·세균처럼 움직이지 않거나 작은 생물을 비생물요소로 여긴다','식물도 살아 있어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-2-u2-X09','sci',4,'u2',ARRAY['SC4-2-u2-C5','SC4-2-u2-C6']::text[],'어느 칸에 넣을지를 목록을 외워 정하거나 사는 곳으로 정한다(숲에만 있으니 비생물요소)','목록이 아니라 살아 있는지') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-2-u2-X10','sci',4,'u2',ARRAY['SC4-2-u2-C6']::text[],'조사·분류할 때 붙임딱지를 미리 다 떼거나 의논 없이 붙이거나 어려운 이름으로만 부른다','의논하고 하나씩') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-2-u2-X11','sci',4,'u2',ARRAY['SC4-2-u2-C7']::text[],'비생물요소와 그것이 필요한 까닭을 잘못 잇는다(흙 — 숨쉬기, 햇빛 — 뿌리)','햇빛 · 공기 · 물 · 온도 · 흙') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-2-u2-X12','sci',4,'u2',ARRAY['SC4-2-u2-C6','SC4-2-u2-C7']::text[],'곳이 달라지면 비생물요소도 모두 달라지거나 비생물요소는 생물에게 필요 없다고 여긴다','세 곳 모두 햇빛 · 공기 · 온도') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-2-u2-X13','sci',4,'u2',ARRAY['SC4-2-u2-C9']::text[],'생물요소를 하는 역할이 아니라 사는 곳·크기·생김새로 나눈다','양분을 얻는 방법') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-2-u2-X14','sci',4,'u2',ARRAY['SC4-2-u2-C10']::text[],'생산자를 다른 생물을 먹는 생물로 여기거나 동물을 생산자에 넣는다','스스로 양분을 만듦') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-2-u2-X15','sci',4,'u2',ARRAY['SC4-2-u2-C11']::text[],'소비자를 스스로 양분을 만드는 생물로 여기거나 소비자는 생산자만 먹는다고 여긴다','다른 생물을 먹음') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-2-u2-X16','sci',4,'u2',ARRAY['SC4-2-u2-C12']::text[],'분해자는 살아 있는 생물이 아니라고 여긴다','분해자도 생물요소') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-2-u2-X17','sci',4,'u2',ARRAY['SC4-2-u2-C12']::text[],'분해자가 하는 일을 잘못 안다(살아 있는 생물을 먹는다, 분해한 물질은 쓸모가 없다)','죽은 몸 · 배출물') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-2-u2-X18','sci',4,'u2',ARRAY['SC4-2-u2-C13']::text[],'버섯은 생김새가 식물과 비슷하니 스스로 양분을 만드는 생산자라고 여긴다','버섯은 분해자') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-2-u2-X19','sci',4,'u2',ARRAY['SC4-2-u2-C9']::text[],'생물 카드를 거칠게 다루거나 컴퓨터를 쓴 뒤 로그아웃하지 않는다','손 조심 · 로그아웃') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-2-u2-X20','sci',4,'u2',ARRAY['SC4-2-u2-C14']::text[],'먹이사슬의 차례나 화살표 방향을 거꾸로 안다(먹는 생물에서 먹히는 생물로)','먹히는 → 먹는') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-2-u2-X21','sci',4,'u2',ARRAY['SC4-2-u2-C14','SC4-2-u2-C15']::text[],'먹이사슬과 먹이그물은 이름만 다른 같은 것이라고 여긴다','사슬과 그물') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-2-u2-X22','sci',4,'u2',ARRAY['SC4-2-u2-C15']::text[],'한 생물은 한 가지 먹이만 먹고 한 생물에게만 먹힌다고 여긴다','여러 먹이 · 여러 상대') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-2-u2-X23','sci',4,'u2',ARRAY['SC4-2-u2-C16']::text[],'먹이그물에서 한 생물이 사라지면 모든 생물이 사라지거나, 먹던 생물·먹히던 생물이 늘고 주는 방향을 거꾸로 안다','일시적으로 줄고 늘어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-2-u2-X24','sci',4,'u2',ARRAY['SC4-2-u2-C16']::text[],'먹이 관계가 단순할수록 생태계가 잘 유지된다고 여긴다','복잡할수록 유지') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-2-u2-X25','sci',4,'u2',ARRAY['SC4-2-u2-C17']::text[],'먹고 먹히는 관계는 몸집이 큰 생물이 작은 생물을 먹는 것으로 정해져 있다고 여긴다','크기로 정해지지 않아요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-2-u2-X26','sci',4,'u2',ARRAY['SC4-2-u2-C18']::text[],'놀이·모형을 만들 때 셀로판테이프 날이나 그림판 모서리를 조심하지 않는다','손 조심') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-2-u2-X27','sci',4,'u2',ARRAY['SC4-2-u2-C19']::text[],'환경오염은 사람과 관계없이 저절로 생기는 것이라 여기거나 환경오염의 종류를 잘못 안다','인간 활동으로') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-2-u2-X28','sci',4,'u2',ARRAY['SC4-2-u2-C20']::text[],'원인 하나는 반드시 한 가지 환경오염만 일으킨다고 여긴다','둘이 켜지기도 해요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-2-u2-X29','sci',4,'u2',ARRAY['SC4-2-u2-C19','SC4-2-u2-C20']::text[],'환경오염의 원인·모습과 종류를 잘못 잇는다(배기가스 — 토양오염만, 숨쉬기 어려움 — 수질오염)','대기 · 수질 · 토양') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-2-u2-X30','sci',4,'u2',ARRAY['SC4-2-u2-C21']::text[],'환경오염은 생물에게 영향이 없거나 금방 저절로 사라진다고 여긴다','생존을 위협해요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-2-u2-X31','sci',4,'u2',ARRAY['SC4-2-u2-C22']::text[],'생태계보전과 거리가 먼 행동을 보전 노력이라고 여긴다(농약 많이 쓰기, 물 마음껏 쓰기)','오염 물질 줄이기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-2-u2-X32','sci',4,'u2',ARRAY['SC4-2-u2-C22']::text[],'농약·플라스틱은 조금도 쓰면 안 된다거나 개발을 모두 멈춰야 한다고 여겨 과다 사용과 균형을 놓친다','과다 사용 · 균형') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-2-u2-X33','sci',4,'u2',ARRAY['SC4-2-u2-C23']::text[],'조사할 때 출처를 확인하지 않거나 옳은 정보와 거짓 정보를 구분하지 않는다','출처 확인') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-2-u2-X34','sci',4,'u2',ARRAY['SC4-2-u2-C24']::text[],'복원의 뜻을 잘못 안다(새로 만들기, 모두 치워 없애기, 다른 곳으로 옮기기)','원래대로 회복') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-2-u2-X35','sci',4,'u2',ARRAY['SC4-2-u2-C25']::text[],'지킴이 활동의 차례를 잘못 알거나 계획·발표로만 끝내고 실천하지 않는다','계획 → 실행 → 실천') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-2-u2-X36','sci',4,'u2',ARRAY['SC4-2-u2-C25']::text[],'개인 정보를 누리망에 함부로 올리거나 친구의 실천 방법을 비난한다','개인 정보 · 칭찬 댓글') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-2-u2-X37','sci',4,'u2',ARRAY['SC4-2-u2-C26']::text[],'장소를 찾아갈 때 위험한 곳에 들어가거나 생물을 함부로 다룬다','안전 · 생물 사랑') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-2-u2-X38','sci',4,'u2',ARRAY['SC4-2-u2-C27']::text[],'예쁘고 화려하게 꾸민 발표 자료가 좋은 자료라고 여기거나 실천할 수 없는 방법을 고른다','문제점 · 실천 · 도움') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-2-u2-X39','sci',4,'u2',ARRAY['SC4-2-u2-C28']::text[],'생물요소이기만 하면 무엇이든 숲의 미로를 지날 수 있다고 여긴다(팻말 ②를 놓침)','올바른 먹이사슬') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-2-u2-X40','sci',4,'u2',ARRAY['SC4-2-u2-C28']::text[],'비생물요소도 숲의 미로를 지날 수 있다고 여기거나 팻말을 붙일 때 줄어드는 수를 잘못 센다(팻말 ①을 놓침)','생물요소만') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-2-u2-X41','sci',4,'u2',ARRAY['SC4-2-u2-C29']::text[],'징그러우니 곤충은 먹을거리가 될 수 없다고 여기거나 곤충이면 무엇이든 먹을 수 있다고 여긴다','인정한 종류 · 맛과 영양') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-2-u2-X42','sci',4,'u2',ARRAY['SC4-2-u2-C29']::text[],'곤충을 먹는 일은 앞으로 처음 시작하는 일이라고 여긴다','예로부터') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-2-u2-X43','sci',4,'u2',ARRAY['SC4-2-u2-C30']::text[],'곤충이 가축보다 먹이를 많이 먹거나 온실 가스를 많이 배출한다고 여긴다','가축과 달리') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-2-u2-X44','sci',4,'u2',ARRAY['SC4-2-u2-C30']::text[],'온실 가스의 뜻을 잘못 안다(지구 표면의 온도를 낮춘다, 곤충의 먹이다)','온도를 상승시키는 기체') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-2-u2-X45','sci',4,'u2',ARRAY['SC4-2-u2-C31']::text[],'곤충 요리 전문가가 하는 일을 잘못 안다(곤충을 잡아 없애기, 곤충 모습을 그대로 드러내기)','찾아내고 개발해요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u2_L01_basic#1','sci',4,2,'u2','L01','g4_2_sci_u2_L01_basic','lesson_basic','SC4-2-u2-C1',1,'mc','auto','숲에 사는 생물로 알맞은 것은 무엇인가요?',ARRAY['SC4-2-u2-X01']::text[],false,'{"seq":1,"concept":"SC4-2-u2-C1","difficulty":1,"kind":"mc","stem":"숲에 사는 생물로 알맞은 것은 무엇인가요?","options":[{"t":"다람쥐","correct":true},{"t":"붕어","mis":"SC4-2-u2-X01"},{"t":"송사리","mis":"SC4-2-u2-X01"},{"t":"물방개","mis":"SC4-2-u2-X01"}],"explanation":["숲을 떠올려요.","나무 사이를 뛰어다녀요.","다람쥐예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u2_L01_basic#2','sci',4,2,'u2','L01','g4_2_sci_u2_L01_basic','lesson_basic','SC4-2-u2-C2',1,'sa','auto','나뭇잎으로 숲과 물속 모습 표현하기에서 ㉡ 나뭇잎을 붙여 가며 꾸미는 종이는 무슨 색인가요? 한 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SC4-2-u2-C2","difficulty":1,"kind":"sa","stem":"나뭇잎으로 숲과 물속 모습 표현하기에서 ㉡ 나뭇잎을 붙여 가며 꾸미는 종이는 무슨 색인가요? 한 글자로 쓰세요.","answer":["흰","흰색","하얀","흰 종이"],"explanation":["㉡을 읽어요.","○ 종이예요.","흰 종이예요."],"asset":{"type":"passage","lines":["㉠ 다양한 식물의 나뭇잎, 나뭇가지, 열매 등을 주워서 모아요.","㉡ 흰 종이에 붙여 가며 숲이나 물속의 모습을 꾸며요.","㉢ 필요한 부분에 그림을 그려서 모습을 완성해요.","㉣ 친구들에게 표현한 모습을 발표해요."],"title":"나뭇잎으로 숲과 물속 모습 표현하기"},"mis":"SC4-2-u2-X02"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u2_L01_basic#3','sci',4,2,'u2','L01','g4_2_sci_u2_L01_basic','lesson_basic','SC4-2-u2-C3',1,'ox','auto','자연물을 모을 때에는 땅에 떨어져 있는 것으로 모아요.',ARRAY['SC4-2-u2-X03']::text[],false,'{"seq":3,"concept":"SC4-2-u2-C3","difficulty":1,"kind":"ox","stem":"자연물을 모을 때에는 땅에 떨어져 있는 것으로 모아요.","answer":"O","reason_options":[{"t":"식물에 붙어 있는 부분을 무리하게 떼지 않아야 하기 때문에","correct":true},{"t":"떨어진 잎만 색깔이 예쁘기 때문에","mis":"SC4-2-u2-X03"}],"mis":"SC4-2-u2-X03","explanation":["모을 때를 떠올려요.","식물을 아껴요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u2_L01_basic#4','sci',4,2,'u2','L01','g4_2_sci_u2_L01_basic','lesson_basic','SC4-2-u2-C1',1,'mc','auto','물속에 사는 생물로 알맞은 것은 무엇인가요?',ARRAY['SC4-2-u2-X01']::text[],false,'{"seq":4,"concept":"SC4-2-u2-C1","difficulty":1,"kind":"mc","stem":"물속에 사는 생물로 알맞은 것은 무엇인가요?","options":[{"t":"송사리","correct":true},{"t":"노루","mis":"SC4-2-u2-X01"},{"t":"토끼","mis":"SC4-2-u2-X01"},{"t":"소나무","mis":"SC4-2-u2-X01"}],"explanation":["물속을 떠올려요.","헤엄치는 작은 물고기예요.","송사리예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u2_L01_basic#5','sci',4,2,'u2','L01','g4_2_sci_u2_L01_basic','lesson_basic','SC4-2-u2-C2',2,'mc','auto','나뭇잎으로 숲과 물속 모습을 표현할 때 가장 먼저 하는 일은 무엇인가요?',ARRAY['SC4-2-u2-X02','SC4-2-u2-X04']::text[],false,'{"seq":5,"concept":"SC4-2-u2-C2","difficulty":2,"kind":"mc","stem":"나뭇잎으로 숲과 물속 모습을 표현할 때 가장 먼저 하는 일은 무엇인가요?","options":[{"t":"나뭇잎, 나뭇가지, 열매 등을 주워서 모은다","correct":true},{"t":"흰 종이에 밑그림부터 색칠한다","mis":"SC4-2-u2-X02"},{"t":"표현한 모습을 발표한다","mis":"SC4-2-u2-X02"},{"t":"어느 모둠이 잘 만드는지 겨룬다","mis":"SC4-2-u2-X04"}],"explanation":["㉠을 읽어요.","재료부터 모아요.","주워서 모아요."],"asset":{"type":"passage","lines":["㉠ 다양한 식물의 나뭇잎, 나뭇가지, 열매 등을 주워서 모아요.","㉡ 흰 종이에 붙여 가며 숲이나 물속의 모습을 꾸며요.","㉢ 필요한 부분에 그림을 그려서 모습을 완성해요.","㉣ 친구들에게 표현한 모습을 발표해요."],"title":"나뭇잎으로 숲과 물속 모습 표현하기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u2_L01_basic#6','sci',4,2,'u2','L01','g4_2_sci_u2_L01_basic','lesson_basic','SC4-2-u2-C3',2,'mc','auto','자연물을 모을 때 하지 않아야 할 행동은 무엇인가요?',ARRAY['SC4-2-u2-X03','SC4-2-u2-X04']::text[],false,'{"seq":6,"concept":"SC4-2-u2-C3","difficulty":2,"kind":"mc","stem":"자연물을 모을 때 하지 않아야 할 행동은 무엇인가요?","options":[{"t":"모은 나뭇가지로 친구에게 장난을 친다","correct":true},{"t":"땅에 떨어져 있는 나뭇잎을 줍는다","mis":"SC4-2-u2-X03"},{"t":"다양한 모양과 색깔을 골고루 찾는다","mis":"SC4-2-u2-X03"},{"t":"모둠 친구와 함께 모은다","mis":"SC4-2-u2-X04"}],"explanation":["안전을 떠올려요.","나뭇가지는 위험할 수 있어요.","장난치는 행동이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u2_L01_basic#7','sci',4,2,'u2','L01','g4_2_sci_u2_L01_basic','lesson_basic','SC4-2-u2-C2',2,'match','auto','차례와 하는 일을 알맞게 이으세요.','{}'::text[],false,'{"seq":7,"concept":"SC4-2-u2-C2","difficulty":2,"kind":"match","stem":"차례와 하는 일을 알맞게 이으세요.","pairs":[{"l":"첫 번째","r":"나뭇잎, 나뭇가지, 열매 모으기"},{"l":"두 번째","r":"흰 종이에 붙여 가며 꾸미기"},{"l":"세 번째","r":"그림을 그려서 모습을 완성하기"},{"l":"네 번째","r":"표현한 모습을 발표하기"}],"mis":"SC4-2-u2-X02","explanation":["㉠~㉣을 차례로 읽어요.","모으고, 붙이고, 그리고, 말해요.","차례대로 이어요."],"asset":{"type":"passage","lines":["㉠ 다양한 식물의 나뭇잎, 나뭇가지, 열매 등을 주워서 모아요.","㉡ 흰 종이에 붙여 가며 숲이나 물속의 모습을 꾸며요.","㉢ 필요한 부분에 그림을 그려서 모습을 완성해요.","㉣ 친구들에게 표현한 모습을 발표해요."],"title":"나뭇잎으로 숲과 물속 모습 표현하기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u2_L01_basic#8','sci',4,2,'u2','L01','g4_2_sci_u2_L01_basic','lesson_basic','SC4-2-u2-C3',2,'ox','auto','생물의 모습은 사진처럼 똑같이 그려야 해요.',ARRAY['SC4-2-u2-X04']::text[],false,'{"seq":8,"concept":"SC4-2-u2-C3","difficulty":2,"kind":"ox","stem":"생물의 모습은 사진처럼 똑같이 그려야 해요.","answer":"X","reason_options":[{"t":"생물의 모습을 사실적으로 묘사할 필요는 없기 때문에","correct":true},{"t":"사진처럼 그려야 좋은 작품이기 때문에","mis":"SC4-2-u2-X04"}],"mis":"SC4-2-u2-X04","explanation":["표현할 때를 떠올려요.","똑같이 그리지 않아도 돼요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u2_L01_basic#9','sci',4,2,'u2','L01','g4_2_sci_u2_L01_basic','lesson_basic','SC4-2-u2-C2',2,'mc','auto','기본적인 모양을 꾸민 뒤에는 무엇을 하나요?',ARRAY['SC4-2-u2-X02']::text[],false,'{"seq":9,"concept":"SC4-2-u2-C2","difficulty":2,"kind":"mc","stem":"기본적인 모양을 꾸민 뒤에는 무엇을 하나요?","options":[{"t":"필요한 부분에 그림을 그려 눈, 코, 입 같은 모습을 완성한다","correct":true},{"t":"붙인 나뭇잎을 모두 떼어 낸다","mis":"SC4-2-u2-X02"},{"t":"종이를 자로 재어 크기를 맞춘다","mis":"SC4-2-u2-X02"},{"t":"아무에게도 보여 주지 않는다","mis":"SC4-2-u2-X02"}],"explanation":["㉢을 읽어요.","자연물로 나타내기 어려운 곳이 있어요.","그림으로 완성해요."],"asset":{"type":"passage","lines":["㉠ 다양한 식물의 나뭇잎, 나뭇가지, 열매 등을 주워서 모아요.","㉡ 흰 종이에 붙여 가며 숲이나 물속의 모습을 꾸며요.","㉢ 필요한 부분에 그림을 그려서 모습을 완성해요.","㉣ 친구들에게 표현한 모습을 발표해요."],"title":"나뭇잎으로 숲과 물속 모습 표현하기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u2_L01_basic#10','sci',4,2,'u2','L01','g4_2_sci_u2_L01_basic','lesson_basic','SC4-2-u2-C1',3,'mc','auto','친구들이 표현한 작품에 들어 있는 생물을 보고 알 수 있는 것은 무엇인가요?',ARRAY['SC4-2-u2-X01']::text[],false,'{"seq":10,"concept":"SC4-2-u2-C1","difficulty":3,"kind":"mc","stem":"친구들이 표현한 작품에 들어 있는 생물을 보고 알 수 있는 것은 무엇인가요?","options":[{"t":"숲과 물속에는 서로 다른 여러 생물이 어우러져 살고 있다","correct":true},{"t":"숲과 물속에는 같은 생물만 산다","mis":"SC4-2-u2-X01"},{"t":"물속에는 식물이 살지 않는다","mis":"SC4-2-u2-X01"},{"t":"숲에는 동물만 산다","mis":"SC4-2-u2-X01"}],"explanation":["두 줄을 견줘요.","사는 생물이 달라요.","여러 생물이 어우러져 살아요."],"asset":{"type":"passage","lines":["숲 — 토끼, 다람쥐, 노루, 소나무, 강아지풀","물속 — 붕어, 송사리, 물방개, 검정말, 부들"],"title":"친구들이 표현한 작품에 들어 있는 생물"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u2_L01_challenge#1','sci',4,2,'u2','L01','g4_2_sci_u2_L01_challenge','lesson_challenge','SC4-2-u2-C1',2,'mc','auto','우리 주변에서 생물이 사는 곳을 바르게 말한 것은 무엇인가요?',ARRAY['SC4-2-u2-X01']::text[],false,'{"seq":1,"concept":"SC4-2-u2-C1","difficulty":2,"kind":"mc","stem":"우리 주변에서 생물이 사는 곳을 바르게 말한 것은 무엇인가요?","options":[{"t":"숲, 강이나 바다, 작은 연못, 논과 밭, 개울가 등 여러 곳에 산다","correct":true},{"t":"생물은 숲에만 산다","mis":"SC4-2-u2-X01"},{"t":"생물은 바다에만 산다","mis":"SC4-2-u2-X01"},{"t":"사람이 사는 동네에는 생물이 없다","mis":"SC4-2-u2-X01"}],"explanation":["주변을 떠올려요.","연못과 논밭도 있어요.","여러 곳에 살아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u2_L01_challenge#2','sci',4,2,'u2','L01','g4_2_sci_u2_L01_challenge','lesson_challenge','SC4-2-u2-C3',2,'blank','auto','「이 활동에서는 잘 만드는 것보다 (    )이/가 중요해요.」 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SC4-2-u2-X04']::text[],false,'{"seq":2,"concept":"SC4-2-u2-C3","difficulty":2,"kind":"blank","stem":"「이 활동에서는 잘 만드는 것보다 (    )이/가 중요해요.」 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"함께 참여하는 것","correct":true},{"t":"가장 화려하게 꾸미는 것","mis":"SC4-2-u2-X04"},{"t":"사진처럼 똑같이 그리는 것","mis":"SC4-2-u2-X04"},{"t":"다른 모둠보다 빨리 끝내는 것","mis":"SC4-2-u2-X04"}],"explanation":["지킬 것을 떠올려요.","솜씨가 달라도 괜찮아요.","함께 참여하는 것이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u2_L01_challenge#3','sci',4,2,'u2','L01','g4_2_sci_u2_L01_challenge','lesson_challenge','SC4-2-u2-C3',3,'error','auto','자연물을 모으며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC4-2-u2-X03','SC4-2-u2-X02','SC4-2-u2-X04']::text[],false,'{"seq":3,"concept":"SC4-2-u2-C3","difficulty":3,"kind":"error","stem":"자연물을 모으며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 나 — 「나무에 붙어 있는 잎이 더 싱싱하니까 힘껏 잡아당겨 따자.」","correct":true,"mis_target":"SC4-2-u2-X03"},{"t":"친구 가 — 「둥근 잎, 길쭉한 잎을 골고루 줍자.」","mis":"SC4-2-u2-X02"},{"t":"친구 다 — 「누가 더 멋지게 만드는지는 따지지 말자.」","mis":"SC4-2-u2-X04"}],"explanation":["모을 때 지킬 것을 떠올려요.","땅에 떨어진 것으로 모아요.","친구 나가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u2_L01_challenge#4','sci',4,2,'u2','L01','g4_2_sci_u2_L01_challenge','lesson_challenge','SC4-2-u2-C3',3,'mc','auto','이 활동에서 표현의 완성도를 따지지 않는 까닭은 무엇인가요?',ARRAY['SC4-2-u2-X04','SC4-2-u2-X03','SC4-2-u2-X02']::text[],false,'{"seq":4,"concept":"SC4-2-u2-C3","difficulty":3,"kind":"mc","stem":"이 활동에서 표현의 완성도를 따지지 않는 까닭은 무엇인가요?","options":[{"t":"주변을 살펴보고 그곳에 사는 생물을 알아보는 것이 목표이기 때문에","correct":true},{"t":"만들 시간이 모자라기 때문에","mis":"SC4-2-u2-X04"},{"t":"나뭇잎이 부족하기 때문에","mis":"SC4-2-u2-X03"},{"t":"그림 도구를 쓸 수 없기 때문에","mis":"SC4-2-u2-X02"}],"explanation":["활동의 목표를 떠올려요.","생물을 알아보는 활동이에요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u2_L01_challenge#5','sci',4,2,'u2','L01','g4_2_sci_u2_L01_challenge','lesson_challenge','SC4-2-u2-C2',3,'mc','auto','나뭇잎으로 표현할 때 알맞은 방법은 무엇인가요?',ARRAY['SC4-2-u2-X02','SC4-2-u2-X04']::text[],false,'{"seq":5,"concept":"SC4-2-u2-C2","difficulty":3,"kind":"mc","stem":"나뭇잎으로 표현할 때 알맞은 방법은 무엇인가요?","options":[{"t":"붙이기 전에 대략적인 밑그림을 그리고, 큰 조각과 작은 조각을 섞어 모양과 색깔을 함께 살린다","correct":true},{"t":"밑그림 없이 한 가지 크기의 잎만 붙인다","mis":"SC4-2-u2-X02"},{"t":"생물의 털 한 올까지 사진처럼 그린다","mis":"SC4-2-u2-X04"},{"t":"색깔은 생각하지 않고 모양만 맞춘다","mis":"SC4-2-u2-X02"}],"explanation":["붙이기 전에 할 일이 있어요.","조각과 색깔을 생각해요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u2_L01_challenge#6','sci',4,2,'u2','L01','g4_2_sci_u2_L01_challenge','lesson_challenge','SC4-2-u2-C1',3,'ox','auto','물속에도 붕어 같은 동물뿐 아니라 검정말, 부들 같은 식물이 살아요.',ARRAY['SC4-2-u2-X01']::text[],false,'{"seq":6,"concept":"SC4-2-u2-C1","difficulty":3,"kind":"ox","stem":"물속에도 붕어 같은 동물뿐 아니라 검정말, 부들 같은 식물이 살아요.","answer":"O","reason_options":[{"t":"물속에는 동물과 식물이 함께 어우러져 살기 때문에","correct":true},{"t":"물속 식물은 물에 떠다니는 쓰레기이기 때문에","mis":"SC4-2-u2-X01"}],"mis":"SC4-2-u2-X01","explanation":["물속 작품을 떠올려요.","식물도 있었어요.","그래서 O예요."],"asset":{"type":"passage","lines":["숲 — 토끼, 다람쥐, 노루, 소나무, 강아지풀","물속 — 붕어, 송사리, 물방개, 검정말, 부들"],"title":"친구들이 표현한 작품에 들어 있는 생물"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u2_L01_challenge#7','sci',4,2,'u2','L01','g4_2_sci_u2_L01_challenge','lesson_challenge','SC4-2-u2-C3',3,'mc','auto','이 활동에서 중요한 것끼리 묶은 것은 무엇인가요?',ARRAY['SC4-2-u2-X04','SC4-2-u2-X03']::text[],false,'{"seq":7,"concept":"SC4-2-u2-C3","difficulty":3,"kind":"mc","stem":"이 활동에서 중요한 것끼리 묶은 것은 무엇인가요?","options":[{"t":"주변에 사는 생물을 알아보기, 모둠 활동에 함께 참여하기","correct":true},{"t":"누구 작품이 가장 예쁜지 뽑기, 완성도 따지기","mis":"SC4-2-u2-X04"},{"t":"나무에 붙은 잎 많이 따기, 빨리 끝내기","mis":"SC4-2-u2-X03"},{"t":"사진처럼 똑같이 그리기, 혼자 다 만들기","mis":"SC4-2-u2-X04"}],"explanation":["목표를 떠올려요.","함께 참여해요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u2_L01_challenge#8','sci',4,2,'u2','L01','g4_2_sci_u2_L01_challenge','lesson_challenge','SC4-2-u2-C1',4,'mc','auto','물속 모습을 표현한 친구가 「나는 노루랑 다람쥐를 붙였어.」라고 했어요. 가장 알맞게 도와준 말은 무엇인가요?',ARRAY['SC4-2-u2-X01','SC4-2-u2-X04']::text[],false,'{"seq":8,"concept":"SC4-2-u2-C1","difficulty":4,"kind":"mc","stem":"물속 모습을 표현한 친구가 「나는 노루랑 다람쥐를 붙였어.」라고 했어요. 가장 알맞게 도와준 말은 무엇인가요?","options":[{"t":"「노루와 다람쥐는 숲에 사는 생물이야. 물속에는 붕어, 송사리, 물방개 같은 생물이 살아.」","correct":true},{"t":"「물속에는 아무 생물이나 넣어도 돼.」","mis":"SC4-2-u2-X01"},{"t":"「물속에는 생물이 살지 않아.」","mis":"SC4-2-u2-X01"},{"t":"「더 화려하게 꾸미면 괜찮아.」","mis":"SC4-2-u2-X04"}],"explanation":["사는 곳을 떠올려요.","노루는 숲에 살아요.","첫 번째가 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u2_L01_challenge#9','sci',4,2,'u2','L01','g4_2_sci_u2_L01_challenge','lesson_challenge','SC4-2-u2-C3',4,'mc','auto','그림 솜씨가 걱정된다는 친구에게 해 줄 말로 가장 알맞은 것은 무엇인가요?',ARRAY['SC4-2-u2-X04','SC4-2-u2-X03']::text[],false,'{"seq":9,"concept":"SC4-2-u2-C3","difficulty":4,"kind":"mc","stem":"그림 솜씨가 걱정된다는 친구에게 해 줄 말로 가장 알맞은 것은 무엇인가요?","options":[{"t":"「똑같이 그리지 않아도 돼. 어떤 생물이 사는지 살펴보고 함께 참여하는 게 중요해.」","correct":true},{"t":"「잘 못 그리면 빠지는 게 좋아.」","mis":"SC4-2-u2-X04"},{"t":"「사진을 보고 똑같이 따라 그려야 해.」","mis":"SC4-2-u2-X04"},{"t":"「나무에서 잎을 많이 따 오면 잘 만들 수 있어.」","mis":"SC4-2-u2-X03"}],"explanation":["활동에서 중요한 것을 떠올려요.","솜씨가 아니에요.","첫 번째가 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u2_L01_challenge#10','sci',4,2,'u2','L01','g4_2_sci_u2_L01_challenge','lesson_challenge','SC4-2-u2-C2',4,'essay','teacher','나뭇잎으로 숲이나 물속 모습을 표현하는 차례를 쓰고, 자연물을 모을 때 지킬 점을 두 가지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC4-2-u2-C2","difficulty":4,"kind":"essay","stem":"나뭇잎으로 숲이나 물속 모습을 표현하는 차례를 쓰고, 자연물을 모을 때 지킬 점을 두 가지 쓰세요.","answer_guide":{"answer":"예: 나뭇잎, 나뭇가지, 열매 등을 주워서 모으고, 흰 종이에 붙여 가며 꾸민 뒤, 필요한 부분에 그림을 그려 완성하고 발표한다. 자연물은 땅에 떨어져 있는 것으로 모으고, 모은 나뭇가지로 친구에게 장난치지 않는다.","scoring_points":["표현하는 차례를 바르게 썼는가","모을 때 지킬 점 하나를 썼는가","모을 때 지킬 점 또 하나를 썼는가"]},"explanation":["차례를 써요.","모을 때를 떠올려요.","지킬 점을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u2_L02_basic#1','sci',4,2,'u2','L02','g4_2_sci_u2_L02_basic','lesson_basic','SC4-2-u2-C4',1,'mc','auto','한 지역에 살고 있는 생물들과 이들이 살아가는 데 영향을 주는 다양한 요소를 통틀어 무엇이라고 하나요?',ARRAY['SC4-2-u2-X05']::text[],false,'{"seq":1,"concept":"SC4-2-u2-C4","difficulty":1,"kind":"mc","stem":"한 지역에 살고 있는 생물들과 이들이 살아가는 데 영향을 주는 다양한 요소를 통틀어 무엇이라고 하나요?","options":[{"t":"생태계","correct":true},{"t":"생물요소","mis":"SC4-2-u2-X05"},{"t":"비생물요소","mis":"SC4-2-u2-X05"},{"t":"생물","mis":"SC4-2-u2-X05"}],"explanation":["통틀어 부르는 말이에요.","생물과 요소를 모두 묶어요.","생태계예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u2_L02_basic#2','sci',4,2,'u2','L02','g4_2_sci_u2_L02_basic','lesson_basic','SC4-2-u2-C5',1,'sa','auto','동물, 식물처럼 살아 있는 요소를 무엇이라고 하나요? 네 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SC4-2-u2-C5","difficulty":1,"kind":"sa","stem":"동물, 식물처럼 살아 있는 요소를 무엇이라고 하나요? 네 글자로 쓰세요.","answer":["생물요소","생물 요소"],"explanation":["살아 있는 요소예요.","생물 + 요소예요.","생물요소예요."],"mis":"SC4-2-u2-X08"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u2_L02_basic#3','sci',4,2,'u2','L02','g4_2_sci_u2_L02_basic','lesson_basic','SC4-2-u2-C5',1,'ox','auto','햇빛은 비생물요소예요.',ARRAY['SC4-2-u2-X07']::text[],false,'{"seq":3,"concept":"SC4-2-u2-C5","difficulty":1,"kind":"ox","stem":"햇빛은 비생물요소예요.","answer":"O","reason_options":[{"t":"햇빛은 살아 있지 않은 요소이기 때문에","correct":true},{"t":"햇빛은 밝게 빛나므로 살아 있는 요소이기 때문에","mis":"SC4-2-u2-X07"}],"mis":"SC4-2-u2-X07","explanation":["살아 있는지 봐요.","햇빛은 살아 있지 않아요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u2_L02_basic#4','sci',4,2,'u2','L02','g4_2_sci_u2_L02_basic','lesson_basic','SC4-2-u2-C5',1,'mc','auto','강을 이루고 있는 것에서 비생물요소는 무엇인가요?',ARRAY['SC4-2-u2-X08']::text[],false,'{"seq":4,"concept":"SC4-2-u2-C5","difficulty":1,"kind":"mc","stem":"강을 이루고 있는 것에서 비생물요소는 무엇인가요?","options":[{"t":"흙","correct":true},{"t":"붕어","mis":"SC4-2-u2-X08"},{"t":"갈대","mis":"SC4-2-u2-X08"},{"t":"다슬기","mis":"SC4-2-u2-X08"}],"explanation":["살아 있지 않은 것을 찾아요.","둘째 줄에 있어요.","흙이에요."],"asset":{"type":"passage","lines":["왜가리, 붕어, 개구리, 갈대, 부들, 다슬기","햇빛, 공기, 물, 흙, 온도"],"title":"강을 이루고 있는 것"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u2_L02_basic#5','sci',4,2,'u2','L02','g4_2_sci_u2_L02_basic','lesson_basic','SC4-2-u2-C7',2,'mc','auto','햇빛이 생물에게 필요한 까닭으로 알맞은 것은 무엇인가요?',ARRAY['SC4-2-u2-X11','SC4-2-u2-X12']::text[],false,'{"seq":5,"concept":"SC4-2-u2-C7","difficulty":2,"kind":"mc","stem":"햇빛이 생물에게 필요한 까닭으로 알맞은 것은 무엇인가요?","options":[{"t":"식물이 양분을 만드는 데 이용한다","correct":true},{"t":"식물이 뿌리를 내리는 곳이 된다","mis":"SC4-2-u2-X11"},{"t":"생물이 숨을 쉴 수 있게 해 준다","mis":"SC4-2-u2-X11"},{"t":"생물에게는 필요하지 않다","mis":"SC4-2-u2-X12"}],"explanation":["식물을 떠올려요.","햇빛으로 만들어요.","양분을 만드는 데 이용해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u2_L02_basic#6','sci',4,2,'u2','L02','g4_2_sci_u2_L02_basic','lesson_basic','SC4-2-u2-C7',2,'match','auto','비생물요소와 필요한 까닭을 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"SC4-2-u2-C7","difficulty":2,"kind":"match","stem":"비생물요소와 필요한 까닭을 알맞게 이으세요.","pairs":[{"l":"공기","r":"생물이 숨을 쉴 수 있게 해 줘요"},{"l":"물","r":"생물이 생명을 유지하는 데 꼭 필요해요"},{"l":"흙","r":"식물이 뿌리를 내리는 곳이에요"}],"mis":"SC4-2-u2-X11","explanation":["하나씩 떠올려요.","흙에 뿌리가 있어요.","공기-숨, 물-생명, 흙-뿌리예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u2_L02_basic#7','sci',4,2,'u2','L02','g4_2_sci_u2_L02_basic','lesson_basic','SC4-2-u2-C4',2,'mc','auto','생태계에 대한 설명으로 알맞은 것은 무엇인가요?',ARRAY['SC4-2-u2-X05','SC4-2-u2-X06']::text[],false,'{"seq":7,"concept":"SC4-2-u2-C4","difficulty":2,"kind":"mc","stem":"생태계에 대한 설명으로 알맞은 것은 무엇인가요?","options":[{"t":"어항, 연못처럼 작은 생태계도 있다","correct":true},{"t":"생태계는 아주 넓은 곳에만 있다","mis":"SC4-2-u2-X05"},{"t":"살아 있지 않은 것은 생태계에 들어가지 않는다","mis":"SC4-2-u2-X05"},{"t":"사람이 가꾸는 곳은 생태계가 될 수 없다","mis":"SC4-2-u2-X06"}],"explanation":["크고 작은 생태계를 떠올려요.","어항도 있어요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u2_L02_basic#8','sci',4,2,'u2','L02','g4_2_sci_u2_L02_basic','lesson_basic','SC4-2-u2-C6',2,'ox','auto','생태계의 구성 요소를 나눌 때에는 붙임딱지를 미리 모두 떼어 놓아요.',ARRAY['SC4-2-u2-X10']::text[],false,'{"seq":8,"concept":"SC4-2-u2-C6","difficulty":2,"kind":"ox","stem":"생태계의 구성 요소를 나눌 때에는 붙임딱지를 미리 모두 떼어 놓아요.","answer":"X","reason_options":[{"t":"모둠이 의논한 뒤 붙임딱지를 하나씩 떼어 내어 붙이기 때문에","correct":true},{"t":"미리 떼어 놓아야 빨리 끝낼 수 있기 때문에","mis":"SC4-2-u2-X10"}],"mis":"SC4-2-u2-X10","explanation":["분류할 때를 떠올려요.","의논이 먼저예요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u2_L02_basic#9','sci',4,2,'u2','L02','g4_2_sci_u2_L02_basic','lesson_basic','SC4-2-u2-C5',2,'mc','auto','생물요소와 비생물요소를 나누는 기준으로 알맞은 것은 무엇인가요?',ARRAY['SC4-2-u2-X09']::text[],false,'{"seq":9,"concept":"SC4-2-u2-C5","difficulty":2,"kind":"mc","stem":"생물요소와 비생물요소를 나누는 기준으로 알맞은 것은 무엇인가요?","options":[{"t":"살아 있는지 아닌지","correct":true},{"t":"어느 곳에 있는지","mis":"SC4-2-u2-X09"},{"t":"이름의 글자 수가 몇 개인지","mis":"SC4-2-u2-X09"},{"t":"목록에 적힌 차례가 몇째인지","mis":"SC4-2-u2-X09"}],"explanation":["두 요소의 뜻을 떠올려요.","살아 있는 요소와 살아 있지 않은 요소예요.","살아 있는지 아닌지예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u2_L02_basic#10','sci',4,2,'u2','L02','g4_2_sci_u2_L02_basic','lesson_basic','SC4-2-u2-C6',3,'mc','auto','세 곳을 견주어 보기에서 알 수 있는 것은 무엇인가요?',ARRAY['SC4-2-u2-X12','SC4-2-u2-X07']::text[],false,'{"seq":10,"concept":"SC4-2-u2-C6","difficulty":3,"kind":"mc","stem":"세 곳을 견주어 보기에서 알 수 있는 것은 무엇인가요?","options":[{"t":"생물인 것은 곳마다 달랐지만 햇빛, 공기, 온도는 세 곳 모두에 있었다","correct":true},{"t":"세 곳에 사는 생물은 모두 같았다","mis":"SC4-2-u2-X12"},{"t":"곳이 다르면 생물이 아닌 것도 하나도 겹치지 않았다","mis":"SC4-2-u2-X12"},{"t":"바다에는 생물이 아닌 것이 없었다","mis":"SC4-2-u2-X07"}],"explanation":["두 칸을 견줘요.","생물이 아닌 것은 거의 같아요.","첫 번째예요."],"asset":{"type":"passage","lines":["숲 — 생물인 것: 소나무, 노루, 버섯 / 생물이 아닌 것: 햇빛, 공기, 온도, 흙","강 — 생물인 것: 왜가리, 붕어, 검정말 / 생물이 아닌 것: 햇빛, 공기, 온도, 물, 흙","바다 — 생물인 것: 상어, 문어, 미역 / 생물이 아닌 것: 햇빛, 공기, 온도, 물"],"title":"세 곳을 견주어 보기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u2_L02_challenge#1','sci',4,2,'u2','L02','g4_2_sci_u2_L02_challenge','lesson_challenge','SC4-2-u2-C5',2,'blank','auto','「햇빛, 공기, 물, 온도, 흙처럼 살아 있지 않은 요소를 (    )(이)라고 해요.」 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SC4-2-u2-X07','SC4-2-u2-X05']::text[],false,'{"seq":1,"concept":"SC4-2-u2-C5","difficulty":2,"kind":"blank","stem":"「햇빛, 공기, 물, 온도, 흙처럼 살아 있지 않은 요소를 (    )(이)라고 해요.」 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"비생물요소","correct":true},{"t":"생물요소","mis":"SC4-2-u2-X07"},{"t":"생태계","mis":"SC4-2-u2-X05"},{"t":"생물","mis":"SC4-2-u2-X07"}],"explanation":["살아 있지 않은 요소예요.","비 + 생물요소예요.","비생물요소예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u2_L02_challenge#2','sci',4,2,'u2','L02','g4_2_sci_u2_L02_challenge','lesson_challenge','SC4-2-u2-C4',2,'mc','auto','생태계의 예를 바르게 묶은 것은 무엇인가요?',ARRAY['SC4-2-u2-X05']::text[],false,'{"seq":2,"concept":"SC4-2-u2-C4","difficulty":2,"kind":"mc","stem":"생태계의 예를 바르게 묶은 것은 무엇인가요?","options":[{"t":"숲, 강, 바다, 어항","correct":true},{"t":"숲, 강, 햇빛, 공기","mis":"SC4-2-u2-X05"},{"t":"붕어, 소나무, 노루, 미역","mis":"SC4-2-u2-X05"},{"t":"흙, 물, 온도, 바위","mis":"SC4-2-u2-X05"}],"explanation":["생물과 요소가 함께 있는 곳이에요.","곳의 이름을 찾아요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u2_L02_challenge#3','sci',4,2,'u2','L02','g4_2_sci_u2_L02_challenge','lesson_challenge','SC4-2-u2-C5',3,'error','auto','강을 이루고 있는 것을 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC4-2-u2-X08','SC4-2-u2-X07','SC4-2-u2-X09']::text[],false,'{"seq":3,"concept":"SC4-2-u2-C5","difficulty":3,"kind":"error","stem":"강을 이루고 있는 것을 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「갈대는 움직이지 않으니까 비생물요소야.」","correct":true,"mis_target":"SC4-2-u2-X08"},{"t":"친구 가 — 「붕어와 다슬기는 살아 있으니 생물요소야.」","mis":"SC4-2-u2-X07"},{"t":"친구 나 — 「물과 온도는 살아 있지 않으니 비생물요소야.」","mis":"SC4-2-u2-X09"}],"explanation":["갈대를 떠올려요.","식물도 살아 있어요.","친구 다가 잘못 말했어요."],"asset":{"type":"passage","lines":["왜가리, 붕어, 개구리, 갈대, 부들, 다슬기","햇빛, 공기, 물, 흙, 온도"],"title":"강을 이루고 있는 것"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u2_L02_challenge#4','sci',4,2,'u2','L02','g4_2_sci_u2_L02_challenge','lesson_challenge','SC4-2-u2-C5',3,'mc','auto','햇빛이 비생물요소인 까닭으로 알맞은 것은 무엇인가요?',ARRAY['SC4-2-u2-X09','SC4-2-u2-X07']::text[],false,'{"seq":4,"concept":"SC4-2-u2-C5","difficulty":3,"kind":"mc","stem":"햇빛이 비생물요소인 까닭으로 알맞은 것은 무엇인가요?","options":[{"t":"햇빛은 살아 있지 않기 때문에","correct":true},{"t":"햇빛은 숲에만 있기 때문에","mis":"SC4-2-u2-X09"},{"t":"햇빛은 밝게 빛나기 때문에","mis":"SC4-2-u2-X07"},{"t":"비생물요소 목록에 적혀 있기 때문에","mis":"SC4-2-u2-X09"}],"explanation":["까닭을 살펴요.","햇빛은 세 곳 모두에 있어요.","살아 있지 않기 때문이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u2_L02_challenge#5','sci',4,2,'u2','L02','g4_2_sci_u2_L02_challenge','lesson_challenge','SC4-2-u2-C8',3,'mc','auto','학교 텃밭을 생태계라고 할 수 있는 까닭은 무엇인가요?',ARRAY['SC4-2-u2-X06','SC4-2-u2-X05']::text[],false,'{"seq":5,"concept":"SC4-2-u2-C8","difficulty":3,"kind":"mc","stem":"학교 텃밭을 생태계라고 할 수 있는 까닭은 무엇인가요?","options":[{"t":"생물요소와 비생물요소를 모두 포함하고 있기 때문에","correct":true},{"t":"사람이 만든 곳이므로 생태계가 아니다","mis":"SC4-2-u2-X06"},{"t":"숲처럼 넓지 않아서 생태계가 아니다","mis":"SC4-2-u2-X06"},{"t":"식물만 있으므로 생태계가 아니다","mis":"SC4-2-u2-X05"}],"explanation":["텃밭에 있는 것을 살펴요.","살아 있는 것과 살아 있지 않은 것이 있어요.","첫 번째예요."],"asset":{"type":"passage","lines":["상추, 고추, 딸기가 자라요.","햇빛이 들고, 흙과 공기가 있어요.","사람이 가꾸는 작은 텃밭이에요."],"title":"학교 텃밭"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u2_L02_challenge#6','sci',4,2,'u2','L02','g4_2_sci_u2_L02_challenge','lesson_challenge','SC4-2-u2-C7',3,'mc','auto','바닷속 생물에게 물이 필요한 까닭으로 알맞은 것끼리 묶은 것은 무엇인가요?',ARRAY['SC4-2-u2-X11','SC4-2-u2-X12']::text[],false,'{"seq":6,"concept":"SC4-2-u2-C7","difficulty":3,"kind":"mc","stem":"바닷속 생물에게 물이 필요한 까닭으로 알맞은 것끼리 묶은 것은 무엇인가요?","options":[{"t":"생명을 유지하는 데 꼭 필요하고, 살아가는 공간이 된다","correct":true},{"t":"뿌리를 내리는 곳이 되고, 양분을 만든다","mis":"SC4-2-u2-X11"},{"t":"바닷속 생물에게는 필요하지 않다","mis":"SC4-2-u2-X12"},{"t":"햇빛을 막아 주는 일만 한다","mis":"SC4-2-u2-X11"}],"explanation":["물이 하는 일을 떠올려요.","바닷속 생물은 물속에 살아요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u2_L02_challenge#7','sci',4,2,'u2','L02','g4_2_sci_u2_L02_challenge','lesson_challenge','SC4-2-u2-C6',3,'ox','auto','생태계를 조사할 때에는 어려운 이름보다 평소에 쓰는 생물 이름으로 이야기해요.',ARRAY['SC4-2-u2-X10']::text[],false,'{"seq":7,"concept":"SC4-2-u2-C6","difficulty":3,"kind":"ox","stem":"생태계를 조사할 때에는 어려운 이름보다 평소에 쓰는 생물 이름으로 이야기해요.","answer":"O","reason_options":[{"t":"모둠 친구들과 쉽게 이야기하며 의논할 수 있기 때문에","correct":true},{"t":"평소에 쓰는 이름은 틀린 이름이기 때문에","mis":"SC4-2-u2-X10"}],"mis":"SC4-2-u2-X10","explanation":["조사할 때를 떠올려요.","친구와 의논해요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u2_L02_challenge#8','sci',4,2,'u2','L02','g4_2_sci_u2_L02_challenge','lesson_challenge','SC4-2-u2-C5',4,'mc','auto','친구가 「숲에서 본 것을 외워 두면 바다에서도 똑같이 나눌 수 있어.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?',ARRAY['SC4-2-u2-X09','SC4-2-u2-X12','SC4-2-u2-X07']::text[],false,'{"seq":8,"concept":"SC4-2-u2-C5","difficulty":4,"kind":"mc","stem":"친구가 「숲에서 본 것을 외워 두면 바다에서도 똑같이 나눌 수 있어.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?","options":[{"t":"「곳마다 사는 생물이 달라. 목록이 아니라 살아 있는지 아닌지를 보고 나누면 어디서든 나눌 수 있어.」","correct":true},{"t":"「맞아, 숲의 목록을 그대로 쓰면 돼.」","mis":"SC4-2-u2-X09"},{"t":"「바다의 생물은 숲의 생물과 모두 같아.」","mis":"SC4-2-u2-X12"},{"t":"「바다에서는 햇빛도 생물요소야.」","mis":"SC4-2-u2-X07"}],"explanation":["세 곳을 견준 것을 떠올려요.","생물은 곳마다 달랐어요.","첫 번째가 알맞아요."],"asset":{"type":"passage","lines":["숲 — 생물인 것: 소나무, 노루, 버섯 / 생물이 아닌 것: 햇빛, 공기, 온도, 흙","강 — 생물인 것: 왜가리, 붕어, 검정말 / 생물이 아닌 것: 햇빛, 공기, 온도, 물, 흙","바다 — 생물인 것: 상어, 문어, 미역 / 생물이 아닌 것: 햇빛, 공기, 온도, 물"],"title":"세 곳을 견주어 보기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u2_L02_challenge#9','sci',4,2,'u2','L02','g4_2_sci_u2_L02_challenge','lesson_challenge','SC4-2-u2-C7',4,'mc','auto','흙이 없어진다면 어떤 일이 생길지 가장 알맞게 말한 것은 무엇인가요?',ARRAY['SC4-2-u2-X11','SC4-2-u2-X12']::text[],false,'{"seq":9,"concept":"SC4-2-u2-C7","difficulty":4,"kind":"mc","stem":"흙이 없어진다면 어떤 일이 생길지 가장 알맞게 말한 것은 무엇인가요?","options":[{"t":"식물이 뿌리를 내릴 곳이 없어지고 땅속 생물이 살 곳을 잃는다","correct":true},{"t":"생물이 숨을 쉴 수 없게 된다","mis":"SC4-2-u2-X11"},{"t":"식물이 양분을 만드는 햇빛이 사라진다","mis":"SC4-2-u2-X11"},{"t":"흙은 생물에게 필요 없으니 아무 일도 없다","mis":"SC4-2-u2-X12"}],"explanation":["흙이 하는 일을 떠올려요.","뿌리와 땅속 생물이에요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u2_L02_challenge#10','sci',4,2,'u2','L02','g4_2_sci_u2_L02_challenge','lesson_challenge','SC4-2-u2-C4',4,'essay','teacher','생태계의 뜻을 쓰고, 강 생태계의 구성 요소를 생물요소 두 가지와 비생물요소 두 가지로 나누어 쓰세요. 그리고 어떻게 나누었는지 기준을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC4-2-u2-C4","difficulty":4,"kind":"essay","stem":"생태계의 뜻을 쓰고, 강 생태계의 구성 요소를 생물요소 두 가지와 비생물요소 두 가지로 나누어 쓰세요. 그리고 어떻게 나누었는지 기준을 쓰세요.","answer_guide":{"answer":"예: 생태계는 한 지역에 살고 있는 생물들과 이들이 살아가는 데 영향을 주는 다양한 요소를 통틀어 이르는 말이다. 강 생태계의 생물요소에는 붕어, 갈대가 있고, 비생물요소에는 물, 흙이 있다. 살아 있는지 아닌지를 보고 나누었다.","scoring_points":["생태계의 뜻을 썼는가","생물요소와 비생물요소를 바르게 나누어 썼는가","살아 있는지를 기준으로 썼는가"]},"explanation":["뜻부터 써요.","두 칸으로 나눠요.","기준을 써요."],"asset":{"type":"passage","lines":["왜가리, 붕어, 개구리, 갈대, 부들, 다슬기","햇빛, 공기, 물, 흙, 온도"],"title":"강을 이루고 있는 것"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u2_L03_basic#1','sci',4,2,'u2','L03','g4_2_sci_u2_L03_basic','lesson_basic','SC4-2-u2-C9',1,'mc','auto','생태계의 생물요소를 하는 역할에 따라 나눈 것은 무엇인가요?',ARRAY['SC4-2-u2-X13']::text[],false,'{"seq":1,"concept":"SC4-2-u2-C9","difficulty":1,"kind":"mc","stem":"생태계의 생물요소를 하는 역할에 따라 나눈 것은 무엇인가요?","options":[{"t":"생산자, 소비자, 분해자","correct":true},{"t":"숲, 강, 바다","mis":"SC4-2-u2-X13"},{"t":"햇빛, 공기, 온도","mis":"SC4-2-u2-X13"},{"t":"생물요소와 비생물요소","mis":"SC4-2-u2-X13"}],"explanation":["역할로 나눠요.","세 무리예요.","생산자, 소비자, 분해자예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u2_L03_basic#2','sci',4,2,'u2','L03','g4_2_sci_u2_L03_basic','lesson_basic','SC4-2-u2-C9',1,'sa','auto','영양이 되는 성분을 무엇이라고 하나요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SC4-2-u2-C9","difficulty":1,"kind":"sa","stem":"영양이 되는 성분을 무엇이라고 하나요? 두 글자로 쓰세요.","answer":["양분"],"explanation":["생물이 얻는 것이에요.","영양 + 성분이에요.","양분이에요."],"mis":"SC4-2-u2-X13"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u2_L03_basic#3','sci',4,2,'u2','L03','g4_2_sci_u2_L03_basic','lesson_basic','SC4-2-u2-C12',1,'ox','auto','분해자도 살아 있는 생물요소예요.',ARRAY['SC4-2-u2-X16']::text[],false,'{"seq":3,"concept":"SC4-2-u2-C12","difficulty":1,"kind":"ox","stem":"분해자도 살아 있는 생물요소예요.","answer":"O","reason_options":[{"t":"곰팡이, 버섯, 세균은 살아 있는 생물이기 때문에","correct":true},{"t":"분해자는 죽은 것을 다루므로 살아 있지 않기 때문에","mis":"SC4-2-u2-X16"}],"mis":"SC4-2-u2-X16","explanation":["분해자를 떠올려요.","곰팡이도 살아 있어요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u2_L03_basic#4','sci',4,2,'u2','L03','g4_2_sci_u2_L03_basic','lesson_basic','SC4-2-u2-C10',1,'mc','auto','생물 카드 뒷면의 표에서 ㉠에 해당하는 생물은 무엇인가요?',ARRAY['SC4-2-u2-X14']::text[],false,'{"seq":4,"concept":"SC4-2-u2-C10","difficulty":1,"kind":"mc","stem":"생물 카드 뒷면의 표에서 ㉠에 해당하는 생물은 무엇인가요?","options":[{"t":"소나무","correct":true},{"t":"메뚜기","mis":"SC4-2-u2-X14"},{"t":"왜가리","mis":"SC4-2-u2-X14"},{"t":"세균","mis":"SC4-2-u2-X14"}],"explanation":["㉠을 읽어요.","스스로 양분을 만들어요.","소나무예요."],"asset":{"type":"passage","lines":["㉠ 햇빛을 이용하여 스스로 양분을 만들어요.","㉡ 다른 생물을 먹어 양분을 얻어요.","㉢ 죽은 몸이나 배출물을 분해하여 양분을 얻어요."],"title":"생물 카드 뒷면의 표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u2_L03_basic#5','sci',4,2,'u2','L03','g4_2_sci_u2_L03_basic','lesson_basic','SC4-2-u2-C11',2,'mc','auto','소비자가 양분을 얻는 방법으로 알맞은 것은 무엇인가요?',ARRAY['SC4-2-u2-X15','SC4-2-u2-X17']::text[],false,'{"seq":5,"concept":"SC4-2-u2-C11","difficulty":2,"kind":"mc","stem":"소비자가 양분을 얻는 방법으로 알맞은 것은 무엇인가요?","options":[{"t":"생산자 또는 다른 생물을 먹어 양분을 얻는다","correct":true},{"t":"햇빛을 이용하여 스스로 양분을 만든다","mis":"SC4-2-u2-X15"},{"t":"죽은 몸이나 배출물을 분해한다","mis":"SC4-2-u2-X17"},{"t":"양분이 필요하지 않다","mis":"SC4-2-u2-X15"}],"explanation":["먹는 생물이에요.","다른 생물을 먹어요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u2_L03_basic#6','sci',4,2,'u2','L03','g4_2_sci_u2_L03_basic','lesson_basic','SC4-2-u2-C9',2,'match','auto','생물 무리와 하는 일을 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"SC4-2-u2-C9","difficulty":2,"kind":"match","stem":"생물 무리와 하는 일을 알맞게 이으세요.","pairs":[{"l":"생산자","r":"스스로 양분을 만들어요"},{"l":"소비자","r":"다른 생물을 먹어요"},{"l":"분해자","r":"죽은 몸이나 배출물을 분해해요"}],"mis":"SC4-2-u2-X13","explanation":["무리 이름을 떠올려요.","만들고, 먹고, 분해해요.","차례대로 이어요."],"asset":{"type":"passage","lines":["㉠ 햇빛을 이용하여 스스로 양분을 만들어요.","㉡ 다른 생물을 먹어 양분을 얻어요.","㉢ 죽은 몸이나 배출물을 분해하여 양분을 얻어요."],"title":"생물 카드 뒷면의 표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u2_L03_basic#7','sci',4,2,'u2','L03','g4_2_sci_u2_L03_basic','lesson_basic','SC4-2-u2-C12',2,'mc','auto','곰팡이는 살아가는 데 필요한 양분을 어떻게 얻나요?',ARRAY['SC4-2-u2-X14','SC4-2-u2-X17','SC4-2-u2-X16']::text[],false,'{"seq":7,"concept":"SC4-2-u2-C12","difficulty":2,"kind":"mc","stem":"곰팡이는 살아가는 데 필요한 양분을 어떻게 얻나요?","options":[{"t":"죽은 몸이나 배출물을 분해하여 얻는다","correct":true},{"t":"햇빛을 이용하여 스스로 만든다","mis":"SC4-2-u2-X14"},{"t":"살아 있는 다른 생물을 먹어 얻는다","mis":"SC4-2-u2-X17"},{"t":"살아 있지 않아 양분이 필요 없다","mis":"SC4-2-u2-X16"}],"explanation":["곰팡이는 분해자예요.","죽은 것을 분해해요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u2_L03_basic#8','sci',4,2,'u2','L03','g4_2_sci_u2_L03_basic','lesson_basic','SC4-2-u2-C13',2,'ox','auto','버섯은 식물처럼 스스로 양분을 만들어요.',ARRAY['SC4-2-u2-X18']::text[],false,'{"seq":8,"concept":"SC4-2-u2-C13","difficulty":2,"kind":"ox","stem":"버섯은 식물처럼 스스로 양분을 만들어요.","answer":"X","reason_options":[{"t":"버섯은 스스로 양분을 만들지 못하고 죽은 몸이나 배출물을 분해하여 양분을 얻기 때문에","correct":true},{"t":"버섯은 생김새가 식물과 비슷하기 때문에","mis":"SC4-2-u2-X18"}],"mis":"SC4-2-u2-X18","explanation":["버섯이 자라는 곳을 떠올려요.","햇빛이 잘 들지 않아요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u2_L03_basic#9','sci',4,2,'u2','L03','g4_2_sci_u2_L03_basic','lesson_basic','SC4-2-u2-C9',2,'mc','auto','생물 카드로 활동할 때 알맞은 행동은 무엇인가요?',ARRAY['SC4-2-u2-X19']::text[],false,'{"seq":9,"concept":"SC4-2-u2-C9","difficulty":2,"kind":"mc","stem":"생물 카드로 활동할 때 알맞은 행동은 무엇인가요?","options":[{"t":"컴퓨터를 사용한 다음에는 반드시 로그아웃을 한다","correct":true},{"t":"카드를 빨리 뽑으려고 손으로 확 잡아당긴다","mis":"SC4-2-u2-X19"},{"t":"컴퓨터를 쓰던 그대로 두고 자리를 뜬다","mis":"SC4-2-u2-X19"},{"t":"카드 모서리로 친구를 콕 찌른다","mis":"SC4-2-u2-X19"}],"explanation":["안전과 정보를 떠올려요.","쓰고 난 뒤가 중요해요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u2_L03_basic#10','sci',4,2,'u2','L03','g4_2_sci_u2_L03_basic','lesson_basic','SC4-2-u2-C10',3,'mc','auto','어항 속 생물을 하는 역할에 따라 바르게 나눈 것은 무엇인가요?',ARRAY['SC4-2-u2-X14','SC4-2-u2-X17','SC4-2-u2-X13']::text[],false,'{"seq":10,"concept":"SC4-2-u2-C10","difficulty":3,"kind":"mc","stem":"어항 속 생물을 하는 역할에 따라 바르게 나눈 것은 무엇인가요?","options":[{"t":"생산자 검정말, 소비자 생이새우, 분해자 물곰팡이","correct":true},{"t":"생산자 생이새우, 소비자 검정말, 분해자 물곰팡이","mis":"SC4-2-u2-X14"},{"t":"생산자 물곰팡이, 소비자 생이새우, 분해자 검정말","mis":"SC4-2-u2-X17"},{"t":"어항에는 생산자만 있다","mis":"SC4-2-u2-X13"}],"explanation":["양분을 얻는 방법을 봐요.","곳이 달라도 역할로 나눠요.","첫 번째예요."],"asset":{"type":"passage","lines":["검정말 — 햇빛을 이용하여 스스로 양분을 만들어요.","생이새우 — 다른 생물을 먹어요.","물곰팡이 — 죽은 생물을 분해해요."],"title":"어항 속 생물"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u2_L03_challenge#1','sci',4,2,'u2','L03','g4_2_sci_u2_L03_challenge','lesson_challenge','SC4-2-u2-C10',2,'blank','auto','「(    )은/는 햇빛을 이용하여 스스로 양분을 만들고 다른 생물의 먹이가 돼요.」 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SC4-2-u2-X15','SC4-2-u2-X17','SC4-2-u2-X13']::text[],false,'{"seq":1,"concept":"SC4-2-u2-C10","difficulty":2,"kind":"blank","stem":"「(    )은/는 햇빛을 이용하여 스스로 양분을 만들고 다른 생물의 먹이가 돼요.」 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"생산자","correct":true},{"t":"소비자","mis":"SC4-2-u2-X15"},{"t":"분해자","mis":"SC4-2-u2-X17"},{"t":"비생물요소","mis":"SC4-2-u2-X13"}],"explanation":["스스로 만들어요.","만드는 생물이에요.","생산자예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u2_L03_challenge#2','sci',4,2,'u2','L03','g4_2_sci_u2_L03_challenge','lesson_challenge','SC4-2-u2-C11',2,'mc','auto','소비자끼리 바르게 묶은 것은 무엇인가요?',ARRAY['SC4-2-u2-X14','SC4-2-u2-X17','SC4-2-u2-X13']::text[],false,'{"seq":2,"concept":"SC4-2-u2-C11","difficulty":2,"kind":"mc","stem":"소비자끼리 바르게 묶은 것은 무엇인가요?","options":[{"t":"왜가리, 고래, 메뚜기","correct":true},{"t":"소나무, 강아지풀, 부들","mis":"SC4-2-u2-X14"},{"t":"곰팡이, 버섯, 세균","mis":"SC4-2-u2-X17"},{"t":"왜가리, 부들, 세균","mis":"SC4-2-u2-X13"}],"explanation":["다른 생물을 먹는 생물이에요.","동물을 찾아요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u2_L03_challenge#3','sci',4,2,'u2','L03','g4_2_sci_u2_L03_challenge','lesson_challenge','SC4-2-u2-C12',3,'error','auto','분해자에 대해 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC4-2-u2-X16','SC4-2-u2-X17','SC4-2-u2-X18']::text[],false,'{"seq":3,"concept":"SC4-2-u2-C12","difficulty":3,"kind":"error","stem":"분해자에 대해 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 가 — 「분해자는 죽은 것을 다루니까 살아 있는 생물이 아니야.」","correct":true,"mis_target":"SC4-2-u2-X16"},{"t":"친구 나 — 「분해 결과 생긴 물질은 생산자가 이용할 수 있어.」","mis":"SC4-2-u2-X17"},{"t":"친구 다 — 「곰팡이, 버섯, 세균이 분해자야.」","mis":"SC4-2-u2-X18"}],"explanation":["분해자를 떠올려요.","분해자도 생물이에요.","친구 가가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u2_L03_challenge#4','sci',4,2,'u2','L03','g4_2_sci_u2_L03_challenge','lesson_challenge','SC4-2-u2-C13',3,'mc','auto','버섯을 생산자로 잘못 생각하기 쉬운 까닭은 무엇인가요?',ARRAY['SC4-2-u2-X18','SC4-2-u2-X15','SC4-2-u2-X16']::text[],false,'{"seq":4,"concept":"SC4-2-u2-C13","difficulty":3,"kind":"mc","stem":"버섯을 생산자로 잘못 생각하기 쉬운 까닭은 무엇인가요?","options":[{"t":"생김새가 식물과 비슷하고 나물처럼 무쳐 먹기도 하기 때문에","correct":true},{"t":"햇빛이 잘 드는 곳에서만 자라기 때문에","mis":"SC4-2-u2-X18"},{"t":"다른 생물을 잡아먹기 때문에","mis":"SC4-2-u2-X15"},{"t":"살아 있지 않은 것이기 때문에","mis":"SC4-2-u2-X16"}],"explanation":["버섯의 생김새를 떠올려요.","식물처럼 보여요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u2_L03_challenge#5','sci',4,2,'u2','L03','g4_2_sci_u2_L03_challenge','lesson_challenge','SC4-2-u2-C12',3,'mc','auto','분해자가 없다면 생태계에 어떤 일이 생길지 가장 알맞은 것은 무엇인가요?',ARRAY['SC4-2-u2-X17','SC4-2-u2-X15']::text[],false,'{"seq":5,"concept":"SC4-2-u2-C12","difficulty":3,"kind":"mc","stem":"분해자가 없다면 생태계에 어떤 일이 생길지 가장 알맞은 것은 무엇인가요?","options":[{"t":"죽은 몸이나 배출물이 분해되지 않아 생산자가 이용할 물질이 생기지 않는다","correct":true},{"t":"생산자가 더 많이 자란다","mis":"SC4-2-u2-X17"},{"t":"아무 일도 생기지 않는다","mis":"SC4-2-u2-X17"},{"t":"소비자가 스스로 양분을 만들게 된다","mis":"SC4-2-u2-X15"}],"explanation":["분해자가 하는 일을 떠올려요.","분해한 물질을 생산자가 써요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u2_L03_challenge#6','sci',4,2,'u2','L03','g4_2_sci_u2_L03_challenge','lesson_challenge','SC4-2-u2-C9',3,'ox','auto','생물요소는 사는 곳이 같으면 모두 같은 무리에 들어가요.',ARRAY['SC4-2-u2-X13']::text[],false,'{"seq":6,"concept":"SC4-2-u2-C9","difficulty":3,"kind":"ox","stem":"생물요소는 사는 곳이 같으면 모두 같은 무리에 들어가요.","answer":"X","reason_options":[{"t":"생물요소는 사는 곳이 아니라 양분을 얻는 방법, 곧 하는 역할에 따라 나누기 때문에","correct":true},{"t":"같은 곳에 사는 생물은 하는 일도 모두 같기 때문에","mis":"SC4-2-u2-X13"}],"mis":"SC4-2-u2-X13","explanation":["어항 속 생물을 떠올려요.","같은 곳에도 세 무리가 있어요.","그래서 X예요."],"asset":{"type":"passage","lines":["검정말 — 햇빛을 이용하여 스스로 양분을 만들어요.","생이새우 — 다른 생물을 먹어요.","물곰팡이 — 죽은 생물을 분해해요."],"title":"어항 속 생물"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u2_L03_challenge#7','sci',4,2,'u2','L03','g4_2_sci_u2_L03_challenge','lesson_challenge','SC4-2-u2-C10',3,'mc','auto','생물 카드 뒷면의 표에서 ㉠과 ㉢에 해당하는 생물을 차례대로 묶은 것은 무엇인가요?',ARRAY['SC4-2-u2-X17','SC4-2-u2-X14','SC4-2-u2-X15']::text[],false,'{"seq":7,"concept":"SC4-2-u2-C10","difficulty":3,"kind":"mc","stem":"생물 카드 뒷면의 표에서 ㉠과 ㉢에 해당하는 생물을 차례대로 묶은 것은 무엇인가요?","options":[{"t":"강아지풀, 세균","correct":true},{"t":"세균, 강아지풀","mis":"SC4-2-u2-X17"},{"t":"메뚜기, 세균","mis":"SC4-2-u2-X14"},{"t":"강아지풀, 고래","mis":"SC4-2-u2-X15"}],"explanation":["㉠은 만들고 ㉢은 분해해요.","식물과 아주 작은 생물이에요.","강아지풀, 세균이에요."],"asset":{"type":"passage","lines":["㉠ 햇빛을 이용하여 스스로 양분을 만들어요.","㉡ 다른 생물을 먹어 양분을 얻어요.","㉢ 죽은 몸이나 배출물을 분해하여 양분을 얻어요."],"title":"생물 카드 뒷면의 표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u2_L03_challenge#8','sci',4,2,'u2','L03','g4_2_sci_u2_L03_challenge','lesson_challenge','SC4-2-u2-C13',4,'mc','auto','친구가 「버섯은 나물처럼 먹으니까 식물이고, 그래서 생산자야.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?',ARRAY['SC4-2-u2-X18','SC4-2-u2-X16','SC4-2-u2-X15']::text[],false,'{"seq":8,"concept":"SC4-2-u2-C13","difficulty":4,"kind":"mc","stem":"친구가 「버섯은 나물처럼 먹으니까 식물이고, 그래서 생산자야.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?","options":[{"t":"「버섯은 식물과 다른 생물이야. 스스로 양분을 만들지 못하고 죽은 몸이나 배출물을 분해해 양분을 얻는 분해자야.」","correct":true},{"t":"「맞아, 먹을 수 있으면 모두 생산자야.」","mis":"SC4-2-u2-X18"},{"t":"「버섯은 살아 있지 않아서 어느 무리에도 들지 않아.」","mis":"SC4-2-u2-X16"},{"t":"「버섯은 다른 생물을 잡아먹는 소비자야.」","mis":"SC4-2-u2-X15"}],"explanation":["양분을 얻는 방법을 봐요.","생김새로 나누지 않아요.","첫 번째가 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u2_L03_challenge#9','sci',4,2,'u2','L03','g4_2_sci_u2_L03_challenge','lesson_challenge','SC4-2-u2-C9',4,'mc','auto','친구가 「생물 이름을 다 외워야 어느 무리인지 정할 수 있어.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?',ARRAY['SC4-2-u2-X09','SC4-2-u2-X13']::text[],false,'{"seq":9,"concept":"SC4-2-u2-C9","difficulty":4,"kind":"mc","stem":"친구가 「생물 이름을 다 외워야 어느 무리인지 정할 수 있어.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?","options":[{"t":"「처음 보는 생물도 양분을 어떻게 얻는지 알아보면 어느 무리인지 정할 수 있어.」","correct":true},{"t":"「맞아, 이름을 모르면 나눌 수 없어.」","mis":"SC4-2-u2-X09"},{"t":"「크기가 큰 생물은 모두 소비자야.」","mis":"SC4-2-u2-X13"},{"t":"「물속에 살면 모두 분해자야.」","mis":"SC4-2-u2-X13"}],"explanation":["나누는 기준을 떠올려요.","양분을 얻는 방법이에요.","첫 번째가 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u2_L03_challenge#10','sci',4,2,'u2','L03','g4_2_sci_u2_L03_challenge','lesson_challenge','SC4-2-u2-C9',4,'essay','teacher','생산자, 소비자, 분해자가 양분을 얻는 방법을 각각 쓰고, 무리마다 생물의 예를 하나씩 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC4-2-u2-C9","difficulty":4,"kind":"essay","stem":"생산자, 소비자, 분해자가 양분을 얻는 방법을 각각 쓰고, 무리마다 생물의 예를 하나씩 쓰세요.","answer_guide":{"answer":"예: 생산자는 햇빛을 이용하여 스스로 양분을 만든다(소나무). 소비자는 생산자 또는 다른 생물을 먹어 양분을 얻는다(메뚜기). 분해자는 죽은 몸이나 배출물을 분해하여 양분을 얻는다(곰팡이).","scoring_points":["생산자의 방법과 예를 썼는가","소비자의 방법과 예를 썼는가","분해자의 방법과 예를 썼는가"]},"explanation":["세 무리를 떠올려요.","양분을 얻는 방법을 써요.","예를 하나씩 들어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u2_L04_basic#1','sci',4,2,'u2','L04','g4_2_sci_u2_L04_basic','lesson_basic','SC4-2-u2-C14',1,'mc','auto','생물 사이의 먹이 관계가 사슬처럼 연결되어 있는 것을 무엇이라고 하나요?',ARRAY['SC4-2-u2-X21']::text[],false,'{"seq":1,"concept":"SC4-2-u2-C14","difficulty":1,"kind":"mc","stem":"생물 사이의 먹이 관계가 사슬처럼 연결되어 있는 것을 무엇이라고 하나요?","options":[{"t":"먹이사슬","correct":true},{"t":"먹이그물","mis":"SC4-2-u2-X21"},{"t":"생태계","mis":"SC4-2-u2-X21"},{"t":"생물요소","mis":"SC4-2-u2-X21"}],"explanation":["사슬처럼 이어져요.","한 줄로 연결돼요.","먹이사슬이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u2_L04_basic#2','sci',4,2,'u2','L04','g4_2_sci_u2_L04_basic','lesson_basic','SC4-2-u2-C14',1,'sa','auto','숲 생태계의 먹이사슬에서 개구리를 먹는 생물을 한 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SC4-2-u2-C14","difficulty":1,"kind":"sa","stem":"숲 생태계의 먹이사슬에서 개구리를 먹는 생물을 한 글자로 쓰세요.","answer":["뱀"],"explanation":["개구리 다음을 봐요.","화살표가 가리켜요.","뱀이에요."],"asset":{"type":"passage","lines":["벼 → 메뚜기 → 개구리 → 뱀 → 새매"],"title":"숲 생태계의 먹이사슬"},"mis":"SC4-2-u2-X20"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u2_L04_basic#3','sci',4,2,'u2','L04','g4_2_sci_u2_L04_basic','lesson_basic','SC4-2-u2-C18',1,'ox','auto','셀로판테이프를 자를 때에는 날카로운 부분에 손을 다치지 않도록 조심해요.',ARRAY['SC4-2-u2-X26']::text[],false,'{"seq":3,"concept":"SC4-2-u2-C18","difficulty":1,"kind":"ox","stem":"셀로판테이프를 자를 때에는 날카로운 부분에 손을 다치지 않도록 조심해요.","answer":"O","reason_options":[{"t":"셀로판테이프 날은 날카로워 손을 다칠 수 있기 때문에","correct":true},{"t":"셀로판테이프는 아무렇게나 만져도 안전하기 때문에","mis":"SC4-2-u2-X26"}],"mis":"SC4-2-u2-X26","explanation":["안전을 떠올려요.","날은 날카로워요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u2_L04_basic#4','sci',4,2,'u2','L04','g4_2_sci_u2_L04_basic','lesson_basic','SC4-2-u2-C15',1,'mc','auto','다양한 먹이사슬이 그물처럼 복잡하게 연결되어 있는 것을 무엇이라고 하나요?',ARRAY['SC4-2-u2-X21']::text[],false,'{"seq":4,"concept":"SC4-2-u2-C15","difficulty":1,"kind":"mc","stem":"다양한 먹이사슬이 그물처럼 복잡하게 연결되어 있는 것을 무엇이라고 하나요?","options":[{"t":"먹이그물","correct":true},{"t":"먹이사슬","mis":"SC4-2-u2-X21"},{"t":"화살표","mis":"SC4-2-u2-X21"},{"t":"분류","mis":"SC4-2-u2-X21"}],"explanation":["그물처럼 얽혀요.","여러 사슬이 모여요.","먹이그물이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u2_L04_basic#5','sci',4,2,'u2','L04','g4_2_sci_u2_L04_basic','lesson_basic','SC4-2-u2-C14',2,'mc','auto','먹고 먹히는 관계를 화살표로 나타내는 방법으로 알맞은 것은 무엇인가요?',ARRAY['SC4-2-u2-X20','SC4-2-u2-X25']::text[],false,'{"seq":5,"concept":"SC4-2-u2-C14","difficulty":2,"kind":"mc","stem":"먹고 먹히는 관계를 화살표로 나타내는 방법으로 알맞은 것은 무엇인가요?","options":[{"t":"잡아먹히는 생물로부터 잡아먹는 생물 방향으로 그린다","correct":true},{"t":"잡아먹는 생물로부터 잡아먹히는 생물 방향으로 그린다","mis":"SC4-2-u2-X20"},{"t":"몸집이 큰 생물부터 작은 생물 방향으로 그린다","mis":"SC4-2-u2-X25"},{"t":"방향은 아무렇게나 그려도 된다","mis":"SC4-2-u2-X20"}],"explanation":["벼 → 메뚜기를 봐요.","먹히는 쪽에서 시작해요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u2_L04_basic#6','sci',4,2,'u2','L04','g4_2_sci_u2_L04_basic','lesson_basic','SC4-2-u2-C15',2,'match','auto','숲 그림판 위의 먹이그물 모형 일부를 보고 생물과 그 생물이 먹는 것을 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"SC4-2-u2-C15","difficulty":2,"kind":"match","stem":"숲 그림판 위의 먹이그물 모형 일부를 보고 생물과 그 생물이 먹는 것을 알맞게 이으세요.","pairs":[{"l":"메뚜기","r":"강아지풀"},{"l":"다람쥐","r":"도토리"},{"l":"직박구리","r":"메뚜기"}],"mis":"SC4-2-u2-X22","explanation":["모형을 읽어요.","먹는 것을 찾아요.","메뚜기-강아지풀, 다람쥐-도토리, 직박구리-메뚜기예요."],"asset":{"type":"passage","lines":["메뚜기가 먹는 것 — 벼, 강아지풀, 질경이","메뚜기를 먹는 것 — 개구리, 직박구리","다람쥐가 먹는 것 — 도토리"],"title":"숲 그림판 위의 먹이그물 모형 일부"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u2_L04_basic#7','sci',4,2,'u2','L04','g4_2_sci_u2_L04_basic','lesson_basic','SC4-2-u2-C15',2,'mc','auto','메뚜기에 대해 바르게 말한 것은 무엇인가요?',ARRAY['SC4-2-u2-X22']::text[],false,'{"seq":7,"concept":"SC4-2-u2-C15","difficulty":2,"kind":"mc","stem":"메뚜기에 대해 바르게 말한 것은 무엇인가요?","options":[{"t":"메뚜기는 벼만 먹지 않고 다른 풀도 먹는다","correct":true},{"t":"메뚜기는 벼 한 가지만 먹는다","mis":"SC4-2-u2-X22"},{"t":"메뚜기는 개구리에게만 먹힌다","mis":"SC4-2-u2-X22"},{"t":"메뚜기는 아무것도 먹지 않는다","mis":"SC4-2-u2-X22"}],"explanation":["먹이그물 모형을 떠올려요.","먹는 것이 여럿이에요.","첫 번째예요."],"asset":{"type":"passage","lines":["메뚜기가 먹는 것 — 벼, 강아지풀, 질경이","메뚜기를 먹는 것 — 개구리, 직박구리","다람쥐가 먹는 것 — 도토리"],"title":"숲 그림판 위의 먹이그물 모형 일부"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u2_L04_basic#8','sci',4,2,'u2','L04','g4_2_sci_u2_L04_basic','lesson_basic','SC4-2-u2-C14',2,'ox','auto','먹이사슬과 먹이그물은 이름만 다를 뿐 같은 것이에요.',ARRAY['SC4-2-u2-X21']::text[],false,'{"seq":8,"concept":"SC4-2-u2-C14","difficulty":2,"kind":"ox","stem":"먹이사슬과 먹이그물은 이름만 다를 뿐 같은 것이에요.","answer":"X","reason_options":[{"t":"먹이사슬은 한 줄로 이어지고 먹이그물은 여러 먹이사슬이 그물처럼 얽혀 있기 때문에","correct":true},{"t":"둘 다 먹고 먹히는 관계를 나타내므로 같은 것이기 때문에","mis":"SC4-2-u2-X21"}],"mis":"SC4-2-u2-X21","explanation":["사슬과 그물을 떠올려요.","모양이 달라요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u2_L04_basic#9','sci',4,2,'u2','L04','g4_2_sci_u2_L04_basic','lesson_basic','SC4-2-u2-C18',2,'mc','auto','먹이사슬 놀이에서 가장 작은 종이컵에 그리는 생물로 알맞은 것은 무엇인가요?',ARRAY['SC4-2-u2-X20']::text[],false,'{"seq":9,"concept":"SC4-2-u2-C18","difficulty":2,"kind":"mc","stem":"먹이사슬 놀이에서 가장 작은 종이컵에 그리는 생물로 알맞은 것은 무엇인가요?","options":[{"t":"토끼풀","correct":true},{"t":"토끼","mis":"SC4-2-u2-X20"},{"t":"여우","mis":"SC4-2-u2-X20"},{"t":"호랑이","mis":"SC4-2-u2-X20"}],"explanation":["먹이사슬의 처음을 떠올려요.","먹히기만 하는 식물이에요.","토끼풀이에요."],"asset":{"type":"passage","lines":["① 크기가 같은 종이컵끼리 입구를 마주 보게 하여 한쪽만 이어요.","② 먹고 먹히는 관계를 생각하며 크기 순서대로 생물을 그려요.","③ 작은 컵부터 다음 컵에 넣고 닫은 뒤 하나씩 열어 봐요.","④ 놀이 말을 숲 그림판에 올리고 화살표를 그려 모형을 완성해요."],"title":"먹이사슬 놀이와 먹이그물 모형"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u2_L04_basic#10','sci',4,2,'u2','L04','g4_2_sci_u2_L04_basic','lesson_basic','SC4-2-u2-C16',3,'mc','auto','먹이그물 모형에서 메뚜기가 사라지면 벼는 어떻게 될까요?',ARRAY['SC4-2-u2-X23','SC4-2-u2-X22']::text[],false,'{"seq":10,"concept":"SC4-2-u2-C16","difficulty":3,"kind":"mc","stem":"먹이그물 모형에서 메뚜기가 사라지면 벼는 어떻게 될까요?","options":[{"t":"메뚜기에게 먹히지 않으므로 일시적으로 그 수가 늘어난다","correct":true},{"t":"메뚜기와 함께 바로 모두 사라진다","mis":"SC4-2-u2-X23"},{"t":"일시적으로 그 수가 줄어든다","mis":"SC4-2-u2-X23"},{"t":"벼는 메뚜기와 관계가 없어 아무 변화가 없다","mis":"SC4-2-u2-X22"}],"explanation":["벼를 먹던 생물이 사라졌어요.","먹히는 일이 줄어요.","일시적으로 늘어나요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u2_L04_challenge#1','sci',4,2,'u2','L04','g4_2_sci_u2_L04_challenge','lesson_challenge','SC4-2-u2-C16',2,'blank','auto','「먹이 관계가 단순한 경우보다 (    )할수록 생태계가 큰 변화 없이 유지될 수 있어요.」 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SC4-2-u2-X24','SC4-2-u2-X25']::text[],false,'{"seq":1,"concept":"SC4-2-u2-C16","difficulty":2,"kind":"blank","stem":"「먹이 관계가 단순한 경우보다 (    )할수록 생태계가 큰 변화 없이 유지될 수 있어요.」 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"복잡","correct":true},{"t":"단순","mis":"SC4-2-u2-X24"},{"t":"조용","mis":"SC4-2-u2-X24"},{"t":"작게","mis":"SC4-2-u2-X25"}],"explanation":["먹이그물을 떠올려요.","얽혀 있을수록 좋아요.","복잡이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u2_L04_challenge#2','sci',4,2,'u2','L04','g4_2_sci_u2_L04_challenge','lesson_challenge','SC4-2-u2-C17',2,'mc','auto','스라소니와 여우에 대해 바르게 말한 것은 무엇인가요?',ARRAY['SC4-2-u2-X22','SC4-2-u2-X25']::text[],false,'{"seq":2,"concept":"SC4-2-u2-C17","difficulty":2,"kind":"mc","stem":"스라소니와 여우에 대해 바르게 말한 것은 무엇인가요?","options":[{"t":"둘 다 토끼를 잡아먹지만 서로 잡아먹는 관계는 아니다","correct":true},{"t":"스라소니는 여우만 잡아먹는다","mis":"SC4-2-u2-X22"},{"t":"여우는 토끼를 먹지 않는다","mis":"SC4-2-u2-X22"},{"t":"몸집이 큰 쪽이 늘 작은 쪽을 잡아먹는다","mis":"SC4-2-u2-X25"}],"explanation":["셋의 관계를 떠올려요.","둘 다 토끼를 먹어요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u2_L04_challenge#3','sci',4,2,'u2','L04','g4_2_sci_u2_L04_challenge','lesson_challenge','SC4-2-u2-C16',3,'error','auto','먹이그물 모형에서 메뚜기가 사라지면 어떻게 될지 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC4-2-u2-X23','SC4-2-u2-X22','SC4-2-u2-X24']::text[],false,'{"seq":3,"concept":"SC4-2-u2-C16","difficulty":3,"kind":"error","stem":"먹이그물 모형에서 메뚜기가 사라지면 어떻게 될지 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 나 — 「먹이그물에 있는 생물이 모두 한꺼번에 사라질 거야.」","correct":true,"mis_target":"SC4-2-u2-X23"},{"t":"친구 가 — 「메뚜기를 먹던 개구리는 일시적으로 줄어들 거야.」","mis":"SC4-2-u2-X22"},{"t":"친구 다 — 「도토리를 먹는 다람쥐는 크게 변하지 않을 거야.」","mis":"SC4-2-u2-X24"}],"explanation":["직접 관계를 따져요.","모두 사라지지 않아요.","친구 나가 잘못 말했어요."],"asset":{"type":"passage","lines":["메뚜기가 먹는 것 — 벼, 강아지풀, 질경이","메뚜기를 먹는 것 — 개구리, 직박구리","다람쥐가 먹는 것 — 도토리"],"title":"숲 그림판 위의 먹이그물 모형 일부"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u2_L04_challenge#4','sci',4,2,'u2','L04','g4_2_sci_u2_L04_challenge','lesson_challenge','SC4-2-u2-C17',3,'mc','auto','골리앗타이거피시 이야기로 알 수 있는 것은 무엇인가요?',ARRAY['SC4-2-u2-X25','SC4-2-u2-X22']::text[],false,'{"seq":4,"concept":"SC4-2-u2-C17","difficulty":3,"kind":"mc","stem":"골리앗타이거피시 이야기로 알 수 있는 것은 무엇인가요?","options":[{"t":"물고기가 새를 잡아먹기도 하듯 먹고 먹히는 관계가 반대로 연결되는 경우도 있다","correct":true},{"t":"몸집이 큰 생물만 다른 생물을 먹는다","mis":"SC4-2-u2-X25"},{"t":"새는 언제나 물고기를 잡아먹는다","mis":"SC4-2-u2-X25"},{"t":"물고기는 다른 생물을 먹지 않는다","mis":"SC4-2-u2-X22"}],"explanation":["물 위로 뛰어올라 새를 낚아채요.","새가 물고기를 먹는 것과 반대예요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u2_L04_challenge#5','sci',4,2,'u2','L04','g4_2_sci_u2_L04_challenge','lesson_challenge','SC4-2-u2-C15',3,'mc','auto','먹이사슬과 먹이그물을 바르게 나눈 것은 무엇인가요?',ARRAY['SC4-2-u2-X21','SC4-2-u2-X22']::text[],false,'{"seq":5,"concept":"SC4-2-u2-C15","difficulty":3,"kind":"mc","stem":"먹이사슬과 먹이그물을 바르게 나눈 것은 무엇인가요?","options":[{"t":"먹이사슬 — 벼 → 메뚜기 → 개구리처럼 한 줄 / 먹이그물 — 메뚜기가 여러 풀을 먹고 여러 생물에게 먹히는 것","correct":true},{"t":"먹이사슬 — 여러 줄이 얽힌 것 / 먹이그물 — 한 줄로 이어진 것","mis":"SC4-2-u2-X21"},{"t":"먹이사슬과 먹이그물 모두 한 줄로만 이어진 것","mis":"SC4-2-u2-X21"},{"t":"먹이사슬 — 식물만 / 먹이그물 — 동물만","mis":"SC4-2-u2-X22"}],"explanation":["사슬은 한 줄이에요.","그물은 여럿이 얽혀요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u2_L04_challenge#6','sci',4,2,'u2','L04','g4_2_sci_u2_L04_challenge','lesson_challenge','SC4-2-u2-C16',3,'ox','auto','먹이그물에서 메뚜기가 사라지면 메뚜기를 잡아먹던 개구리는 일시적으로 그 수가 늘어나요.',ARRAY['SC4-2-u2-X23']::text[],false,'{"seq":6,"concept":"SC4-2-u2-C16","difficulty":3,"kind":"ox","stem":"먹이그물에서 메뚜기가 사라지면 메뚜기를 잡아먹던 개구리는 일시적으로 그 수가 늘어나요.","answer":"X","reason_options":[{"t":"먹이인 메뚜기가 줄어들어 개구리는 일시적으로 그 수가 줄어들기 때문에","correct":true},{"t":"먹이가 사라지면 먹던 생물은 늘 더 많아지기 때문에","mis":"SC4-2-u2-X23"}],"mis":"SC4-2-u2-X23","explanation":["개구리의 먹이를 떠올려요.","먹이가 줄었어요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u2_L04_challenge#7','sci',4,2,'u2','L04','g4_2_sci_u2_L04_challenge','lesson_challenge','SC4-2-u2-C18',3,'mc','auto','먹이그물 모형을 만들 때 알맞은 행동은 무엇인가요?',ARRAY['SC4-2-u2-X26','SC4-2-u2-X20']::text[],false,'{"seq":7,"concept":"SC4-2-u2-C18","difficulty":3,"kind":"mc","stem":"먹이그물 모형을 만들 때 알맞은 행동은 무엇인가요?","options":[{"t":"숲 그림판 모서리에 손을 다치지 않게 조심하며 놀이 말 사이에 화살표를 그린다","correct":true},{"t":"그림판을 모서리가 손에 닿든 말든 휙 잡아당긴다","mis":"SC4-2-u2-X26"},{"t":"놀이 말을 아무 곳에나 두고 화살표는 그리지 않는다","mis":"SC4-2-u2-X20"},{"t":"화살표를 먹는 생물에서 먹히는 생물 쪽으로 그린다","mis":"SC4-2-u2-X20"}],"explanation":["④를 읽어요.","안전과 화살표 방향이에요.","첫 번째예요."],"asset":{"type":"passage","lines":["① 크기가 같은 종이컵끼리 입구를 마주 보게 하여 한쪽만 이어요.","② 먹고 먹히는 관계를 생각하며 크기 순서대로 생물을 그려요.","③ 작은 컵부터 다음 컵에 넣고 닫은 뒤 하나씩 열어 봐요.","④ 놀이 말을 숲 그림판에 올리고 화살표를 그려 모형을 완성해요."],"title":"먹이사슬 놀이와 먹이그물 모형"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u2_L04_challenge#8','sci',4,2,'u2','L04','g4_2_sci_u2_L04_challenge','lesson_challenge','SC4-2-u2-C16',4,'mc','auto','숲 생태계에서 여러 먹이사슬이 얽혀 있으면 생물이 살아가기에 어떤 점이 좋은가요?',ARRAY['SC4-2-u2-X22','SC4-2-u2-X25','SC4-2-u2-X24']::text[],false,'{"seq":8,"concept":"SC4-2-u2-C16","difficulty":4,"kind":"mc","stem":"숲 생태계에서 여러 먹이사슬이 얽혀 있으면 생물이 살아가기에 어떤 점이 좋은가요?","options":[{"t":"한 종류의 생물 수가 갑자기 늘거나 줄어도 다른 생물을 먹이로 먹을 수 있다","correct":true},{"t":"먹이를 먹지 않고도 살 수 있다","mis":"SC4-2-u2-X22"},{"t":"몸집이 큰 생물만 살아남는다","mis":"SC4-2-u2-X25"},{"t":"먹이사슬이 한 줄로만 이어져 찾기 쉽다","mis":"SC4-2-u2-X24"}],"explanation":["강아지풀이 사라졌다고 해 봐요.","메뚜기는 질경이를 먹어요.","첫 번째예요."],"asset":{"type":"passage","lines":["메뚜기가 먹는 것 — 벼, 강아지풀, 질경이","메뚜기를 먹는 것 — 개구리, 직박구리","다람쥐가 먹는 것 — 도토리"],"title":"숲 그림판 위의 먹이그물 모형 일부"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u2_L04_challenge#9','sci',4,2,'u2','L04','g4_2_sci_u2_L04_challenge','lesson_challenge','SC4-2-u2-C14',4,'mc','auto','「새매 → 뱀 → 개구리 → 메뚜기 → 벼」라고 쓴 친구에게 가장 알맞게 말한 것은 무엇인가요?',ARRAY['SC4-2-u2-X25','SC4-2-u2-X20','SC4-2-u2-X21']::text[],false,'{"seq":9,"concept":"SC4-2-u2-C14","difficulty":4,"kind":"mc","stem":"「새매 → 뱀 → 개구리 → 메뚜기 → 벼」라고 쓴 친구에게 가장 알맞게 말한 것은 무엇인가요?","options":[{"t":"「화살표는 잡아먹히는 생물에서 잡아먹는 생물 쪽으로 그려. 벼 → 메뚜기 → 개구리 → 뱀 → 새매로 고쳐야 해.」","correct":true},{"t":"「잘 썼어. 큰 생물부터 쓰면 돼.」","mis":"SC4-2-u2-X25"},{"t":"「먹이사슬은 화살표 없이 이름만 쓰는 거야.」","mis":"SC4-2-u2-X20"},{"t":"「이건 먹이그물이라서 방향이 거꾸로야.」","mis":"SC4-2-u2-X21"}],"explanation":["화살표 방향을 떠올려요.","먹히는 생물에서 시작해요.","첫 번째가 알맞아요."],"asset":{"type":"passage","lines":["벼 → 메뚜기 → 개구리 → 뱀 → 새매"],"title":"숲 생태계의 먹이사슬"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u2_L04_challenge#10','sci',4,2,'u2','L04','g4_2_sci_u2_L04_challenge','lesson_challenge','SC4-2-u2-C15',4,'essay','teacher','먹이사슬과 먹이그물의 뜻을 각각 쓰고, 먹이 관계가 복잡할수록 생태계가 큰 변화 없이 유지되는 까닭을 메뚜기를 예로 들어 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC4-2-u2-C15","difficulty":4,"kind":"essay","stem":"먹이사슬과 먹이그물의 뜻을 각각 쓰고, 먹이 관계가 복잡할수록 생태계가 큰 변화 없이 유지되는 까닭을 메뚜기를 예로 들어 쓰세요.","answer_guide":{"answer":"예: 먹이사슬은 생물 사이의 먹이 관계가 사슬처럼 연결되어 있는 것이고, 먹이그물은 다양한 먹이사슬이 그물처럼 복잡하게 연결되어 있는 것이다. 메뚜기는 강아지풀이 사라져도 질경이를 먹을 수 있듯이, 한 종류의 생물 수가 변해도 다른 생물을 먹이로 먹을 수 있기 때문이다.","scoring_points":["먹이사슬의 뜻을 썼는가","먹이그물의 뜻을 썼는가","복잡할수록 유지되는 까닭을 예를 들어 썼는가"]},"explanation":["두 뜻을 써요.","메뚜기의 먹이를 떠올려요.","까닭을 써요."],"asset":{"type":"passage","lines":["메뚜기가 먹는 것 — 벼, 강아지풀, 질경이","메뚜기를 먹는 것 — 개구리, 직박구리","다람쥐가 먹는 것 — 도토리"],"title":"숲 그림판 위의 먹이그물 모형 일부"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u2_L05_basic#1','sci',4,2,'u2','L05','g4_2_sci_u2_L05_basic','lesson_basic','SC4-2-u2-C19',1,'mc','auto','자연 생태계나 주변이 인간 활동으로 훼손되고 더럽혀지는 현상을 무엇이라고 하나요?',ARRAY['SC4-2-u2-X27']::text[],false,'{"seq":1,"concept":"SC4-2-u2-C19","difficulty":1,"kind":"mc","stem":"자연 생태계나 주변이 인간 활동으로 훼손되고 더럽혀지는 현상을 무엇이라고 하나요?","options":[{"t":"환경오염","correct":true},{"t":"생태계","mis":"SC4-2-u2-X27"},{"t":"생태계보전","mis":"SC4-2-u2-X27"},{"t":"분리배출","mis":"SC4-2-u2-X27"}],"explanation":["더럽혀지는 현상이에요.","사람이 하는 일 때문이에요.","환경오염이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u2_L05_basic#2','sci',4,2,'u2','L05','g4_2_sci_u2_L05_basic','lesson_basic','SC4-2-u2-C20',1,'sa','auto','원인과 관련 있는 환경오염에서 ㉡에 알맞은 환경오염을 네 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SC4-2-u2-C20","difficulty":1,"kind":"sa","stem":"원인과 관련 있는 환경오염에서 ㉡에 알맞은 환경오염을 네 글자로 쓰세요.","answer":["토양오염","토양 오염"],"explanation":["넷째 줄을 읽어요.","쓰레기를 땅에 묻어요.","토양오염이에요."],"asset":{"type":"passage","lines":["자동차에서 나오는 배기가스 — 대기오염, ㉠","바닷물에 섞여 있는 쓰레기 — 수질오염","논밭에 사용하는 농약 — 토양오염, 수질오염","생활 쓰레기의 매립 — ㉡"],"title":"원인과 관련 있는 환경오염"},"mis":"SC4-2-u2-X29"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u2_L05_basic#3','sci',4,2,'u2','L05','g4_2_sci_u2_L05_basic','lesson_basic','SC4-2-u2-C23',1,'ox','auto','누리망에서 환경오염을 조사할 때에는 정보의 출처를 확인해요.',ARRAY['SC4-2-u2-X33']::text[],false,'{"seq":3,"concept":"SC4-2-u2-C23","difficulty":1,"kind":"ox","stem":"누리망에서 환경오염을 조사할 때에는 정보의 출처를 확인해요.","answer":"O","reason_options":[{"t":"옳은 정보와 거짓 정보를 구분해야 하기 때문에","correct":true},{"t":"누리망의 정보는 모두 옳기 때문에","mis":"SC4-2-u2-X33"}],"mis":"SC4-2-u2-X33","explanation":["조사할 때를 떠올려요.","거짓 정보도 있어요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u2_L05_basic#4','sci',4,2,'u2','L05','g4_2_sci_u2_L05_basic','lesson_basic','SC4-2-u2-C19',1,'mc','auto','생물이 숨 쉬는 것을 힘들게 만드는 환경오염은 무엇인가요?',ARRAY['SC4-2-u2-X29','SC4-2-u2-X27']::text[],false,'{"seq":4,"concept":"SC4-2-u2-C19","difficulty":1,"kind":"mc","stem":"생물이 숨 쉬는 것을 힘들게 만드는 환경오염은 무엇인가요?","options":[{"t":"대기오염","correct":true},{"t":"수질오염","mis":"SC4-2-u2-X29"},{"t":"토양오염","mis":"SC4-2-u2-X29"},{"t":"분리배출","mis":"SC4-2-u2-X27"}],"explanation":["숨 쉬는 공기를 떠올려요.","공기가 더러워져요.","대기오염이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u2_L05_basic#5','sci',4,2,'u2','L05','g4_2_sci_u2_L05_basic','lesson_basic','SC4-2-u2-C20',2,'mc','auto','원인과 관련 있는 환경오염에서 ㉠에 알맞은 것은 무엇인가요?',ARRAY['SC4-2-u2-X29','SC4-2-u2-X28','SC4-2-u2-X27']::text[],false,'{"seq":5,"concept":"SC4-2-u2-C20","difficulty":2,"kind":"mc","stem":"원인과 관련 있는 환경오염에서 ㉠에 알맞은 것은 무엇인가요?","options":[{"t":"수질오염","correct":true},{"t":"토양오염","mis":"SC4-2-u2-X29"},{"t":"없음","mis":"SC4-2-u2-X28"},{"t":"분리배출","mis":"SC4-2-u2-X27"}],"explanation":["첫째 줄을 읽어요.","배기가스는 둘과 관련 있어요.","수질오염이에요."],"asset":{"type":"passage","lines":["자동차에서 나오는 배기가스 — 대기오염, ㉠","바닷물에 섞여 있는 쓰레기 — 수질오염","논밭에 사용하는 농약 — 토양오염, 수질오염","생활 쓰레기의 매립 — ㉡"],"title":"원인과 관련 있는 환경오염"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u2_L05_basic#6','sci',4,2,'u2','L05','g4_2_sci_u2_L05_basic','lesson_basic','SC4-2-u2-C22',2,'mc','auto','생태계보전을 위한 노력으로 알맞은 것은 무엇인가요?',ARRAY['SC4-2-u2-X31']::text[],false,'{"seq":6,"concept":"SC4-2-u2-C22","difficulty":2,"kind":"mc","stem":"생태계보전을 위한 노력으로 알맞은 것은 무엇인가요?","options":[{"t":"일회용품 사용을 줄이고 쓰레기를 분리배출한다","correct":true},{"t":"농약을 많이 사용한다","mis":"SC4-2-u2-X31"},{"t":"물은 얼마든지 써도 되니 샤워를 오래 한다","mis":"SC4-2-u2-X31"},{"t":"가까운 거리도 늘 자동차로 다닌다","mis":"SC4-2-u2-X31"}],"explanation":["오염 물질을 줄여요.","쓰레기를 줄여요.","첫 번째예요."],"asset":{"type":"passage","lines":["가까운 거리는 걸어가거나 자전거를 타요.","일회용품 사용을 줄이고 분리배출을 해요.","설거지할 때 세제를 적당한 양만 써요.","물티슈 대신에 손수건을 써요."],"title":"우리 모둠이 토의한 생태계보전 노력"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u2_L05_basic#7','sci',4,2,'u2','L05','g4_2_sci_u2_L05_basic','lesson_basic','SC4-2-u2-C20',2,'match','auto','원인과 관련 있는 환경오염을 알맞게 이으세요.','{}'::text[],false,'{"seq":7,"concept":"SC4-2-u2-C20","difficulty":2,"kind":"match","stem":"원인과 관련 있는 환경오염을 알맞게 이으세요.","pairs":[{"l":"바닷물에 섞여 있는 쓰레기","r":"수질오염"},{"l":"생활 쓰레기의 매립","r":"토양오염"},{"l":"자동차에서 나오는 미세 먼지","r":"대기오염"}],"mis":"SC4-2-u2-X29","explanation":["원인을 하나씩 떠올려요.","바다, 땅, 공기예요.","쓰레기-수질, 매립-토양, 미세 먼지-대기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u2_L05_basic#8','sci',4,2,'u2','L05','g4_2_sci_u2_L05_basic','lesson_basic','SC4-2-u2-C20',2,'ox','auto','환경오염을 일으키는 원인 하나는 반드시 한 가지 환경오염만 일으켜요.',ARRAY['SC4-2-u2-X28']::text[],false,'{"seq":8,"concept":"SC4-2-u2-C20","difficulty":2,"kind":"ox","stem":"환경오염을 일으키는 원인 하나는 반드시 한 가지 환경오염만 일으켜요.","answer":"X","reason_options":[{"t":"자동차 배기가스나 농약처럼 두 가지 환경오염과 관련 있는 원인도 있기 때문에","correct":true},{"t":"원인과 환경오염은 언제나 하나씩 짝지어지기 때문에","mis":"SC4-2-u2-X28"}],"mis":"SC4-2-u2-X28","explanation":["배기가스를 떠올려요.","두 가지와 관련 있어요.","그래서 X예요."],"asset":{"type":"passage","lines":["자동차에서 나오는 배기가스 — 대기오염, ㉠","바닷물에 섞여 있는 쓰레기 — 수질오염","논밭에 사용하는 농약 — 토양오염, 수질오염","생활 쓰레기의 매립 — ㉡"],"title":"원인과 관련 있는 환경오염"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u2_L05_basic#9','sci',4,2,'u2','L05','g4_2_sci_u2_L05_basic','lesson_basic','SC4-2-u2-C21',2,'mc','auto','주변 환경이 오염되면 생태계에 어떤 일이 생기나요?',ARRAY['SC4-2-u2-X30']::text[],false,'{"seq":9,"concept":"SC4-2-u2-C21","difficulty":2,"kind":"mc","stem":"주변 환경이 오염되면 생태계에 어떤 일이 생기나요?","options":[{"t":"생물이 숨 쉬기 어려워지고 생태계의 안정이 깨질 수 있다","correct":true},{"t":"생물의 수가 저절로 늘어난다","mis":"SC4-2-u2-X30"},{"t":"생태계에는 아무 영향이 없다","mis":"SC4-2-u2-X30"},{"t":"오염 물질이 곧바로 저절로 사라진다","mis":"SC4-2-u2-X30"}],"explanation":["오염된 공기와 물을 떠올려요.","생물이 살기 어려워져요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u2_L05_basic#10','sci',4,2,'u2','L05','g4_2_sci_u2_L05_basic','lesson_basic','SC4-2-u2-C20',3,'mc','auto','기름을 운반하는 배에서 기름이 흘러나와 바다나 강으로 퍼지면 어떤 환경오염이 생길까요?',ARRAY['SC4-2-u2-X29','SC4-2-u2-X30','SC4-2-u2-X27']::text[],false,'{"seq":10,"concept":"SC4-2-u2-C20","difficulty":3,"kind":"mc","stem":"기름을 운반하는 배에서 기름이 흘러나와 바다나 강으로 퍼지면 어떤 환경오염이 생길까요?","options":[{"t":"바다나 강이 오염되어 그곳 생물이 살기 어려워지는 수질오염","correct":true},{"t":"공기만 더러워지는 대기오염","mis":"SC4-2-u2-X29"},{"t":"기름은 곧 사라져 아무 오염도 생기지 않는다","mis":"SC4-2-u2-X30"},{"t":"사람이 한 일이 아니어서 환경오염이 아니다","mis":"SC4-2-u2-X27"}],"explanation":["기름이 어디로 퍼지나요?","바다나 강이에요.","수질오염이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u2_L05_challenge#1','sci',4,2,'u2','L05','g4_2_sci_u2_L05_challenge','lesson_challenge','SC4-2-u2-C22',2,'blank','auto','「생태계를 보전하려면 오염 물질의 양을 줄이고, 자연 개발과 생태계보전을 위한 노력 사이에 (    )을/를 이루어야 해요.」 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SC4-2-u2-X32','SC4-2-u2-X31']::text[],false,'{"seq":1,"concept":"SC4-2-u2-C22","difficulty":2,"kind":"blank","stem":"「생태계를 보전하려면 오염 물질의 양을 줄이고, 자연 개발과 생태계보전을 위한 노력 사이에 (    )을/를 이루어야 해요.」 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"균형","correct":true},{"t":"경쟁","mis":"SC4-2-u2-X32"},{"t":"차이","mis":"SC4-2-u2-X31"},{"t":"분리","mis":"SC4-2-u2-X31"}],"explanation":["개발과 보전을 견줘요.","어느 한쪽만이 아니에요.","균형이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u2_L05_challenge#2','sci',4,2,'u2','L05','g4_2_sci_u2_L05_challenge','lesson_challenge','SC4-2-u2-C21',2,'mc','auto','논밭에 농약을 지나치게 많이 써서 흙이 오염되면 어떤 일이 생기나요?',ARRAY['SC4-2-u2-X30','SC4-2-u2-X29']::text[],false,'{"seq":2,"concept":"SC4-2-u2-C21","difficulty":2,"kind":"mc","stem":"논밭에 농약을 지나치게 많이 써서 흙이 오염되면 어떤 일이 생기나요?","options":[{"t":"식물이 잘 자라지 못하고 흙 속 이로운 생물이 살기 어려워진다","correct":true},{"t":"식물이 더 잘 자란다","mis":"SC4-2-u2-X30"},{"t":"흙 속 생물이 더 많아진다","mis":"SC4-2-u2-X30"},{"t":"공기만 깨끗해진다","mis":"SC4-2-u2-X29"}],"explanation":["흙에 사는 생물을 떠올려요.","농약이 흙에 남아요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u2_L05_challenge#3','sci',4,2,'u2','L05','g4_2_sci_u2_L05_challenge','lesson_challenge','SC4-2-u2-C23',3,'error','auto','환경오염을 조사하며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC4-2-u2-X33','SC4-2-u2-X29','SC4-2-u2-X30']::text[],false,'{"seq":3,"concept":"SC4-2-u2-C23","difficulty":3,"kind":"error","stem":"환경오염을 조사하며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「누리망에 올라온 글이니까 어디서 왔는지 안 봐도 돼.」","correct":true,"mis_target":"SC4-2-u2-X33"},{"t":"친구 가 — 「우리 모둠은 배기가스에 의한 대기오염을 골랐어.」","mis":"SC4-2-u2-X29"},{"t":"친구 나 — 「쓰레기로 오염된 물을 마신 생물은 병에 걸릴 수 있어.」","mis":"SC4-2-u2-X30"}],"explanation":["조사할 때 지킬 것을 떠올려요.","출처를 확인해요.","친구 다가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u2_L05_challenge#4','sci',4,2,'u2','L05','g4_2_sci_u2_L05_challenge','lesson_challenge','SC4-2-u2-C20',3,'mc','auto','원인과 관련 있는 환경오염에서 두 가지 환경오염과 관련 있는 원인끼리 묶은 것은 무엇인가요?',ARRAY['SC4-2-u2-X28']::text[],false,'{"seq":4,"concept":"SC4-2-u2-C20","difficulty":3,"kind":"mc","stem":"원인과 관련 있는 환경오염에서 두 가지 환경오염과 관련 있는 원인끼리 묶은 것은 무엇인가요?","options":[{"t":"자동차에서 나오는 배기가스, 논밭에 사용하는 농약","correct":true},{"t":"바닷물에 섞여 있는 쓰레기, 생활 쓰레기의 매립","mis":"SC4-2-u2-X28"},{"t":"생활 쓰레기의 매립, 자동차에서 나오는 배기가스","mis":"SC4-2-u2-X28"},{"t":"네 가지 모두 한 가지 환경오염과만 관련 있다","mis":"SC4-2-u2-X28"}],"explanation":["줄마다 몇 가지인지 세요.","쉼표가 있는 줄이에요.","배기가스와 농약이에요."],"asset":{"type":"passage","lines":["자동차에서 나오는 배기가스 — 대기오염, ㉠","바닷물에 섞여 있는 쓰레기 — 수질오염","논밭에 사용하는 농약 — 토양오염, 수질오염","생활 쓰레기의 매립 — ㉡"],"title":"원인과 관련 있는 환경오염"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u2_L05_challenge#5','sci',4,2,'u2','L05','g4_2_sci_u2_L05_challenge','lesson_challenge','SC4-2-u2-C22',3,'mc','auto','농약에 대해 가장 알맞게 말한 것은 무엇인가요?',ARRAY['SC4-2-u2-X31','SC4-2-u2-X32']::text[],false,'{"seq":5,"concept":"SC4-2-u2-C22","difficulty":3,"kind":"mc","stem":"농약에 대해 가장 알맞게 말한 것은 무엇인가요?","options":[{"t":"농약을 지나치게 많이 쓰는 것이 문제이므로 가능한 한 적게 사용한다","correct":true},{"t":"농약은 많이 쓸수록 생태계에 좋다","mis":"SC4-2-u2-X31"},{"t":"농약은 아무 문제가 없으니 마음껏 쓴다","mis":"SC4-2-u2-X31"},{"t":"농약은 한 방울이라도 쓰면 안 되니 아예 쓰지 않아야 한다","mis":"SC4-2-u2-X32"}],"explanation":["과다 사용을 떠올려요.","양이 문제예요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u2_L05_challenge#6','sci',4,2,'u2','L05','g4_2_sci_u2_L05_challenge','lesson_challenge','SC4-2-u2-C21',3,'ox','auto','작은 플라스틱은 사람을 비롯한 생물의 몸속으로 들어오기도 해요.',ARRAY['SC4-2-u2-X30']::text[],false,'{"seq":6,"concept":"SC4-2-u2-C21","difficulty":3,"kind":"ox","stem":"작은 플라스틱은 사람을 비롯한 생물의 몸속으로 들어오기도 해요.","answer":"O","reason_options":[{"t":"바다에 떠다니는 플라스틱 쓰레기가 잘게 부서져 생물이 먹기도 하기 때문에","correct":true},{"t":"플라스틱은 물에 닿으면 곧바로 사라지기 때문에","mis":"SC4-2-u2-X30"}],"mis":"SC4-2-u2-X30","explanation":["바다 쓰레기를 떠올려요.","작게 부서져요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u2_L05_challenge#7','sci',4,2,'u2','L05','g4_2_sci_u2_L05_challenge','lesson_challenge','SC4-2-u2-C22',3,'mc','auto','우리 모둠이 토의한 생태계보전 노력에 하나를 더 넣으려고 해요. 알맞은 것은 무엇인가요?',ARRAY['SC4-2-u2-X31']::text[],false,'{"seq":7,"concept":"SC4-2-u2-C22","difficulty":3,"kind":"mc","stem":"우리 모둠이 토의한 생태계보전 노력에 하나를 더 넣으려고 해요. 알맞은 것은 무엇인가요?","options":[{"t":"음식물을 남기지 않는다","correct":true},{"t":"물을 쓰는 시간을 늘린다","mis":"SC4-2-u2-X31"},{"t":"쓰레기를 한 봉투에 모두 섞어 버린다","mis":"SC4-2-u2-X31"},{"t":"가까운 거리도 자동차를 탄다","mis":"SC4-2-u2-X31"}],"explanation":["노력의 공통점을 찾아요.","버리는 것을 줄여요.","음식물을 남기지 않아요."],"asset":{"type":"passage","lines":["가까운 거리는 걸어가거나 자전거를 타요.","일회용품 사용을 줄이고 분리배출을 해요.","설거지할 때 세제를 적당한 양만 써요.","물티슈 대신에 손수건을 써요."],"title":"우리 모둠이 토의한 생태계보전 노력"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u2_L05_challenge#8','sci',4,2,'u2','L05','g4_2_sci_u2_L05_challenge','lesson_challenge','SC4-2-u2-C20',4,'mc','auto','친구가 「배기가스는 공기만 더럽히니까 강이나 바다와는 관계없어.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?',ARRAY['SC4-2-u2-X28','SC4-2-u2-X29','SC4-2-u2-X30']::text[],false,'{"seq":8,"concept":"SC4-2-u2-C20","difficulty":4,"kind":"mc","stem":"친구가 「배기가스는 공기만 더럽히니까 강이나 바다와는 관계없어.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?","options":[{"t":"「배기가스는 대기오염과 수질오염을 함께 일으켜. 원인 하나가 꼭 한 가지 오염만 일으키는 건 아니야.」","correct":true},{"t":"「맞아, 배기가스는 대기오염만 일으켜.」","mis":"SC4-2-u2-X28"},{"t":"「배기가스는 토양오염만 일으켜.」","mis":"SC4-2-u2-X29"},{"t":"「배기가스는 어떤 오염도 일으키지 않아.」","mis":"SC4-2-u2-X30"}],"explanation":["원인과 오염을 견줘요.","둘과 관련 있어요.","첫 번째가 알맞아요."],"asset":{"type":"passage","lines":["자동차에서 나오는 배기가스 — 대기오염, ㉠","바닷물에 섞여 있는 쓰레기 — 수질오염","논밭에 사용하는 농약 — 토양오염, 수질오염","생활 쓰레기의 매립 — ㉡"],"title":"원인과 관련 있는 환경오염"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u2_L05_challenge#9','sci',4,2,'u2','L05','g4_2_sci_u2_L05_challenge','lesson_challenge','SC4-2-u2-C22',4,'mc','auto','「생태계를 보전하려면 모든 개발을 멈추고 농약과 플라스틱을 아예 쓰지 말아야 해.」라는 말을 가장 알맞게 고친 것은 무엇인가요?',ARRAY['SC4-2-u2-X31','SC4-2-u2-X27']::text[],false,'{"seq":9,"concept":"SC4-2-u2-C22","difficulty":4,"kind":"mc","stem":"「생태계를 보전하려면 모든 개발을 멈추고 농약과 플라스틱을 아예 쓰지 말아야 해.」라는 말을 가장 알맞게 고친 것은 무엇인가요?","options":[{"t":"「오염 물질의 양을 줄이고 과다 사용을 막으며, 자연 개발과 생태계보전 사이에 균형을 이루어야 해.」","correct":true},{"t":"「개발만 계속하면 생태계도 저절로 보전돼.」","mis":"SC4-2-u2-X31"},{"t":"「농약을 많이 쓰면 생태계가 건강해져.」","mis":"SC4-2-u2-X31"},{"t":"「생태계는 사람과 관계가 없으니 그냥 두면 돼.」","mis":"SC4-2-u2-X27"}],"explanation":["균형을 떠올려요.","양을 줄이는 것이에요.","첫 번째가 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u2_L05_challenge#10','sci',4,2,'u2','L05','g4_2_sci_u2_L05_challenge','lesson_challenge','SC4-2-u2-C21',4,'essay','teacher','환경오염의 뜻을 쓰고, 환경오염의 원인 한 가지와 그것이 생태계에 미치는 영향을 쓰세요. 그리고 생태계보전을 위해 내가 할 수 있는 노력을 두 가지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC4-2-u2-C21","difficulty":4,"kind":"essay","stem":"환경오염의 뜻을 쓰고, 환경오염의 원인 한 가지와 그것이 생태계에 미치는 영향을 쓰세요. 그리고 생태계보전을 위해 내가 할 수 있는 노력을 두 가지 쓰세요.","answer_guide":{"answer":"예: 환경오염은 자연 생태계나 주변이 인간 활동으로 훼손되고 더럽혀지는 현상이다. 자동차 배기가스는 대기오염을 일으켜 생물이 숨 쉬기 어려워진다. 나는 가까운 거리는 걸어가고, 일회용품 사용을 줄이겠다.","scoring_points":["환경오염의 뜻을 썼는가","원인과 그 영향을 이어 썼는가","보전 노력 두 가지를 썼는가"]},"explanation":["뜻부터 써요.","원인과 영향을 이어요.","노력을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u2_L06_basic#1','sci',4,2,'u2','L06','g4_2_sci_u2_L06_basic','lesson_basic','SC4-2-u2-C24',1,'mc','auto','「복원」은 무슨 뜻인가요?',ARRAY['SC4-2-u2-X34']::text[],false,'{"seq":1,"concept":"SC4-2-u2-C24","difficulty":1,"kind":"mc","stem":"「복원」은 무슨 뜻인가요?","options":[{"t":"원래대로 회복함","correct":true},{"t":"한 번도 없던 것을 새로 만듦","mis":"SC4-2-u2-X34"},{"t":"남김없이 모두 치워 없앰","mis":"SC4-2-u2-X34"},{"t":"있던 것을 다른 곳으로 옮겨 감","mis":"SC4-2-u2-X34"}],"explanation":["되살리는 일이에요.","원래 모습으로 돌아가요.","원래대로 회복함이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u2_L06_basic#2','sci',4,2,'u2','L06','g4_2_sci_u2_L06_basic','lesson_basic','SC4-2-u2-C28',1,'sa','auto','숲의 미로에서 팻말 ①을 지키면 지날 수 없는 비생물요소 세 가지 가운데 하나를 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SC4-2-u2-C28","difficulty":1,"kind":"sa","stem":"숲의 미로에서 팻말 ①을 지키면 지날 수 없는 비생물요소 세 가지 가운데 하나를 쓰세요.","answer":["흙","물","햇빛"],"explanation":["살아 있지 않은 것을 찾아요.","세 가지가 있어요.","흙, 물, 햇빛이에요."],"asset":{"type":"passage","lines":["미로에 있는 것 — 흙, 옥수수, 물, 상어, 노루, 참새, 세균, 새매, 햇빛, 메뚜기, 곰팡이","팻말 ① 생물요소만을 따라가요.","팻말 ② 지나간 길에 있는 요소들끼리 올바른 먹이사슬을 이루어야 해요."],"title":"숲의 미로"},"mis":"SC4-2-u2-X40"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u2_L06_basic#3','sci',4,2,'u2','L06','g4_2_sci_u2_L06_basic','lesson_basic','SC4-2-u2-C26',1,'ox','auto','생태계 지킴이 활동으로 찾아간 곳에서는 여러 생물을 아끼고 사랑하는 마음을 가져요.',ARRAY['SC4-2-u2-X37']::text[],false,'{"seq":3,"concept":"SC4-2-u2-C26","difficulty":1,"kind":"ox","stem":"생태계 지킴이 활동으로 찾아간 곳에서는 여러 생물을 아끼고 사랑하는 마음을 가져요.","answer":"O","reason_options":[{"t":"생물은 소중하고 함부로 다루면 안 되기 때문에","correct":true},{"t":"사진만 찍으면 되니 생물은 신경 쓰지 않아도 되기 때문에","mis":"SC4-2-u2-X37"}],"mis":"SC4-2-u2-X37","explanation":["방문한 곳을 떠올려요.","생물을 아껴요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u2_L06_basic#4','sci',4,2,'u2','L06','g4_2_sci_u2_L06_basic','lesson_basic','SC4-2-u2-C28',1,'mc','auto','숲의 미로에서 팻말 ①은 무엇을 따라가라고 하나요?',ARRAY['SC4-2-u2-X40','SC4-2-u2-X39']::text[],false,'{"seq":4,"concept":"SC4-2-u2-C28","difficulty":1,"kind":"mc","stem":"숲의 미로에서 팻말 ①은 무엇을 따라가라고 하나요?","options":[{"t":"생물요소만","correct":true},{"t":"비생물요소만","mis":"SC4-2-u2-X40"},{"t":"몸집이 가장 큰 것만","mis":"SC4-2-u2-X39"},{"t":"이름이 가장 긴 것만","mis":"SC4-2-u2-X40"}],"explanation":["팻말 ①을 읽어요.","살아 있는 요소예요.","생물요소만이에요."],"asset":{"type":"passage","lines":["미로에 있는 것 — 흙, 옥수수, 물, 상어, 노루, 참새, 세균, 새매, 햇빛, 메뚜기, 곰팡이","팻말 ① 생물요소만을 따라가요.","팻말 ② 지나간 길에 있는 요소들끼리 올바른 먹이사슬을 이루어야 해요."],"title":"숲의 미로"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u2_L06_basic#5','sci',4,2,'u2','L06','g4_2_sci_u2_L06_basic','lesson_basic','SC4-2-u2-C25',2,'mc','auto','생태계 지킴이 활동을 계획할 때 정할 것으로 알맞은 것은 무엇인가요?',ARRAY['SC4-2-u2-X38','SC4-2-u2-X35','SC4-2-u2-X36']::text[],false,'{"seq":5,"concept":"SC4-2-u2-C25","difficulty":2,"kind":"mc","stem":"생태계 지킴이 활동을 계획할 때 정할 것으로 알맞은 것은 무엇인가요?","options":[{"t":"생태계보전이 필요한 까닭, 갈 장소, 모둠원의 역할","correct":true},{"t":"발표 자료에 칠할 색깔만","mis":"SC4-2-u2-X38"},{"t":"누가 가장 먼저 끝내는지","mis":"SC4-2-u2-X35"},{"t":"친구들의 집 주소","mis":"SC4-2-u2-X36"}],"explanation":["계획해요를 떠올려요.","까닭과 장소와 역할이에요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u2_L06_basic#6','sci',4,2,'u2','L06','g4_2_sci_u2_L06_basic','lesson_basic','SC4-2-u2-C26',2,'mc','auto','사진을 찍을 장소를 찾아갈 때 알맞은 행동은 무엇인가요?',ARRAY['SC4-2-u2-X37']::text[],false,'{"seq":6,"concept":"SC4-2-u2-C26","difficulty":2,"kind":"mc","stem":"사진을 찍을 장소를 찾아갈 때 알맞은 행동은 무엇인가요?","options":[{"t":"다치지 않도록 주변을 살피며 조심한다","correct":true},{"t":"좋은 사진을 찍으려고 위험한 곳에 얼른 들어간다","mis":"SC4-2-u2-X37"},{"t":"방문한 곳의 꽃을 마음대로 꺾는다","mis":"SC4-2-u2-X37"},{"t":"혼자 몰래 멀리 간다","mis":"SC4-2-u2-X37"}],"explanation":["안전을 떠올려요.","다치지 않아야 해요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u2_L06_basic#7','sci',4,2,'u2','L06','g4_2_sci_u2_L06_basic','lesson_basic','SC4-2-u2-C25',2,'match','auto','지킴이 활동의 단계와 하는 일을 알맞게 이으세요.','{}'::text[],false,'{"seq":7,"concept":"SC4-2-u2-C25","difficulty":2,"kind":"match","stem":"지킴이 활동의 단계와 하는 일을 알맞게 이으세요.","pairs":[{"l":"계획해요","r":"갈 장소와 모둠원의 역할을 정해요"},{"l":"실행해요","r":"장소를 찾아 사진을 찍고 해결 방법을 토의해요"},{"l":"실천해요","r":"정리한 방법을 발표하고 생활 속에서 실천해요"}],"mis":"SC4-2-u2-X35","explanation":["세 단계를 떠올려요.","정하고, 해 보고, 생활에서 해요.","차례대로 이어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u2_L06_basic#8','sci',4,2,'u2','L06','g4_2_sci_u2_L06_basic','lesson_basic','SC4-2-u2-C25',2,'ox','auto','실천 방법을 학급 게시판에 올릴 때에는 친구의 개인 정보도 함께 올려요.',ARRAY['SC4-2-u2-X36']::text[],false,'{"seq":8,"concept":"SC4-2-u2-C25","difficulty":2,"kind":"ox","stem":"실천 방법을 학급 게시판에 올릴 때에는 친구의 개인 정보도 함께 올려요.","answer":"X","reason_options":[{"t":"자신이나 다른 사람의 개인 정보를 누리망에 함부로 올리면 안 되기 때문에","correct":true},{"t":"개인 정보를 올려야 누가 했는지 알 수 있기 때문에","mis":"SC4-2-u2-X36"}],"mis":"SC4-2-u2-X36","explanation":["누리망을 쓸 때를 떠올려요.","개인 정보를 지켜요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u2_L06_basic#9','sci',4,2,'u2','L06','g4_2_sci_u2_L06_basic','lesson_basic','SC4-2-u2-C27',2,'mc','auto','우리 모둠의 생태계 지킴이 계획에서 ㉠에 들어갈 해결 방법으로 알맞은 것은 무엇인가요?',ARRAY['SC4-2-u2-X38','SC4-2-u2-X31']::text[],false,'{"seq":9,"concept":"SC4-2-u2-C27","difficulty":2,"kind":"mc","stem":"우리 모둠의 생태계 지킴이 계획에서 ㉠에 들어갈 해결 방법으로 알맞은 것은 무엇인가요?","options":[{"t":"등산로를 보수하고 정해진 길로만 사람들이 다니도록 한다","correct":true},{"t":"망가진 등산로는 그냥 두고 다른 산으로 간다","mis":"SC4-2-u2-X38"},{"t":"뒷산 입구를 아예 막아 아무도 못 오게 한다","mis":"SC4-2-u2-X38"},{"t":"길을 더 넓혀 풀을 모두 걷어 낸다","mis":"SC4-2-u2-X31"}],"explanation":["문제점을 읽어요.","길이 넓어지고 풀이 없어졌어요.","첫 번째예요."],"asset":{"type":"passage","lines":["장소 — 뒷산 등산로","문제점 — 풀이 없어지고 사람이 다니는 길이 지나치게 넓어졌어요.","해결 방법 — ㉠"],"title":"우리 모둠의 생태계 지킴이 계획"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u2_L06_basic#10','sci',4,2,'u2','L06','g4_2_sci_u2_L06_basic','lesson_basic','SC4-2-u2-C28',3,'mc','auto','숲의 미로에서 팻말 ①과 ②를 모두 지키며 지날 수 있는 것끼리 묶은 것은 무엇인가요?',ARRAY['SC4-2-u2-X39','SC4-2-u2-X40']::text[],false,'{"seq":10,"concept":"SC4-2-u2-C28","difficulty":3,"kind":"mc","stem":"숲의 미로에서 팻말 ①과 ②를 모두 지키며 지날 수 있는 것끼리 묶은 것은 무엇인가요?","options":[{"t":"옥수수, 메뚜기, 참새, 새매","correct":true},{"t":"옥수수, 메뚜기, 상어, 노루","mis":"SC4-2-u2-X39"},{"t":"흙, 물, 햇빛, 옥수수","mis":"SC4-2-u2-X40"},{"t":"세균, 곰팡이, 참새, 새매","mis":"SC4-2-u2-X39"}],"explanation":["먹이사슬로 이어 봐요.","옥수수 → 메뚜기 → 참새 → 새매예요.","첫 번째예요."],"asset":{"type":"passage","lines":["미로에 있는 것 — 흙, 옥수수, 물, 상어, 노루, 참새, 세균, 새매, 햇빛, 메뚜기, 곰팡이","팻말 ① 생물요소만을 따라가요.","팻말 ② 지나간 길에 있는 요소들끼리 올바른 먹이사슬을 이루어야 해요."],"title":"숲의 미로"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u2_L06_challenge#1','sci',4,2,'u2','L06','g4_2_sci_u2_L06_challenge','lesson_challenge','SC4-2-u2-C24',2,'blank','auto','「무분별한 개발과 환경오염으로 원래의 모습을 잃은 곳을 되살리는 일을 생태계(    )(이)라고 해요.」 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SC4-2-u2-X34']::text[],false,'{"seq":1,"concept":"SC4-2-u2-C24","difficulty":2,"kind":"blank","stem":"「무분별한 개발과 환경오염으로 원래의 모습을 잃은 곳을 되살리는 일을 생태계(    )(이)라고 해요.」 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"복원","correct":true},{"t":"개발","mis":"SC4-2-u2-X34"},{"t":"오염","mis":"SC4-2-u2-X34"},{"t":"이동","mis":"SC4-2-u2-X34"}],"explanation":["되살리는 일이에요.","원래대로 회복해요.","복원이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u2_L06_challenge#2','sci',4,2,'u2','L06','g4_2_sci_u2_L06_challenge','lesson_challenge','SC4-2-u2-C28',2,'mc','auto','숲의 미로에서 팻말을 하나씩 붙일 때 지날 수 있는 것의 수가 바르게 바뀐 것은 무엇인가요?',ARRAY['SC4-2-u2-X40','SC4-2-u2-X39']::text[],false,'{"seq":2,"concept":"SC4-2-u2-C28","difficulty":2,"kind":"mc","stem":"숲의 미로에서 팻말을 하나씩 붙일 때 지날 수 있는 것의 수가 바르게 바뀐 것은 무엇인가요?","options":[{"t":"11가지 → 8가지 → 4가지","correct":true},{"t":"11가지 → 11가지 → 4가지","mis":"SC4-2-u2-X40"},{"t":"11가지 → 8가지 → 8가지","mis":"SC4-2-u2-X39"},{"t":"11가지 → 3가지 → 1가지","mis":"SC4-2-u2-X40"}],"explanation":["팻말 ①은 셋을 빼요.","팻말 ②는 넷만 남겨요.","첫 번째예요."],"asset":{"type":"passage","lines":["미로에 있는 것 — 흙, 옥수수, 물, 상어, 노루, 참새, 세균, 새매, 햇빛, 메뚜기, 곰팡이","팻말 ① 생물요소만을 따라가요.","팻말 ② 지나간 길에 있는 요소들끼리 올바른 먹이사슬을 이루어야 해요."],"title":"숲의 미로"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u2_L06_challenge#3','sci',4,2,'u2','L06','g4_2_sci_u2_L06_challenge','lesson_challenge','SC4-2-u2-C28',3,'error','auto','숲의 미로를 지나며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC4-2-u2-X39','SC4-2-u2-X40']::text[],false,'{"seq":3,"concept":"SC4-2-u2-C28","difficulty":3,"kind":"error","stem":"숲의 미로를 지나며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「상어는 생물요소니까 미로를 지날 수 있어.」","correct":true,"mis_target":"SC4-2-u2-X39"},{"t":"친구 가 — 「햇빛은 살아 있지 않아서 팻말 ①에 걸려.」","mis":"SC4-2-u2-X40"},{"t":"친구 나 — 「옥수수에서 새매까지 먹이사슬로 이어져.」","mis":"SC4-2-u2-X39"}],"explanation":["팻말 ②를 떠올려요.","먹이사슬을 이루어야 해요.","친구 다가 잘못 말했어요."],"asset":{"type":"passage","lines":["미로에 있는 것 — 흙, 옥수수, 물, 상어, 노루, 참새, 세균, 새매, 햇빛, 메뚜기, 곰팡이","팻말 ① 생물요소만을 따라가요.","팻말 ② 지나간 길에 있는 요소들끼리 올바른 먹이사슬을 이루어야 해요."],"title":"숲의 미로"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u2_L06_challenge#4','sci',4,2,'u2','L06','g4_2_sci_u2_L06_challenge','lesson_challenge','SC4-2-u2-C28',3,'mc','auto','상어는 생물요소인데도 숲의 미로를 지날 수 없는 까닭은 무엇인가요?',ARRAY['SC4-2-u2-X40','SC4-2-u2-X25']::text[],false,'{"seq":4,"concept":"SC4-2-u2-C28","difficulty":3,"kind":"mc","stem":"상어는 생물요소인데도 숲의 미로를 지날 수 없는 까닭은 무엇인가요?","options":[{"t":"지나간 길의 요소들끼리 올바른 먹이사슬을 이루어야 하기 때문에","correct":true},{"t":"상어는 생물요소가 아니기 때문에","mis":"SC4-2-u2-X40"},{"t":"상어는 몸집이 너무 크기 때문에","mis":"SC4-2-u2-X25"},{"t":"미로에 있는 생물요소가 네 가지뿐이기 때문에","mis":"SC4-2-u2-X40"}],"explanation":["팻말은 두 줄이에요.","둘째 팻말을 읽어요.","첫 번째예요."],"asset":{"type":"passage","lines":["미로에 있는 것 — 흙, 옥수수, 물, 상어, 노루, 참새, 세균, 새매, 햇빛, 메뚜기, 곰팡이","팻말 ① 생물요소만을 따라가요.","팻말 ② 지나간 길에 있는 요소들끼리 올바른 먹이사슬을 이루어야 해요."],"title":"숲의 미로"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u2_L06_challenge#5','sci',4,2,'u2','L06','g4_2_sci_u2_L06_challenge','lesson_challenge','SC4-2-u2-C27',3,'mc','auto','좋은 발표 자료인지 살펴보는 물음으로 알맞지 않은 것은 무엇인가요?',ARRAY['SC4-2-u2-X38']::text[],false,'{"seq":5,"concept":"SC4-2-u2-C27","difficulty":3,"kind":"mc","stem":"좋은 발표 자료인지 살펴보는 물음으로 알맞지 않은 것은 무엇인가요?","options":[{"t":"가장 예쁘고 화려하게 꾸몄나요?","correct":true},{"t":"장소의 문제점이 잘 드러났나요?","mis":"SC4-2-u2-X38"},{"t":"우리가 실천할 수 있는 해결 방법인가요?","mis":"SC4-2-u2-X38"},{"t":"내용대로 실천하면 복원과 보전에 도움이 될까요?","mis":"SC4-2-u2-X38"}],"explanation":["세 물음을 떠올려요.","꾸밈을 묻지 않아요.","첫 번째가 알맞지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u2_L06_challenge#6','sci',4,2,'u2','L06','g4_2_sci_u2_L06_challenge','lesson_challenge','SC4-2-u2-C25',3,'ox','auto','모둠 발표를 마치면 생태계 지킴이 활동은 모두 끝나요.',ARRAY['SC4-2-u2-X35']::text[],false,'{"seq":6,"concept":"SC4-2-u2-C25","difficulty":3,"kind":"ox","stem":"모둠 발표를 마치면 생태계 지킴이 활동은 모두 끝나요.","answer":"X","reason_options":[{"t":"발표한 실천 방법을 생활 속에서 실천해야 지킴이 활동이 되기 때문에","correct":true},{"t":"발표를 잘하면 실천은 하지 않아도 되기 때문에","mis":"SC4-2-u2-X35"}],"mis":"SC4-2-u2-X35","explanation":["실천해요를 떠올려요.","계획으로 끝내지 않아요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u2_L06_challenge#7','sci',4,2,'u2','L06','g4_2_sci_u2_L06_challenge','lesson_challenge','SC4-2-u2-C25',3,'mc','auto','친구들의 실천 방법이 올라온 학급 게시판에서 알맞은 행동은 무엇인가요?',ARRAY['SC4-2-u2-X36','SC4-2-u2-X35']::text[],false,'{"seq":7,"concept":"SC4-2-u2-C25","difficulty":3,"kind":"mc","stem":"친구들의 실천 방법이 올라온 학급 게시판에서 알맞은 행동은 무엇인가요?","options":[{"t":"친구들의 실천 방법을 살펴보고 칭찬하는 댓글을 쓴다","correct":true},{"t":"마음에 들지 않는 실천 방법을 비난한다","mis":"SC4-2-u2-X36"},{"t":"친구의 전화번호를 댓글로 적는다","mis":"SC4-2-u2-X36"},{"t":"읽지 않고 그냥 지나친다","mis":"SC4-2-u2-X35"}],"explanation":["게시판을 떠올려요.","칭찬해요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u2_L06_challenge#8','sci',4,2,'u2','L06','g4_2_sci_u2_L06_challenge','lesson_challenge','SC4-2-u2-C27',4,'mc','auto','친구가 「발표 자료는 색을 많이 칠하고 반짝이를 붙일수록 좋은 자료야.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?',ARRAY['SC4-2-u2-X38','SC4-2-u2-X35','SC4-2-u2-X36']::text[],false,'{"seq":8,"concept":"SC4-2-u2-C27","difficulty":4,"kind":"mc","stem":"친구가 「발표 자료는 색을 많이 칠하고 반짝이를 붙일수록 좋은 자료야.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?","options":[{"t":"「꾸밈보다 장소의 문제점과 우리가 실천할 수 있는 해결 방법이 잘 드러나는지가 중요해.」","correct":true},{"t":"「맞아, 화려할수록 생태계에 도움이 돼.」","mis":"SC4-2-u2-X38"},{"t":"「발표 자료는 만들지 않아도 돼.」","mis":"SC4-2-u2-X35"},{"t":"「꾸밀 시간에 친구 개인 정보를 적자.」","mis":"SC4-2-u2-X36"}],"explanation":["좋은 자료의 기준을 떠올려요.","내용이 중요해요.","첫 번째가 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u2_L06_challenge#9','sci',4,2,'u2','L06','g4_2_sci_u2_L06_challenge','lesson_challenge','SC4-2-u2-C24',4,'mc','auto','쓰레기로 가득했던 산이 새롭게 태어났다는 이야기를 듣고 가장 알맞게 생각한 것은 무엇인가요?',ARRAY['SC4-2-u2-X34','SC4-2-u2-X35']::text[],false,'{"seq":9,"concept":"SC4-2-u2-C24","difficulty":4,"kind":"mc","stem":"쓰레기로 가득했던 산이 새롭게 태어났다는 이야기를 듣고 가장 알맞게 생각한 것은 무엇인가요?","options":[{"t":"「원래 모습을 잃은 곳도 복원할 수 있구나. 우리 동네에서도 지킴이 활동을 해 보자.」","correct":true},{"t":"「복원은 산을 모두 없애는 거구나.」","mis":"SC4-2-u2-X34"},{"t":"「한 번 망가진 곳은 다시 되살릴 수 없어.」","mis":"SC4-2-u2-X34"},{"t":"「우리 동네는 지킬 필요가 없어.」","mis":"SC4-2-u2-X35"}],"explanation":["복원의 뜻을 떠올려요.","되살릴 수 있어요.","첫 번째가 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u2_L06_challenge#10','sci',4,2,'u2','L06','g4_2_sci_u2_L06_challenge','lesson_challenge','SC4-2-u2-C25',4,'essay','teacher','우리 동네에서 생태계복원이나 보전이 필요한 장소를 하나 정해 문제점을 쓰고, 생태계 지킴이로서 실천할 수 있는 방법을 두 가지 쓰세요. 그리고 장소를 찾아갈 때 지킬 점을 한 가지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC4-2-u2-C25","difficulty":4,"kind":"essay","stem":"우리 동네에서 생태계복원이나 보전이 필요한 장소를 하나 정해 문제점을 쓰고, 생태계 지킴이로서 실천할 수 있는 방법을 두 가지 쓰세요. 그리고 장소를 찾아갈 때 지킬 점을 한 가지 쓰세요.","answer_guide":{"answer":"예: 뒷산 등산로는 풀이 없어지고 길이 지나치게 넓어졌다. 뒷산 입구에 안내 팻말을 만들어 세우고, 길이 무너지고 풀이 없어진 곳은 흙을 덮어 주고 관리한다. 장소를 찾아갈 때에는 다치지 않도록 조심하고 생물을 아끼는 마음을 가진다.","scoring_points":["장소와 문제점을 썼는가","실천할 수 있는 방법 두 가지를 썼는가","찾아갈 때 지킬 점을 썼는가"]},"explanation":["장소를 정해요.","실천 방법을 써요.","지킬 점을 써요."],"asset":{"type":"passage","lines":["장소 — 뒷산 등산로","문제점 — 풀이 없어지고 사람이 다니는 길이 지나치게 넓어졌어요.","해결 방법 — ㉠"],"title":"우리 모둠의 생태계 지킴이 계획"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u2_L07_basic#1','sci',4,2,'u2','L07','g4_2_sci_u2_L07_basic','lesson_basic','SC4-2-u2-C30',1,'mc','auto','「온실 가스」는 무엇인가요?',ARRAY['SC4-2-u2-X44']::text[],false,'{"seq":1,"concept":"SC4-2-u2-C30","difficulty":1,"kind":"mc","stem":"「온실 가스」는 무엇인가요?","options":[{"t":"지구 표면의 온도를 상승시키는 원인이 되는 기체","correct":true},{"t":"지구 표면의 온도를 낮추어 주는 기체","mis":"SC4-2-u2-X44"},{"t":"곤충을 기를 때 주는 먹이","mis":"SC4-2-u2-X44"},{"t":"음식의 영양가를 재는 단위","mis":"SC4-2-u2-X44"}],"explanation":["지구 표면의 온도와 관련 있어요.","온도를 높여요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u2_L07_basic#2','sci',4,2,'u2','L07','g4_2_sci_u2_L07_basic','lesson_basic','SC4-2-u2-C29',1,'sa','auto','예로부터 우리 조상들이 즐겨 먹은 곤충 가운데 하나를 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SC4-2-u2-C29","difficulty":1,"kind":"sa","stem":"예로부터 우리 조상들이 즐겨 먹은 곤충 가운데 하나를 쓰세요.","answer":["메뚜기","누에 번데기","누에번데기","번데기"],"explanation":["첫째 줄을 읽어요.","두 가지가 있어요.","메뚜기, 누에 번데기예요."],"asset":{"type":"passage","lines":["예로부터 — 우리 조상들은 메뚜기나 누에 번데기를 즐겨 먹었어요.","현재 — 우리나라는 곤충을 먹을 수 있는 종류로 인정하고 있어요.","앞으로 — ㉠"],"title":"곤충을 먹는 일의 때"},"mis":"SC4-2-u2-X42"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u2_L07_basic#3','sci',4,2,'u2','L07','g4_2_sci_u2_L07_basic','lesson_basic','SC4-2-u2-C30',1,'ox','auto','곤충은 가축과 달리 기를 때 먹이를 훨씬 적게 먹어요.',ARRAY['SC4-2-u2-X43']::text[],false,'{"seq":3,"concept":"SC4-2-u2-C30","difficulty":1,"kind":"ox","stem":"곤충은 가축과 달리 기를 때 먹이를 훨씬 적게 먹어요.","answer":"O","reason_options":[{"t":"곤충과 가축을 견주면 곤충이 먹이를 훨씬 적게 먹기 때문에","correct":true},{"t":"곤충은 먹이를 전혀 먹지 않기 때문에","mis":"SC4-2-u2-X43"}],"mis":"SC4-2-u2-X43","explanation":["견주어 보기를 읽어요.","먹이가 달라요.","그래서 O예요."],"asset":{"type":"passage","lines":["곤충을 기를 때 — 먹이: 훨씬 적게 먹어요 / 온실 가스: 거의 배출하지 않아요","가축을 기를 때 — 먹이: 곤충보다 훨씬 많이 먹어요 / 온실 가스: 배출해요"],"title":"곤충과 가축 견주어 보기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u2_L07_basic#4','sci',4,2,'u2','L07','g4_2_sci_u2_L07_basic','lesson_basic','SC4-2-u2-C29',1,'mc','auto','곤충 요리는 주로 어떤 모습으로 만드나요?',ARRAY['SC4-2-u2-X45','SC4-2-u2-X41']::text[],false,'{"seq":4,"concept":"SC4-2-u2-C29","difficulty":1,"kind":"mc","stem":"곤충 요리는 주로 어떤 모습으로 만드나요?","options":[{"t":"곤충의 원래 모습이 잘 드러나지 않는 형태","correct":true},{"t":"곤충 모습이 하나도 빠짐없이 다 보이는 형태","mis":"SC4-2-u2-X45"},{"t":"살아 있는 곤충 그대로","mis":"SC4-2-u2-X41"},{"t":"차갑게 얼려 그대로 내놓는 형태","mis":"SC4-2-u2-X45"}],"explanation":["먹는 사람을 생각해요.","모습이 잘 안 보여요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u2_L07_basic#5','sci',4,2,'u2','L07','g4_2_sci_u2_L07_basic','lesson_basic','SC4-2-u2-C30',2,'mc','auto','곤충과 가축 견주어 보기에서 가축에 대한 설명으로 알맞은 것은 무엇인가요?',ARRAY['SC4-2-u2-X43']::text[],false,'{"seq":5,"concept":"SC4-2-u2-C30","difficulty":2,"kind":"mc","stem":"곤충과 가축 견주어 보기에서 가축에 대한 설명으로 알맞은 것은 무엇인가요?","options":[{"t":"곤충보다 먹이를 훨씬 많이 먹고 온실 가스를 배출한다","correct":true},{"t":"곤충보다 먹이를 훨씬 적게 먹는다","mis":"SC4-2-u2-X43"},{"t":"온실 가스를 전혀 배출하지 않는다","mis":"SC4-2-u2-X43"},{"t":"먹이를 먹지 않는다","mis":"SC4-2-u2-X43"}],"explanation":["둘째 줄을 읽어요.","곤충과 반대예요.","첫 번째예요."],"asset":{"type":"passage","lines":["곤충을 기를 때 — 먹이: 훨씬 적게 먹어요 / 온실 가스: 거의 배출하지 않아요","가축을 기를 때 — 먹이: 곤충보다 훨씬 많이 먹어요 / 온실 가스: 배출해요"],"title":"곤충과 가축 견주어 보기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u2_L07_basic#6','sci',4,2,'u2','L07','g4_2_sci_u2_L07_basic','lesson_basic','SC4-2-u2-C31',2,'mc','auto','곤충 요리 전문가가 하는 일로 알맞은 것은 무엇인가요?',ARRAY['SC4-2-u2-X45','SC4-2-u2-X43']::text[],false,'{"seq":6,"concept":"SC4-2-u2-C31","difficulty":2,"kind":"mc","stem":"곤충 요리 전문가가 하는 일로 알맞은 것은 무엇인가요?","options":[{"t":"맛이 좋고 영양가 높은 다양한 곤충을 찾아내고 새로운 요리 방법을 개발한다","correct":true},{"t":"곤충을 모두 잡아 없앤다","mis":"SC4-2-u2-X45"},{"t":"곤충의 모습이 그대로 드러나게 요리한다","mis":"SC4-2-u2-X45"},{"t":"가축을 더 많이 기른다","mis":"SC4-2-u2-X43"}],"explanation":["찾아내고 개발해요.","새로운 요리 방법이에요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u2_L07_basic#7','sci',4,2,'u2','L07','g4_2_sci_u2_L07_basic','lesson_basic','SC4-2-u2-C29',2,'match','auto','말과 알맞은 뜻을 이으세요.','{}'::text[],false,'{"seq":7,"concept":"SC4-2-u2-C29","difficulty":2,"kind":"match","stem":"말과 알맞은 뜻을 이으세요.","pairs":[{"l":"예로부터 즐겨 온 먹거리","r":"메뚜기, 누에 번데기"},{"l":"온실 가스","r":"지구 표면의 온도를 상승시키는 원인이 되는 기체"},{"l":"곤충 요리 전문가","r":"새로운 곤충 요리 방법을 개발하는 사람"}],"mis":"SC4-2-u2-X44","explanation":["하나씩 떠올려요.","온실 가스는 기체예요.","차례대로 이어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u2_L07_basic#8','sci',4,2,'u2','L07','g4_2_sci_u2_L07_basic','lesson_basic','SC4-2-u2-C29',2,'ox','auto','곤충은 징그러우니 먹을거리가 될 수 없어요.',ARRAY['SC4-2-u2-X41']::text[],false,'{"seq":8,"concept":"SC4-2-u2-C29","difficulty":2,"kind":"ox","stem":"곤충은 징그러우니 먹을거리가 될 수 없어요.","answer":"X","reason_options":[{"t":"징그럽다고 생각하는 사람이 많지만 곤충은 맛이 좋고 영양가가 아주 높기 때문에","correct":true},{"t":"보기에 징그러운 것은 먹을 수 없기 때문에","mis":"SC4-2-u2-X41"}],"mis":"SC4-2-u2-X41","explanation":["곤충의 장점을 떠올려요.","맛과 영양이 좋아요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u2_L07_basic#9','sci',4,2,'u2','L07','g4_2_sci_u2_L07_basic','lesson_basic','SC4-2-u2-C30',2,'mc','auto','곤충 요리가 친환경 미래 식량으로 관심을 받는 까닭으로 알맞은 것은 무엇인가요?',ARRAY['SC4-2-u2-X43','SC4-2-u2-X41']::text[],false,'{"seq":9,"concept":"SC4-2-u2-C30","difficulty":2,"kind":"mc","stem":"곤충 요리가 친환경 미래 식량으로 관심을 받는 까닭으로 알맞은 것은 무엇인가요?","options":[{"t":"온실 가스를 거의 배출하지 않기 때문에","correct":true},{"t":"온실 가스를 아주 많이 배출하기 때문에","mis":"SC4-2-u2-X43"},{"t":"기를 때 먹이를 가축보다 훨씬 많이 먹기 때문에","mis":"SC4-2-u2-X43"},{"t":"맛이 없고 영양가가 낮기 때문에","mis":"SC4-2-u2-X41"}],"explanation":["친환경을 떠올려요.","환경에 부담이 적어요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u2_L07_basic#10','sci',4,2,'u2','L07','g4_2_sci_u2_L07_basic','lesson_basic','SC4-2-u2-C31',3,'mc','auto','곤충을 먹는 일의 때에서 ㉠에 들어갈 내용으로 알맞은 것은 무엇인가요?',ARRAY['SC4-2-u2-X42','SC4-2-u2-X41','SC4-2-u2-X43']::text[],false,'{"seq":10,"concept":"SC4-2-u2-C31","difficulty":3,"kind":"mc","stem":"곤충을 먹는 일의 때에서 ㉠에 들어갈 내용으로 알맞은 것은 무엇인가요?","options":[{"t":"다양한 곤충을 찾아내고 새로운 요리 방법을 개발하는 곤충 요리 전문가가 미래 직업으로 자리 잡을 수도 있어요","correct":true},{"t":"이제부터 처음으로 곤충을 먹기 시작해요","mis":"SC4-2-u2-X42"},{"t":"어떤 곤충이든 마음대로 잡아먹어요","mis":"SC4-2-u2-X41"},{"t":"곤충을 기르면 온실 가스가 크게 늘어나요","mis":"SC4-2-u2-X43"}],"explanation":["「앞으로」 줄이에요.","전문가와 직업이에요.","첫 번째예요."],"asset":{"type":"passage","lines":["예로부터 — 우리 조상들은 메뚜기나 누에 번데기를 즐겨 먹었어요.","현재 — 우리나라는 곤충을 먹을 수 있는 종류로 인정하고 있어요.","앞으로 — ㉠"],"title":"곤충을 먹는 일의 때"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u2_L07_challenge#1','sci',4,2,'u2','L07','g4_2_sci_u2_L07_challenge','lesson_challenge','SC4-2-u2-C30',2,'blank','auto','「곤충 요리는 (    )와/과 환경 문제를 동시에 해결해 줄 친환경 미래 식량으로 관심을 받고 있어요.」 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SC4-2-u2-X41','SC4-2-u2-X44','SC4-2-u2-X43']::text[],false,'{"seq":1,"concept":"SC4-2-u2-C30","difficulty":2,"kind":"blank","stem":"「곤충 요리는 (    )와/과 환경 문제를 동시에 해결해 줄 친환경 미래 식량으로 관심을 받고 있어요.」 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"빈곤","correct":true},{"t":"징그러움","mis":"SC4-2-u2-X41"},{"t":"온실 가스","mis":"SC4-2-u2-X44"},{"t":"가축","mis":"SC4-2-u2-X43"}],"explanation":["먹을거리가 모자란 문제예요.","가난이에요.","빈곤이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u2_L07_challenge#2','sci',4,2,'u2','L07','g4_2_sci_u2_L07_challenge','lesson_challenge','SC4-2-u2-C29',2,'mc','auto','곤충을 먹는 일에 대해 바르게 말한 것은 무엇인가요?',ARRAY['SC4-2-u2-X42','SC4-2-u2-X41']::text[],false,'{"seq":2,"concept":"SC4-2-u2-C29","difficulty":2,"kind":"mc","stem":"곤충을 먹는 일에 대해 바르게 말한 것은 무엇인가요?","options":[{"t":"예로부터 해 온 일이고, 지금은 먹을 수 있는 종류로 인정한 곤충을 먹는다","correct":true},{"t":"앞으로 처음 시작할 새로운 일이다","mis":"SC4-2-u2-X42"},{"t":"곤충이면 어떤 것이든 먹어도 된다","mis":"SC4-2-u2-X41"},{"t":"곤충은 영양가가 없어 먹지 않는다","mis":"SC4-2-u2-X41"}],"explanation":["때를 떠올려요.","이미 먹어 왔어요.","첫 번째예요."],"asset":{"type":"passage","lines":["예로부터 — 우리 조상들은 메뚜기나 누에 번데기를 즐겨 먹었어요.","현재 — 우리나라는 곤충을 먹을 수 있는 종류로 인정하고 있어요.","앞으로 — ㉠"],"title":"곤충을 먹는 일의 때"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u2_L07_challenge#3','sci',4,2,'u2','L07','g4_2_sci_u2_L07_challenge','lesson_challenge','SC4-2-u2-C30',3,'error','auto','곤충과 가축을 견주며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC4-2-u2-X43','SC4-2-u2-X44','SC4-2-u2-X41']::text[],false,'{"seq":3,"concept":"SC4-2-u2-C30","difficulty":3,"kind":"error","stem":"곤충과 가축을 견주며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 나 — 「곤충은 기를 때 가축보다 먹이를 훨씬 많이 먹어.」","correct":true,"mis_target":"SC4-2-u2-X43"},{"t":"친구 가 — 「곤충은 온실 가스를 거의 배출하지 않아.」","mis":"SC4-2-u2-X44"},{"t":"친구 다 — 「곤충은 맛이 좋고 영양가가 높아.」","mis":"SC4-2-u2-X41"}],"explanation":["견주어 보기를 읽어요.","먹이는 곤충이 훨씬 적어요.","친구 나가 잘못 말했어요."],"asset":{"type":"passage","lines":["곤충을 기를 때 — 먹이: 훨씬 적게 먹어요 / 온실 가스: 거의 배출하지 않아요","가축을 기를 때 — 먹이: 곤충보다 훨씬 많이 먹어요 / 온실 가스: 배출해요"],"title":"곤충과 가축 견주어 보기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u2_L07_challenge#4','sci',4,2,'u2','L07','g4_2_sci_u2_L07_challenge','lesson_challenge','SC4-2-u2-C29',3,'mc','auto','「미래 식량」이라고 부르는 곤충을 우리 조상들이 이미 먹어 왔다는 것으로 알 수 있는 것은 무엇인가요?',ARRAY['SC4-2-u2-X42','SC4-2-u2-X41']::text[],false,'{"seq":4,"concept":"SC4-2-u2-C29","difficulty":3,"kind":"mc","stem":"「미래 식량」이라고 부르는 곤충을 우리 조상들이 이미 먹어 왔다는 것으로 알 수 있는 것은 무엇인가요?","options":[{"t":"곤충을 먹는 일은 새로 생긴 일이 아니라 예로부터 해 온 일이다","correct":true},{"t":"곤충은 앞으로만 먹을 수 있다","mis":"SC4-2-u2-X42"},{"t":"조상들은 곤충을 먹지 않았다","mis":"SC4-2-u2-X42"},{"t":"곤충 요리는 아무도 먹지 않는다","mis":"SC4-2-u2-X41"}],"explanation":["「예로부터」를 떠올려요.","이미 먹어 왔어요.","첫 번째예요."],"asset":{"type":"passage","lines":["예로부터 — 우리 조상들은 메뚜기나 누에 번데기를 즐겨 먹었어요.","현재 — 우리나라는 곤충을 먹을 수 있는 종류로 인정하고 있어요.","앞으로 — ㉠"],"title":"곤충을 먹는 일의 때"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u2_L07_challenge#5','sci',4,2,'u2','L07','g4_2_sci_u2_L07_challenge','lesson_challenge','SC4-2-u2-C30',3,'mc','auto','온실 가스에 대해 바르게 말한 것은 무엇인가요?',ARRAY['SC4-2-u2-X44','SC4-2-u2-X43']::text[],false,'{"seq":5,"concept":"SC4-2-u2-C30","difficulty":3,"kind":"mc","stem":"온실 가스에 대해 바르게 말한 것은 무엇인가요?","options":[{"t":"이산화 탄소, 메탄처럼 지구 표면의 온도를 상승시키는 원인이 되는 기체이다","correct":true},{"t":"지구 표면을 시원하게 만드는 기체이다","mis":"SC4-2-u2-X44"},{"t":"곤충이 먹는 먹이의 이름이다","mis":"SC4-2-u2-X44"},{"t":"곤충을 기를 때 가장 많이 나온다","mis":"SC4-2-u2-X43"}],"explanation":["온실 가스의 뜻을 떠올려요.","온도를 상승시켜요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u2_L07_challenge#6','sci',4,2,'u2','L07','g4_2_sci_u2_L07_challenge','lesson_challenge','SC4-2-u2-C29',3,'ox','auto','곤충이면 어떤 것이든 먹을 수 있어요.',ARRAY['SC4-2-u2-X41']::text[],false,'{"seq":6,"concept":"SC4-2-u2-C29","difficulty":3,"kind":"ox","stem":"곤충이면 어떤 것이든 먹을 수 있어요.","answer":"X","reason_options":[{"t":"우리나라가 먹을 수 있는 종류로 인정한 곤충만 먹을 수 있기 때문에","correct":true},{"t":"모든 곤충은 맛이 좋고 영양가가 높기 때문에","mis":"SC4-2-u2-X41"}],"mis":"SC4-2-u2-X41","explanation":["현재를 떠올려요.","인정한 종류가 있어요.","그래서 X예요."],"asset":{"type":"passage","lines":["예로부터 — 우리 조상들은 메뚜기나 누에 번데기를 즐겨 먹었어요.","현재 — 우리나라는 곤충을 먹을 수 있는 종류로 인정하고 있어요.","앞으로 — ㉠"],"title":"곤충을 먹는 일의 때"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u2_L07_challenge#7','sci',4,2,'u2','L07','g4_2_sci_u2_L07_challenge','lesson_challenge','SC4-2-u2-C31',3,'mc','auto','곤충 요리 전문가가 새로운 요리를 만들 때 가장 알맞은 생각은 무엇인가요?',ARRAY['SC4-2-u2-X41','SC4-2-u2-X43']::text[],false,'{"seq":7,"concept":"SC4-2-u2-C31","difficulty":3,"kind":"mc","stem":"곤충 요리 전문가가 새로운 요리를 만들 때 가장 알맞은 생각은 무엇인가요?","options":[{"t":"「먹을 수 있는 곤충으로, 원래 모습이 잘 드러나지 않게 맛있는 요리를 만들어 보자.」","correct":true},{"t":"「아무 곤충이나 잡아서 모습 그대로 내놓자.」","mis":"SC4-2-u2-X41"},{"t":"「곤충은 징그러우니 요리하지 말자.」","mis":"SC4-2-u2-X41"},{"t":"「온실 가스가 많이 나오게 가축을 함께 기르자.」","mis":"SC4-2-u2-X43"}],"explanation":["곤충 요리를 떠올려요.","인정한 곤충, 모습이 드러나지 않게예요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u2_L07_challenge#8','sci',4,2,'u2','L07','g4_2_sci_u2_L07_challenge','lesson_challenge','SC4-2-u2-C30',4,'mc','auto','친구가 「곤충 요리는 징그럽기만 하고 환경에도 도움이 안 돼.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?',ARRAY['SC4-2-u2-X41','SC4-2-u2-X43','SC4-2-u2-X44']::text[],false,'{"seq":8,"concept":"SC4-2-u2-C30","difficulty":4,"kind":"mc","stem":"친구가 「곤충 요리는 징그럽기만 하고 환경에도 도움이 안 돼.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?","options":[{"t":"「곤충은 맛이 좋고 영양가가 높아. 또 가축과 달리 먹이를 훨씬 적게 먹고 온실 가스를 거의 배출하지 않아서 환경에도 좋아.」","correct":true},{"t":"「맞아, 곤충은 먹을거리가 될 수 없어.」","mis":"SC4-2-u2-X41"},{"t":"「곤충은 가축보다 온실 가스를 더 많이 배출해.」","mis":"SC4-2-u2-X43"},{"t":"「온실 가스는 지구 표면을 시원하게 해 줘서 괜찮아.」","mis":"SC4-2-u2-X44"}],"explanation":["곤충의 장점을 떠올려요.","맛, 영양, 먹이, 온실 가스예요.","첫 번째가 알맞아요."],"asset":{"type":"passage","lines":["곤충을 기를 때 — 먹이: 훨씬 적게 먹어요 / 온실 가스: 거의 배출하지 않아요","가축을 기를 때 — 먹이: 곤충보다 훨씬 많이 먹어요 / 온실 가스: 배출해요"],"title":"곤충과 가축 견주어 보기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u2_L07_challenge#9','sci',4,2,'u2','L07','g4_2_sci_u2_L07_challenge','lesson_challenge','SC4-2-u2-C31',4,'mc','auto','곤충 요리를 「미래 식량」이라고 부르는데 우리 조상들은 이미 곤충을 먹어 왔어요. 그런데도 앞으로 더 관심을 받는 까닭은 무엇인가요?',ARRAY['SC4-2-u2-X42','SC4-2-u2-X41','SC4-2-u2-X43']::text[],false,'{"seq":9,"concept":"SC4-2-u2-C31","difficulty":4,"kind":"mc","stem":"곤충 요리를 「미래 식량」이라고 부르는데 우리 조상들은 이미 곤충을 먹어 왔어요. 그런데도 앞으로 더 관심을 받는 까닭은 무엇인가요?","options":[{"t":"맛이 좋고 영양가 높은 다양한 곤충을 찾아내고 새로운 요리 방법을 개발할 수 있기 때문에","correct":true},{"t":"예로부터 아무도 곤충을 먹지 않았기 때문에","mis":"SC4-2-u2-X42"},{"t":"먹을 수 있는 곤충이 한 종류뿐이기 때문에","mis":"SC4-2-u2-X41"},{"t":"곤충이 가축보다 먹이를 훨씬 많이 먹기 때문에","mis":"SC4-2-u2-X43"}],"explanation":["「앞으로」를 떠올려요.","찾아내고 개발해요.","첫 번째예요."],"asset":{"type":"passage","lines":["예로부터 — 우리 조상들은 메뚜기나 누에 번데기를 즐겨 먹었어요.","현재 — 우리나라는 곤충을 먹을 수 있는 종류로 인정하고 있어요.","앞으로 — ㉠"],"title":"곤충을 먹는 일의 때"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u2_L07_challenge#10','sci',4,2,'u2','L07','g4_2_sci_u2_L07_challenge','lesson_challenge','SC4-2-u2-C30',4,'essay','teacher','곤충 요리가 친환경 미래 식량으로 관심을 받는 까닭을 가축과 견주어 두 가지 쓰고, 내가 곤충 요리 전문가가 된다면 어떤 일을 하고 싶은지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC4-2-u2-C30","difficulty":4,"kind":"essay","stem":"곤충 요리가 친환경 미래 식량으로 관심을 받는 까닭을 가축과 견주어 두 가지 쓰고, 내가 곤충 요리 전문가가 된다면 어떤 일을 하고 싶은지 쓰세요.","answer_guide":{"answer":"예: 곤충은 가축과 달리 기를 때 먹이를 훨씬 적게 먹고, 온실 가스를 거의 배출하지 않는다. 내가 곤충 요리 전문가가 된다면 먹을 수 있는 곤충을 찾아내어 원래 모습이 잘 드러나지 않는 맛있는 요리 방법을 개발하고 싶다.","scoring_points":["먹이를 가축과 견주어 썼는가","온실 가스를 가축과 견주어 썼는가","전문가로서 하고 싶은 일을 썼는가"]},"explanation":["견주어 보기를 읽어요.","두 줄을 견줘요.","하고 싶은 일을 써요."],"asset":{"type":"passage","lines":["곤충을 기를 때 — 먹이: 훨씬 적게 먹어요 / 온실 가스: 거의 배출하지 않아요","가축을 기를 때 — 먹이: 곤충보다 훨씬 많이 먹어요 / 온실 가스: 배출해요"],"title":"곤충과 가축 견주어 보기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u2_review_a#1','sci',4,2,'u2','','g4_2_sci_u2_review_a','unit_review','SC4-2-u2-C1',1,'mc','auto','초록반 일지 ①에서 물속을 꾸민 모둠이 표현한 생물은 무엇인가요?',ARRAY['SC4-2-u2-X01']::text[],false,'{"seq":1,"concept":"SC4-2-u2-C1","difficulty":1,"kind":"mc","stem":"초록반 일지 ①에서 물속을 꾸민 모둠이 표현한 생물은 무엇인가요?","options":[{"t":"붕어","correct":true},{"t":"토끼","mis":"SC4-2-u2-X01"},{"t":"다람쥐","mis":"SC4-2-u2-X01"},{"t":"노루","mis":"SC4-2-u2-X01"}],"explanation":["셋째 줄을 읽어요.","물속 쪽을 봐요.","붕어예요."],"asset":{"type":"passage","lines":["모둠마다 땅에 떨어진 나뭇잎, 나뭇가지, 열매를 주워 모았다.","한 모둠은 숲을, 다른 모둠은 물속을 흰 종이에 꾸몄다.","숲 — 토끼, 다람쥐, 노루 / 물속 — 붕어, 송사리, 물방개","다짐 — 잘 만드는 것보다 함께 참여하기"],"title":"초록반 일지 ① 나뭇잎 작품"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u2_review_a#2','sci',4,2,'u2','','g4_2_sci_u2_review_a','unit_review','SC4-2-u2-C5',1,'mc','auto','초록반 일지 ②에서 살아 있지 않은 것은 무엇인가요?',ARRAY['SC4-2-u2-X08']::text[],false,'{"seq":2,"concept":"SC4-2-u2-C5","difficulty":1,"kind":"mc","stem":"초록반 일지 ②에서 살아 있지 않은 것은 무엇인가요?","options":[{"t":"흙","correct":true},{"t":"붕어","mis":"SC4-2-u2-X08"},{"t":"부들","mis":"SC4-2-u2-X08"},{"t":"개구리","mis":"SC4-2-u2-X08"}],"explanation":["셋째 줄을 읽어요.","살아 있지 않아요.","흙이에요."],"asset":{"type":"passage","lines":["학교 연못을 조사했다.","살아 있는 것 — 붕어, 개구리, 부들, 검정말","살아 있지 않은 것 — 햇빛, 물, 공기, 흙, 온도","친구 가 — 「작은 연못도 생태계구나.」"],"title":"초록반 일지 ② 학교 연못 조사"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u2_review_a#3','sci',4,2,'u2','','g4_2_sci_u2_review_a','unit_review','SC4-2-u2-C12',1,'mc','auto','초록반 일지 ③에서 분해자는 무엇인가요?',ARRAY['SC4-2-u2-X17']::text[],false,'{"seq":3,"concept":"SC4-2-u2-C12","difficulty":1,"kind":"mc","stem":"초록반 일지 ③에서 분해자는 무엇인가요?","options":[{"t":"곰팡이","correct":true},{"t":"부들","mis":"SC4-2-u2-X17"},{"t":"붕어","mis":"SC4-2-u2-X17"},{"t":"개구리","mis":"SC4-2-u2-X17"}],"explanation":["셋째 줄을 읽어요.","죽은 몸을 분해해요.","곰팡이예요."],"asset":{"type":"passage","lines":["부들, 검정말 — 햇빛을 이용하여 스스로 양분을 만든다.","붕어, 개구리 — 다른 생물을 먹어 양분을 얻는다.","곰팡이, 세균 — 죽은 몸이나 배출물을 분해한다.","연못가 나무 밑동에서 버섯을 보았다."],"title":"초록반 일지 ③ 연못 생물 나누기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u2_review_a#4','sci',4,2,'u2','','g4_2_sci_u2_review_a','unit_review','SC4-2-u2-C14',1,'mc','auto','초록반 일지 ④의 한 줄로 이은 것에서 메뚜기를 먹는 생물은 무엇인가요?',ARRAY['SC4-2-u2-X20','SC4-2-u2-X22']::text[],false,'{"seq":4,"concept":"SC4-2-u2-C14","difficulty":1,"kind":"mc","stem":"초록반 일지 ④의 한 줄로 이은 것에서 메뚜기를 먹는 생물은 무엇인가요?","options":[{"t":"개구리","correct":true},{"t":"벼","mis":"SC4-2-u2-X20"},{"t":"뱀","mis":"SC4-2-u2-X20"},{"t":"도토리","mis":"SC4-2-u2-X22"}],"explanation":["첫 줄을 읽어요.","메뚜기 다음이에요.","개구리예요."],"asset":{"type":"passage","lines":["한 줄로 이은 것 — 벼 → 메뚜기 → 개구리 → 뱀","메뚜기는 벼뿐 아니라 질경이도 먹는다.","메뚜기는 개구리뿐 아니라 직박구리의 먹이도 된다.","다람쥐는 도토리를 먹는다."],"title":"초록반 일지 ④ 먹이 관계 모형"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u2_review_a#5','sci',4,2,'u2','','g4_2_sci_u2_review_a','unit_review','SC4-2-u2-C20',1,'mc','auto','초록반 일지 ⑤에서 하천에 버려진 쓰레기와 관련 있는 환경오염은 무엇인가요?',ARRAY['SC4-2-u2-X29','SC4-2-u2-X30']::text[],false,'{"seq":5,"concept":"SC4-2-u2-C20","difficulty":1,"kind":"mc","stem":"초록반 일지 ⑤에서 하천에 버려진 쓰레기와 관련 있는 환경오염은 무엇인가요?","options":[{"t":"수질오염","correct":true},{"t":"대기오염","mis":"SC4-2-u2-X29"},{"t":"토양오염","mis":"SC4-2-u2-X29"},{"t":"관련 없음","mis":"SC4-2-u2-X30"}],"explanation":["첫 줄을 읽어요.","물이 더러워져요.","수질오염이에요."],"asset":{"type":"passage","lines":["하천에 버려진 쓰레기 — 수질오염","자동차에서 나오는 배기가스 — 대기오염, 수질오염","논밭에 지나치게 많이 쓴 농약 — 토양오염, 수질오염","조사한 자료마다 출처를 적었다."],"title":"초록반 일지 ⑤ 환경오염 조사"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u2_review_a#6','sci',4,2,'u2','','g4_2_sci_u2_review_a','unit_review','SC4-2-u2-C25',1,'mc','auto','초록반 일지 ⑥에서 생태계 지킴이 활동을 한 장소는 어디인가요?',ARRAY['SC4-2-u2-X35']::text[],false,'{"seq":6,"concept":"SC4-2-u2-C25","difficulty":1,"kind":"mc","stem":"초록반 일지 ⑥에서 생태계 지킴이 활동을 한 장소는 어디인가요?","options":[{"t":"학교 뒷산 등산로","correct":true},{"t":"학교 연못","mis":"SC4-2-u2-X35"},{"t":"교실 게시판","mis":"SC4-2-u2-X35"},{"t":"바닷가","mis":"SC4-2-u2-X35"}],"explanation":["첫 줄을 읽어요.","풀이 없어졌어요.","학교 뒷산 등산로예요."],"asset":{"type":"passage","lines":["장소 — 풀이 없어지고 길이 넓어진 학교 뒷산 등산로","실천 방법 — 안내 팻말 세우기, 정해진 길로만 다니기","사진을 찍으러 갈 때 다치지 않게 조심했다.","친구 나 — 「반짝이를 더 붙여야 최고의 자료가 돼.」"],"title":"초록반 일지 ⑥ 생태계 지킴이"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u2_review_a#7','sci',4,2,'u2','','g4_2_sci_u2_review_a','unit_review','SC4-2-u2-C28',1,'mc','auto','초록반 일지 ⑦에서 팻말 ①을 붙였을 때 빠진 것은 무엇인가요?',ARRAY['SC4-2-u2-X40','SC4-2-u2-X39']::text[],false,'{"seq":7,"concept":"SC4-2-u2-C28","difficulty":1,"kind":"mc","stem":"초록반 일지 ⑦에서 팻말 ①을 붙였을 때 빠진 것은 무엇인가요?","options":[{"t":"흙, 물, 햇빛","correct":true},{"t":"옥수수, 메뚜기, 참새","mis":"SC4-2-u2-X40"},{"t":"상어, 노루, 세균","mis":"SC4-2-u2-X39"},{"t":"하나도 빠지지 않았다","mis":"SC4-2-u2-X40"}],"explanation":["둘째 줄을 읽어요.","살아 있지 않은 것이에요.","흙, 물, 햇빛이에요."],"asset":{"type":"passage","lines":["팻말 없이 — 열한 가지가 모두 지날 수 있었다.","팻말 ① 생물요소만 — 흙, 물, 햇빛이 빠졌다.","팻말 ② 올바른 먹이사슬 — 네 가지만 남았다.","남은 길 — 옥수수 → 메뚜기 → 참새 → 새매"],"title":"초록반 일지 ⑦ 숲의 미로"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u2_review_a#8','sci',4,2,'u2','','g4_2_sci_u2_review_a','unit_review','SC4-2-u2-C29',1,'mc','auto','초록반 일지 ⑧에서 조상들이 즐겨 먹은 곤충은 무엇인가요?',ARRAY['SC4-2-u2-X42']::text[],false,'{"seq":8,"concept":"SC4-2-u2-C29","difficulty":1,"kind":"mc","stem":"초록반 일지 ⑧에서 조상들이 즐겨 먹은 곤충은 무엇인가요?","options":[{"t":"메뚜기","correct":true},{"t":"나비","mis":"SC4-2-u2-X42"},{"t":"잠자리","mis":"SC4-2-u2-X42"},{"t":"개미","mis":"SC4-2-u2-X42"}],"explanation":["첫 줄을 읽어요.","누에 번데기도 있어요.","메뚜기예요."],"asset":{"type":"passage","lines":["조상들은 메뚜기나 누에 번데기를 즐겨 먹었다.","곤충은 가축과 달리 먹이를 훨씬 적게 먹는다.","곤충은 온실 가스를 거의 배출하지 않는다.","친구 다 — 「곤충이면 아무거나 먹어도 되겠다.」"],"title":"초록반 일지 ⑧ 곤충 요리 탐구"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u2_review_a#9','sci',4,2,'u2','','g4_2_sci_u2_review_a','unit_review','SC4-2-u2-C1',2,'match','auto','생물과 알맞은 설명을 이으세요.','{}'::text[],false,'{"seq":9,"concept":"SC4-2-u2-C1","difficulty":2,"kind":"match","stem":"생물과 알맞은 설명을 이으세요.","pairs":[{"l":"노루","r":"숲에 사는 동물"},{"l":"송사리","r":"물속에 사는 동물"},{"l":"부들","r":"물속에 사는 식물"},{"l":"소나무","r":"숲에 사는 식물"}],"mis":"SC4-2-u2-X01","explanation":["사는 곳을 떠올려요.","동물인지 식물인지도 봐요.","노루-숲 동물, 송사리-물속 동물, 부들-물속 식물, 소나무-숲 식물이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u2_review_a#10','sci',4,2,'u2','','g4_2_sci_u2_review_a','unit_review','SC4-2-u2-C7',2,'match','auto','비생물요소와 필요한 까닭을 바르게 이으세요.','{}'::text[],false,'{"seq":10,"concept":"SC4-2-u2-C7","difficulty":2,"kind":"match","stem":"비생물요소와 필요한 까닭을 바르게 이으세요.","pairs":[{"l":"햇빛","r":"식물이 양분을 만드는 데 이용해요"},{"l":"온도","r":"살아가는 데 알맞은 환경을 줘요"},{"l":"흙","r":"땅속 생물이 사는 장소예요"}],"mis":"SC4-2-u2-X11","explanation":["하나씩 떠올려요.","햇빛은 양분이에요.","햇빛-양분, 온도-환경, 흙-땅속 생물이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u2_review_a#11','sci',4,2,'u2','','g4_2_sci_u2_review_a','unit_review','SC4-2-u2-C9',2,'match','auto','생물과 하는 역할에 따른 무리를 알맞게 이으세요.','{}'::text[],false,'{"seq":11,"concept":"SC4-2-u2-C9","difficulty":2,"kind":"match","stem":"생물과 하는 역할에 따른 무리를 알맞게 이으세요.","pairs":[{"l":"강아지풀","r":"생산자"},{"l":"왜가리","r":"소비자"},{"l":"세균","r":"분해자"}],"mis":"SC4-2-u2-X13","explanation":["양분을 얻는 방법을 떠올려요.","세균은 분해해요.","강아지풀-생산자, 왜가리-소비자, 세균-분해자예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u2_review_a#12','sci',4,2,'u2','','g4_2_sci_u2_review_a','unit_review','SC4-2-u2-C14',2,'match','auto','말과 뜻을 알맞게 이으세요.','{}'::text[],false,'{"seq":12,"concept":"SC4-2-u2-C14","difficulty":2,"kind":"match","stem":"말과 뜻을 알맞게 이으세요.","pairs":[{"l":"먹이사슬","r":"먹이 관계가 사슬처럼 연결된 것"},{"l":"먹이그물","r":"여러 먹이사슬이 그물처럼 얽힌 것"},{"l":"화살표","r":"먹히는 생물에서 먹는 생물 쪽으로 그려요"}],"mis":"SC4-2-u2-X21","explanation":["사슬과 그물을 떠올려요.","화살표 방향도 있어요.","차례대로 이어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u2_review_a#13','sci',4,2,'u2','','g4_2_sci_u2_review_a','unit_review','SC4-2-u2-C17',2,'mc','auto','먹고 먹히는 관계에 대해 바르게 말한 것은 무엇인가요?',ARRAY['SC4-2-u2-X25']::text[],false,'{"seq":13,"concept":"SC4-2-u2-C17","difficulty":2,"kind":"mc","stem":"먹고 먹히는 관계에 대해 바르게 말한 것은 무엇인가요?","options":[{"t":"몸집 크기로 정해지지 않고, 물고기가 새를 잡아먹는 것처럼 반대로 연결되기도 한다","correct":true},{"t":"늘 큰 생물이 작은 생물을 먹는다","mis":"SC4-2-u2-X25"},{"t":"물고기는 언제나 새에게 먹힌다","mis":"SC4-2-u2-X25"},{"t":"작은 생물은 다른 생물을 먹지 않는다","mis":"SC4-2-u2-X25"}],"explanation":["골리앗타이거피시를 떠올려요.","새를 낚아채요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u2_review_a#14','sci',4,2,'u2','','g4_2_sci_u2_review_a','unit_review','SC4-2-u2-C20',2,'match','auto','환경오염의 원인과 종류를 바르게 이으세요.','{}'::text[],false,'{"seq":14,"concept":"SC4-2-u2-C20","difficulty":2,"kind":"match","stem":"환경오염의 원인과 종류를 바르게 이으세요.","pairs":[{"l":"생활 쓰레기의 매립","r":"토양오염"},{"l":"기름 유출","r":"수질오염"},{"l":"미세 먼지","r":"대기오염"}],"mis":"SC4-2-u2-X29","explanation":["원인을 하나씩 떠올려요.","기름은 바다나 강으로 퍼져요.","매립-토양, 기름-수질, 미세 먼지-대기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u2_review_a#15','sci',4,2,'u2','','g4_2_sci_u2_review_a','unit_review','SC4-2-u2-C22',2,'match','auto','생태계보전을 위한 노력과 줄어드는 것을 알맞게 이으세요.','{}'::text[],false,'{"seq":15,"concept":"SC4-2-u2-C22","difficulty":2,"kind":"match","stem":"생태계보전을 위한 노력과 줄어드는 것을 알맞게 이으세요.","pairs":[{"l":"자전거 타고 다니기","r":"자동차 배기가스"},{"l":"분리배출 하기","r":"버려지는 쓰레기"},{"l":"세제를 적당한 양만 쓰기","r":"물을 더럽히는 것"}],"mis":"SC4-2-u2-X31","explanation":["노력을 하나씩 떠올려요.","무엇이 줄어들까요?","차례대로 이어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u2_review_a#16','sci',4,2,'u2','','g4_2_sci_u2_review_a','unit_review','SC4-2-u2-C30',2,'match','auto','곤충과 가축을 견주어 알맞게 이으세요.','{}'::text[],false,'{"seq":16,"concept":"SC4-2-u2-C30","difficulty":2,"kind":"match","stem":"곤충과 가축을 견주어 알맞게 이으세요.","pairs":[{"l":"곤충의 먹이","r":"훨씬 적게 먹어요"},{"l":"가축의 먹이","r":"곤충보다 훨씬 많이 먹어요"},{"l":"곤충의 온실 가스","r":"거의 배출하지 않아요"}],"mis":"SC4-2-u2-X43","explanation":["견주어 보기를 떠올려요.","곤충이 적어요.","차례대로 이어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u2_review_a#17','sci',4,2,'u2','','g4_2_sci_u2_review_a','unit_review','SC4-2-u2-C5',3,'error','auto','초록반 일지 ②를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC4-2-u2-X07','SC4-2-u2-X08','SC4-2-u2-X06']::text[],false,'{"seq":17,"concept":"SC4-2-u2-C5","difficulty":3,"kind":"error","stem":"초록반 일지 ②를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「물은 연못 어디에나 있으니까 생물요소야.」","correct":true,"mis_target":"SC4-2-u2-X07"},{"t":"친구 가 — 「부들은 움직이지 않아도 살아 있으니 생물요소야.」","mis":"SC4-2-u2-X08"},{"t":"친구 나 — 「연못도 두 요소가 다 있으니 생태계야.」","mis":"SC4-2-u2-X06"}],"explanation":["물을 떠올려요.","살아 있지 않아요.","친구 다가 잘못 말했어요."],"asset":{"type":"passage","lines":["학교 연못을 조사했다.","살아 있는 것 — 붕어, 개구리, 부들, 검정말","살아 있지 않은 것 — 햇빛, 물, 공기, 흙, 온도","친구 가 — 「작은 연못도 생태계구나.」"],"title":"초록반 일지 ② 학교 연못 조사"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u2_review_a#18','sci',4,2,'u2','','g4_2_sci_u2_review_a','unit_review','SC4-2-u2-C13',3,'error','auto','초록반 일지 ③을 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC4-2-u2-X18','SC4-2-u2-X16','SC4-2-u2-X15']::text[],false,'{"seq":18,"concept":"SC4-2-u2-C13","difficulty":3,"kind":"error","stem":"초록반 일지 ③을 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 나 — 「버섯은 식물처럼 생겼으니 부들과 같은 무리야.」","correct":true,"mis_target":"SC4-2-u2-X18"},{"t":"친구 가 — 「곰팡이와 세균도 살아 있는 생물요소야.」","mis":"SC4-2-u2-X16"},{"t":"친구 다 — 「붕어는 다른 생물을 먹으니 소비자야.」","mis":"SC4-2-u2-X15"}],"explanation":["버섯을 떠올려요.","버섯은 분해자예요.","친구 나가 잘못 말했어요."],"asset":{"type":"passage","lines":["부들, 검정말 — 햇빛을 이용하여 스스로 양분을 만든다.","붕어, 개구리 — 다른 생물을 먹어 양분을 얻는다.","곰팡이, 세균 — 죽은 몸이나 배출물을 분해한다.","연못가 나무 밑동에서 버섯을 보았다."],"title":"초록반 일지 ③ 연못 생물 나누기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u2_review_a#19','sci',4,2,'u2','','g4_2_sci_u2_review_a','unit_review','SC4-2-u2-C16',3,'error','auto','초록반 일지 ④를 보고 메뚜기가 사라지면 어떻게 될지 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC4-2-u2-X23','SC4-2-u2-X22','SC4-2-u2-X24']::text[],false,'{"seq":19,"concept":"SC4-2-u2-C16","difficulty":3,"kind":"error","stem":"초록반 일지 ④를 보고 메뚜기가 사라지면 어떻게 될지 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 가 — 「모형에 있는 생물이 모두 한꺼번에 사라질 거야.」","correct":true,"mis_target":"SC4-2-u2-X23"},{"t":"친구 나 — 「직박구리는 메뚜기 말고 다른 먹이를 먹을 수 있을지도 몰라.」","mis":"SC4-2-u2-X22"},{"t":"친구 다 — 「다람쥐는 크게 변하지 않을 거야.」","mis":"SC4-2-u2-X24"}],"explanation":["직접 관계를 따져요.","모두 사라지지 않아요.","친구 가가 잘못 말했어요."],"asset":{"type":"passage","lines":["한 줄로 이은 것 — 벼 → 메뚜기 → 개구리 → 뱀","메뚜기는 벼뿐 아니라 질경이도 먹는다.","메뚜기는 개구리뿐 아니라 직박구리의 먹이도 된다.","다람쥐는 도토리를 먹는다."],"title":"초록반 일지 ④ 먹이 관계 모형"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u2_review_a#20','sci',4,2,'u2','','g4_2_sci_u2_review_a','unit_review','SC4-2-u2-C20',3,'error','auto','초록반 일지 ⑤를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC4-2-u2-X28','SC4-2-u2-X29','SC4-2-u2-X33']::text[],false,'{"seq":20,"concept":"SC4-2-u2-C20","difficulty":3,"kind":"error","stem":"초록반 일지 ⑤를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「배기가스는 대기오염 한 가지만 일으켜.」","correct":true,"mis_target":"SC4-2-u2-X28"},{"t":"친구 가 — 「하천 쓰레기는 수질오염을 일으켜.」","mis":"SC4-2-u2-X29"},{"t":"친구 나 — 「자료의 출처를 적어 두니 확인하기 좋아.」","mis":"SC4-2-u2-X33"}],"explanation":["둘째 줄을 읽어요.","두 가지예요.","친구 다가 잘못 말했어요."],"asset":{"type":"passage","lines":["하천에 버려진 쓰레기 — 수질오염","자동차에서 나오는 배기가스 — 대기오염, 수질오염","논밭에 지나치게 많이 쓴 농약 — 토양오염, 수질오염","조사한 자료마다 출처를 적었다."],"title":"초록반 일지 ⑤ 환경오염 조사"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u2_review_a#21','sci',4,2,'u2','','g4_2_sci_u2_review_a','unit_review','SC4-2-u2-C27',3,'error','auto','초록반 일지 ⑥을 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC4-2-u2-X38','SC4-2-u2-X35','SC4-2-u2-X37']::text[],false,'{"seq":21,"concept":"SC4-2-u2-C27","difficulty":3,"kind":"error","stem":"초록반 일지 ⑥을 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 나 — 「반짝이를 더 붙여야 최고의 자료가 돼.」","correct":true,"mis_target":"SC4-2-u2-X38"},{"t":"친구 가 — 「등산로의 문제점이 잘 드러났어.」","mis":"SC4-2-u2-X35"},{"t":"친구 다 — 「정해진 길로 다니기는 우리가 실천할 수 있어.」","mis":"SC4-2-u2-X37"}],"explanation":["좋은 자료의 기준을 떠올려요.","꾸밈이 아니에요.","친구 나가 잘못 말했어요."],"asset":{"type":"passage","lines":["장소 — 풀이 없어지고 길이 넓어진 학교 뒷산 등산로","실천 방법 — 안내 팻말 세우기, 정해진 길로만 다니기","사진을 찍으러 갈 때 다치지 않게 조심했다.","친구 나 — 「반짝이를 더 붙여야 최고의 자료가 돼.」"],"title":"초록반 일지 ⑥ 생태계 지킴이"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u2_review_a#22','sci',4,2,'u2','','g4_2_sci_u2_review_a','unit_review','SC4-2-u2-C29',3,'error','auto','초록반 일지 ⑧을 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC4-2-u2-X41','SC4-2-u2-X42','SC4-2-u2-X43']::text[],false,'{"seq":22,"concept":"SC4-2-u2-C29","difficulty":3,"kind":"error","stem":"초록반 일지 ⑧을 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「곤충이면 아무거나 먹어도 되겠다.」","correct":true,"mis_target":"SC4-2-u2-X41"},{"t":"친구 가 — 「조상들도 메뚜기를 먹었구나.」","mis":"SC4-2-u2-X42"},{"t":"친구 나 — 「곤충은 온실 가스를 거의 배출하지 않아.」","mis":"SC4-2-u2-X43"}],"explanation":["먹을 수 있는 곤충을 떠올려요.","인정한 종류만이에요.","친구 다가 잘못 말했어요."],"asset":{"type":"passage","lines":["조상들은 메뚜기나 누에 번데기를 즐겨 먹었다.","곤충은 가축과 달리 먹이를 훨씬 적게 먹는다.","곤충은 온실 가스를 거의 배출하지 않는다.","친구 다 — 「곤충이면 아무거나 먹어도 되겠다.」"],"title":"초록반 일지 ⑧ 곤충 요리 탐구"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u2_review_a#23','sci',4,2,'u2','','g4_2_sci_u2_review_a','unit_review','SC4-2-u2-C5',4,'essay','teacher','초록반 일지 ②를 보고 학교 연못이 생태계인 까닭을 쓰고, 연못의 구성 요소를 생물요소와 비생물요소로 나누어 두 가지씩 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"SC4-2-u2-C5","difficulty":4,"kind":"essay","stem":"초록반 일지 ②를 보고 학교 연못이 생태계인 까닭을 쓰고, 연못의 구성 요소를 생물요소와 비생물요소로 나누어 두 가지씩 쓰세요.","answer_guide":{"answer":"예: 학교 연못에는 생물요소와 비생물요소가 모두 있으므로 생태계이다. 생물요소에는 붕어, 부들이 있고, 비생물요소에는 햇빛, 물이 있다.","scoring_points":["생태계인 까닭을 썼는가","생물요소 두 가지를 썼는가","비생물요소 두 가지를 썼는가"]},"explanation":["일지를 읽어요.","까닭을 써요.","두 칸으로 나눠요."],"asset":{"type":"passage","lines":["학교 연못을 조사했다.","살아 있는 것 — 붕어, 개구리, 부들, 검정말","살아 있지 않은 것 — 햇빛, 물, 공기, 흙, 온도","친구 가 — 「작은 연못도 생태계구나.」"],"title":"초록반 일지 ② 학교 연못 조사"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u2_review_a#24','sci',4,2,'u2','','g4_2_sci_u2_review_a','unit_review','SC4-2-u2-C5',4,'mc','auto','친구가 「햇빛은 숲에만 있으니까 비생물요소야.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?',ARRAY['SC4-2-u2-X09','SC4-2-u2-X07','SC4-2-u2-X12']::text[],false,'{"seq":24,"concept":"SC4-2-u2-C5","difficulty":4,"kind":"mc","stem":"친구가 「햇빛은 숲에만 있으니까 비생물요소야.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?","options":[{"t":"「햇빛은 숲, 강, 바다 어디에나 있어. 비생물요소인 까닭은 살아 있지 않기 때문이야.」","correct":true},{"t":"「맞아, 숲에만 있어서 비생물요소야.」","mis":"SC4-2-u2-X09"},{"t":"「햇빛은 밝게 빛나니까 생물요소야.」","mis":"SC4-2-u2-X07"},{"t":"「햇빛은 생물에게 필요 없어.」","mis":"SC4-2-u2-X12"}],"explanation":["까닭을 따져요.","어디에나 있었어요.","첫 번째가 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u2_review_a#25','sci',4,2,'u2','','g4_2_sci_u2_review_a','unit_review','SC4-2-u2-C25',4,'essay','teacher','초록반 일지 ⑥을 보고 생태계 지킴이 활동을 계획해요, 실행해요, 실천해요 차례로 정리해 쓰고, 친구 나의 말을 바르게 고쳐 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"SC4-2-u2-C25","difficulty":4,"kind":"essay","stem":"초록반 일지 ⑥을 보고 생태계 지킴이 활동을 계획해요, 실행해요, 실천해요 차례로 정리해 쓰고, 친구 나의 말을 바르게 고쳐 쓰세요.","answer_guide":{"answer":"예: 계획해요 — 보전이 필요한 까닭, 갈 장소, 모둠원의 역할을 정한다. 실행해요 — 뒷산 등산로를 찾아 사진을 찍고 해결 방법을 토의해 발표 자료를 만든다. 실천해요 — 발표하고 생활 속에서 정해진 길로만 다닌다. 반짝이를 더 붙인다고 좋은 자료가 되는 것이 아니라 문제점과 실천할 수 있는 해결 방법이 잘 드러나야 한다.","scoring_points":["세 단계를 차례대로 썼는가","단계마다 할 일을 알맞게 썼는가","친구 나의 말을 바르게 고쳤는가"]},"explanation":["일지를 읽어요.","세 단계를 써요.","고쳐 써요."],"asset":{"type":"passage","lines":["장소 — 풀이 없어지고 길이 넓어진 학교 뒷산 등산로","실천 방법 — 안내 팻말 세우기, 정해진 길로만 다니기","사진을 찍으러 갈 때 다치지 않게 조심했다.","친구 나 — 「반짝이를 더 붙여야 최고의 자료가 돼.」"],"title":"초록반 일지 ⑥ 생태계 지킴이"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u2_review_b#1','sci',4,2,'u2','','g4_2_sci_u2_review_b','unit_review','SC4-2-u2-C2',1,'sa','auto','초록반 일지 ①에서 모은 나뭇잎을 붙여 꾸민 종이는 무슨 색인가요? 한 글자로 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"SC4-2-u2-C2","difficulty":1,"kind":"sa","stem":"초록반 일지 ①에서 모은 나뭇잎을 붙여 꾸민 종이는 무슨 색인가요? 한 글자로 쓰세요.","answer":["흰","흰색","하얀","흰 종이"],"explanation":["둘째 줄을 읽어요.","○ 종이예요.","흰 종이예요."],"asset":{"type":"passage","lines":["모둠마다 땅에 떨어진 나뭇잎, 나뭇가지, 열매를 주워 모았다.","한 모둠은 숲을, 다른 모둠은 물속을 흰 종이에 꾸몄다.","숲 — 토끼, 다람쥐, 노루 / 물속 — 붕어, 송사리, 물방개","다짐 — 잘 만드는 것보다 함께 참여하기"],"title":"초록반 일지 ① 나뭇잎 작품"},"mis":"SC4-2-u2-X02"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u2_review_b#2','sci',4,2,'u2','','g4_2_sci_u2_review_b','unit_review','SC4-2-u2-C5',1,'sa','auto','초록반 일지 ②에서 살아 있는 것을 무엇이라고 하나요? 네 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SC4-2-u2-C5","difficulty":1,"kind":"sa","stem":"초록반 일지 ②에서 살아 있는 것을 무엇이라고 하나요? 네 글자로 쓰세요.","answer":["생물요소","생물 요소"],"explanation":["둘째 줄을 읽어요.","살아 있는 요소예요.","생물요소예요."],"asset":{"type":"passage","lines":["학교 연못을 조사했다.","살아 있는 것 — 붕어, 개구리, 부들, 검정말","살아 있지 않은 것 — 햇빛, 물, 공기, 흙, 온도","친구 가 — 「작은 연못도 생태계구나.」"],"title":"초록반 일지 ② 학교 연못 조사"},"mis":"SC4-2-u2-X07"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u2_review_b#3','sci',4,2,'u2','','g4_2_sci_u2_review_b','unit_review','SC4-2-u2-C10',1,'sa','auto','초록반 일지 ③에서 부들, 검정말처럼 스스로 양분을 만드는 생물 무리의 이름을 세 글자로 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"SC4-2-u2-C10","difficulty":1,"kind":"sa","stem":"초록반 일지 ③에서 부들, 검정말처럼 스스로 양분을 만드는 생물 무리의 이름을 세 글자로 쓰세요.","answer":["생산자"],"explanation":["첫 줄을 읽어요.","만드는 생물이에요.","생산자예요."],"asset":{"type":"passage","lines":["부들, 검정말 — 햇빛을 이용하여 스스로 양분을 만든다.","붕어, 개구리 — 다른 생물을 먹어 양분을 얻는다.","곰팡이, 세균 — 죽은 몸이나 배출물을 분해한다.","연못가 나무 밑동에서 버섯을 보았다."],"title":"초록반 일지 ③ 연못 생물 나누기"},"mis":"SC4-2-u2-X14"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u2_review_b#4','sci',4,2,'u2','','g4_2_sci_u2_review_b','unit_review','SC4-2-u2-C15',1,'sa','auto','초록반 일지 ④에서 메뚜기가 벼 말고 먹는 풀을 쓰세요.','{}'::text[],false,'{"seq":4,"concept":"SC4-2-u2-C15","difficulty":1,"kind":"sa","stem":"초록반 일지 ④에서 메뚜기가 벼 말고 먹는 풀을 쓰세요.","answer":["질경이"],"explanation":["둘째 줄을 읽어요.","다른 풀도 먹어요.","질경이예요."],"asset":{"type":"passage","lines":["한 줄로 이은 것 — 벼 → 메뚜기 → 개구리 → 뱀","메뚜기는 벼뿐 아니라 질경이도 먹는다.","메뚜기는 개구리뿐 아니라 직박구리의 먹이도 된다.","다람쥐는 도토리를 먹는다."],"title":"초록반 일지 ④ 먹이 관계 모형"},"mis":"SC4-2-u2-X22"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u2_review_b#5','sci',4,2,'u2','','g4_2_sci_u2_review_b','unit_review','SC4-2-u2-C19',1,'sa','auto','자연 생태계나 주변이 인간 활동으로 훼손되고 더럽혀지는 현상을 네 글자로 쓰세요.','{}'::text[],false,'{"seq":5,"concept":"SC4-2-u2-C19","difficulty":1,"kind":"sa","stem":"자연 생태계나 주변이 인간 활동으로 훼손되고 더럽혀지는 현상을 네 글자로 쓰세요.","answer":["환경오염","환경 오염"],"explanation":["인간 활동 때문이에요.","더럽혀져요.","환경오염이에요."],"mis":"SC4-2-u2-X27"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u2_review_b#6','sci',4,2,'u2','','g4_2_sci_u2_review_b','unit_review','SC4-2-u2-C24',1,'sa','auto','원래대로 회복한다는 뜻의 낱말을 두 글자로 쓰세요.','{}'::text[],false,'{"seq":6,"concept":"SC4-2-u2-C24","difficulty":1,"kind":"sa","stem":"원래대로 회복한다는 뜻의 낱말을 두 글자로 쓰세요.","answer":["복원"],"explanation":["되살리는 일이에요.","생태계○○이에요.","복원이에요."],"mis":"SC4-2-u2-X34"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u2_review_b#7','sci',4,2,'u2','','g4_2_sci_u2_review_b','unit_review','SC4-2-u2-C28',1,'sa','auto','초록반 일지 ⑦의 남은 길에서 메뚜기를 먹는 생물을 두 글자로 쓰세요.','{}'::text[],false,'{"seq":7,"concept":"SC4-2-u2-C28","difficulty":1,"kind":"sa","stem":"초록반 일지 ⑦의 남은 길에서 메뚜기를 먹는 생물을 두 글자로 쓰세요.","answer":["참새"],"explanation":["넷째 줄을 읽어요.","메뚜기 다음이에요.","참새예요."],"asset":{"type":"passage","lines":["팻말 없이 — 열한 가지가 모두 지날 수 있었다.","팻말 ① 생물요소만 — 흙, 물, 햇빛이 빠졌다.","팻말 ② 올바른 먹이사슬 — 네 가지만 남았다.","남은 길 — 옥수수 → 메뚜기 → 참새 → 새매"],"title":"초록반 일지 ⑦ 숲의 미로"},"mis":"SC4-2-u2-X39"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u2_review_b#8','sci',4,2,'u2','','g4_2_sci_u2_review_b','unit_review','SC4-2-u2-C30',1,'sa','auto','지구 표면의 온도를 상승시키는 원인이 되는 기체를 무엇이라고 하나요? (온실 ○○)','{}'::text[],false,'{"seq":8,"concept":"SC4-2-u2-C30","difficulty":1,"kind":"sa","stem":"지구 표면의 온도를 상승시키는 원인이 되는 기체를 무엇이라고 하나요? (온실 ○○)","answer":["가스","온실 가스","온실가스"],"explanation":["넷째 줄 낱말이에요.","온실 ○○예요.","온실 가스예요."],"asset":{"type":"passage","lines":["조상들은 메뚜기나 누에 번데기를 즐겨 먹었다.","곤충은 가축과 달리 먹이를 훨씬 적게 먹는다.","곤충은 온실 가스를 거의 배출하지 않는다.","친구 다 — 「곤충이면 아무거나 먹어도 되겠다.」"],"title":"초록반 일지 ⑧ 곤충 요리 탐구"},"mis":"SC4-2-u2-X44"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u2_review_b#9','sci',4,2,'u2','','g4_2_sci_u2_review_b','unit_review','SC4-2-u2-C4',2,'mc','auto','생태계에 대해 바르게 말한 것은 무엇인가요?',ARRAY['SC4-2-u2-X05','SC4-2-u2-X06']::text[],false,'{"seq":9,"concept":"SC4-2-u2-C4","difficulty":2,"kind":"mc","stem":"생태계에 대해 바르게 말한 것은 무엇인가요?","options":[{"t":"숲처럼 큰 곳도, 어항처럼 작은 곳도 생태계가 될 수 있다","correct":true},{"t":"생태계는 아주 넓은 곳에만 있다","mis":"SC4-2-u2-X05"},{"t":"생태계에는 살아 있는 것만 들어간다","mis":"SC4-2-u2-X05"},{"t":"사람이 만든 곳은 생태계가 아니다","mis":"SC4-2-u2-X06"}],"explanation":["크고 작은 생태계를 떠올려요.","어항도 있어요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u2_review_b#10','sci',4,2,'u2','','g4_2_sci_u2_review_b','unit_review','SC4-2-u2-C5',2,'mc','auto','생물요소끼리 바르게 묶은 것은 무엇인가요?',ARRAY['SC4-2-u2-X07']::text[],false,'{"seq":10,"concept":"SC4-2-u2-C5","difficulty":2,"kind":"mc","stem":"생물요소끼리 바르게 묶은 것은 무엇인가요?","options":[{"t":"버섯, 세균, 소나무","correct":true},{"t":"햇빛, 공기, 온도","mis":"SC4-2-u2-X07"},{"t":"물, 흙, 노루","mis":"SC4-2-u2-X07"},{"t":"소나무, 공기, 붕어","mis":"SC4-2-u2-X07"}],"explanation":["살아 있는 것만 찾아요.","작은 생물도 생물이에요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u2_review_b#11','sci',4,2,'u2','','g4_2_sci_u2_review_b','unit_review','SC4-2-u2-C12',2,'mc','auto','분해자가 하는 일로 알맞은 것은 무엇인가요?',ARRAY['SC4-2-u2-X17','SC4-2-u2-X14','SC4-2-u2-X16']::text[],false,'{"seq":11,"concept":"SC4-2-u2-C12","difficulty":2,"kind":"mc","stem":"분해자가 하는 일로 알맞은 것은 무엇인가요?","options":[{"t":"죽은 몸이나 배출물을 분해하여 생산자가 이용할 수 있는 물질을 만든다","correct":true},{"t":"살아 있는 생물을 잡아먹는다","mis":"SC4-2-u2-X17"},{"t":"햇빛으로 스스로 양분을 만든다","mis":"SC4-2-u2-X14"},{"t":"살아 있지 않아 아무 일도 하지 않는다","mis":"SC4-2-u2-X16"}],"explanation":["분해자를 떠올려요.","분해한 물질을 생산자가 써요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u2_review_b#12','sci',4,2,'u2','','g4_2_sci_u2_review_b','unit_review','SC4-2-u2-C16',2,'mc','auto','먹이그물에서 메뚜기가 사라질 때 크게 변하지 않을 생물은 무엇인가요?',ARRAY['SC4-2-u2-X23']::text[],false,'{"seq":12,"concept":"SC4-2-u2-C16","difficulty":2,"kind":"mc","stem":"먹이그물에서 메뚜기가 사라질 때 크게 변하지 않을 생물은 무엇인가요?","options":[{"t":"도토리를 먹는 다람쥐","correct":true},{"t":"메뚜기를 먹던 개구리","mis":"SC4-2-u2-X23"},{"t":"메뚜기에게 먹히던 벼","mis":"SC4-2-u2-X23"},{"t":"모든 생물이 크게 변한다","mis":"SC4-2-u2-X23"}],"explanation":["메뚜기와 직접 관계가 없어요.","도토리를 먹어요.","다람쥐예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u2_review_b#13','sci',4,2,'u2','','g4_2_sci_u2_review_b','unit_review','SC4-2-u2-C18',2,'ox','auto','먹이그물 모형을 만들 때에는 숲 그림판 모서리에 손을 다치지 않게 조심해요.',ARRAY['SC4-2-u2-X26']::text[],false,'{"seq":13,"concept":"SC4-2-u2-C18","difficulty":2,"kind":"ox","stem":"먹이그물 모형을 만들 때에는 숲 그림판 모서리에 손을 다치지 않게 조심해요.","answer":"O","reason_options":[{"t":"그림판 모서리에 손을 다칠 수 있기 때문에","correct":true},{"t":"그림판은 부드러워 아무렇게나 다루어도 되기 때문에","mis":"SC4-2-u2-X26"}],"mis":"SC4-2-u2-X26","explanation":["모형을 만들 때를 떠올려요.","모서리를 조심해요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u2_review_b#14','sci',4,2,'u2','','g4_2_sci_u2_review_b','unit_review','SC4-2-u2-C21',2,'mc','auto','쓰레기로 오염된 물을 마신 생물에게 생길 수 있는 일은 무엇인가요?',ARRAY['SC4-2-u2-X30']::text[],false,'{"seq":14,"concept":"SC4-2-u2-C21","difficulty":2,"kind":"mc","stem":"쓰레기로 오염된 물을 마신 생물에게 생길 수 있는 일은 무엇인가요?","options":[{"t":"여러 가지 병에 걸릴 수 있다","correct":true},{"t":"더 건강해진다","mis":"SC4-2-u2-X30"},{"t":"아무 변화가 없다","mis":"SC4-2-u2-X30"},{"t":"숨을 더 잘 쉬게 된다","mis":"SC4-2-u2-X30"}],"explanation":["오염된 물을 떠올려요.","몸에 해로워요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u2_review_b#15','sci',4,2,'u2','','g4_2_sci_u2_review_b','unit_review','SC4-2-u2-C22',2,'mc','auto','생태계보전을 위한 노력으로 알맞지 않은 것은 무엇인가요?',ARRAY['SC4-2-u2-X31']::text[],false,'{"seq":15,"concept":"SC4-2-u2-C22","difficulty":2,"kind":"mc","stem":"생태계보전을 위한 노력으로 알맞지 않은 것은 무엇인가요?","options":[{"t":"농약을 많이 사용한다","correct":true},{"t":"물티슈 대신 손수건을 쓴다","mis":"SC4-2-u2-X31"},{"t":"일회용품 사용을 줄인다","mis":"SC4-2-u2-X31"},{"t":"꽃을 꺾지 않는다","mis":"SC4-2-u2-X31"}],"explanation":["오염 물질을 늘리는 것을 찾아요.","과다 사용이에요.","첫 번째가 알맞지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u2_review_b#16','sci',4,2,'u2','','g4_2_sci_u2_review_b','unit_review','SC4-2-u2-C28',2,'mc','auto','숲의 미로에서 팻말 ①과 ②를 지키며 지날 수 없는 생물요소는 무엇인가요?',ARRAY['SC4-2-u2-X39']::text[],false,'{"seq":16,"concept":"SC4-2-u2-C28","difficulty":2,"kind":"mc","stem":"숲의 미로에서 팻말 ①과 ②를 지키며 지날 수 없는 생물요소는 무엇인가요?","options":[{"t":"노루","correct":true},{"t":"옥수수","mis":"SC4-2-u2-X39"},{"t":"참새","mis":"SC4-2-u2-X39"},{"t":"새매","mis":"SC4-2-u2-X39"}],"explanation":["남은 길을 떠올려요.","옥수수 → 메뚜기 → 참새 → 새매예요.","노루예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u2_review_b#17','sci',4,2,'u2','','g4_2_sci_u2_review_b','unit_review','SC4-2-u2-C8',3,'error','auto','학교 연못을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC4-2-u2-X06','SC4-2-u2-X11','SC4-2-u2-X09']::text[],false,'{"seq":17,"concept":"SC4-2-u2-C8","difficulty":3,"kind":"error","stem":"학교 연못을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 가 — 「사람이 만든 연못이라서 생태계가 아니야.」","correct":true,"mis_target":"SC4-2-u2-X06"},{"t":"친구 나 — 「햇빛은 검정말이 양분을 만드는 데 이용해.」","mis":"SC4-2-u2-X11"},{"t":"친구 다 — 「목록을 외우지 않고 살아 있는지 보고 나눴어.」","mis":"SC4-2-u2-X09"}],"explanation":["생태계의 뜻을 떠올려요.","사람이 만든 곳도 돼요.","친구 가가 잘못 말했어요."],"asset":{"type":"passage","lines":["학교 연못을 조사했다.","살아 있는 것 — 붕어, 개구리, 부들, 검정말","살아 있지 않은 것 — 햇빛, 물, 공기, 흙, 온도","친구 가 — 「작은 연못도 생태계구나.」"],"title":"초록반 일지 ② 학교 연못 조사"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u2_review_b#18','sci',4,2,'u2','','g4_2_sci_u2_review_b','unit_review','SC4-2-u2-C12',3,'error','auto','분해자를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC4-2-u2-X17','SC4-2-u2-X16','SC4-2-u2-X14']::text[],false,'{"seq":18,"concept":"SC4-2-u2-C12","difficulty":3,"kind":"error","stem":"분해자를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「분해한 물질은 아무 데도 쓰이지 않아.」","correct":true,"mis_target":"SC4-2-u2-X17"},{"t":"친구 가 — 「세균은 죽은 몸을 분해해 양분을 얻어.」","mis":"SC4-2-u2-X16"},{"t":"친구 나 — 「검정말은 햇빛으로 스스로 양분을 만들어.」","mis":"SC4-2-u2-X14"}],"explanation":["분해 결과를 떠올려요.","생산자가 이용해요.","친구 다가 잘못 말했어요."],"asset":{"type":"passage","lines":["부들, 검정말 — 햇빛을 이용하여 스스로 양분을 만든다.","붕어, 개구리 — 다른 생물을 먹어 양분을 얻는다.","곰팡이, 세균 — 죽은 몸이나 배출물을 분해한다.","연못가 나무 밑동에서 버섯을 보았다."],"title":"초록반 일지 ③ 연못 생물 나누기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u2_review_b#19','sci',4,2,'u2','','g4_2_sci_u2_review_b','unit_review','SC4-2-u2-C15',3,'error','auto','먹이 관계 모형을 보며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC4-2-u2-X21','SC4-2-u2-X22','SC4-2-u2-X20']::text[],false,'{"seq":19,"concept":"SC4-2-u2-C15","difficulty":3,"kind":"error","stem":"먹이 관계 모형을 보며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 나 — 「먹이사슬과 먹이그물은 같은 거야.」","correct":true,"mis_target":"SC4-2-u2-X21"},{"t":"친구 가 — 「메뚜기는 여러 생물에게 먹혀.」","mis":"SC4-2-u2-X22"},{"t":"친구 다 — 「화살표는 먹히는 쪽에서 먹는 쪽으로 그려.」","mis":"SC4-2-u2-X20"}],"explanation":["사슬과 그물을 떠올려요.","모양이 달라요.","친구 나가 잘못 말했어요."],"asset":{"type":"passage","lines":["한 줄로 이은 것 — 벼 → 메뚜기 → 개구리 → 뱀","메뚜기는 벼뿐 아니라 질경이도 먹는다.","메뚜기는 개구리뿐 아니라 직박구리의 먹이도 된다.","다람쥐는 도토리를 먹는다."],"title":"초록반 일지 ④ 먹이 관계 모형"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u2_review_b#20','sci',4,2,'u2','','g4_2_sci_u2_review_b','unit_review','SC4-2-u2-C22',3,'error','auto','농약을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC4-2-u2-X31','SC4-2-u2-X32','SC4-2-u2-X28']::text[],false,'{"seq":20,"concept":"SC4-2-u2-C22","difficulty":3,"kind":"error","stem":"농약을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 나 — 「농약은 많이 쓸수록 생태계에 좋아.」","correct":true,"mis_target":"SC4-2-u2-X31"},{"t":"친구 가 — 「지나치게 많이 쓰는 게 문제야.」","mis":"SC4-2-u2-X32"},{"t":"친구 다 — 「농약은 흙과 물을 함께 오염시킬 수 있어.」","mis":"SC4-2-u2-X28"}],"explanation":["셋째 줄을 읽어요.","과다 사용이 문제예요.","친구 나가 잘못 말했어요."],"asset":{"type":"passage","lines":["하천에 버려진 쓰레기 — 수질오염","자동차에서 나오는 배기가스 — 대기오염, 수질오염","논밭에 지나치게 많이 쓴 농약 — 토양오염, 수질오염","조사한 자료마다 출처를 적었다."],"title":"초록반 일지 ⑤ 환경오염 조사"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u2_review_b#21','sci',4,2,'u2','','g4_2_sci_u2_review_b','unit_review','SC4-2-u2-C28',3,'error','auto','초록반 일지 ⑦을 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC4-2-u2-X39','SC4-2-u2-X40']::text[],false,'{"seq":21,"concept":"SC4-2-u2-C28","difficulty":3,"kind":"error","stem":"초록반 일지 ⑦을 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「세균은 생물요소니까 미로를 끝까지 지날 수 있어.」","correct":true,"mis_target":"SC4-2-u2-X39"},{"t":"친구 가 — 「흙은 살아 있지 않아서 팻말 ①에서 빠져.」","mis":"SC4-2-u2-X40"},{"t":"친구 나 — 「참새는 메뚜기를 먹고 새매에게 먹혀.」","mis":"SC4-2-u2-X39"}],"explanation":["팻말 ②를 떠올려요.","먹이사슬을 이뤄야 해요.","친구 다가 잘못 말했어요."],"asset":{"type":"passage","lines":["팻말 없이 — 열한 가지가 모두 지날 수 있었다.","팻말 ① 생물요소만 — 흙, 물, 햇빛이 빠졌다.","팻말 ② 올바른 먹이사슬 — 네 가지만 남았다.","남은 길 — 옥수수 → 메뚜기 → 참새 → 새매"],"title":"초록반 일지 ⑦ 숲의 미로"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u2_review_b#22','sci',4,2,'u2','','g4_2_sci_u2_review_b','unit_review','SC4-2-u2-C30',3,'error','auto','곤충 요리를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC4-2-u2-X44','SC4-2-u2-X43','SC4-2-u2-X45']::text[],false,'{"seq":22,"concept":"SC4-2-u2-C30","difficulty":3,"kind":"error","stem":"곤충 요리를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 가 — 「온실 가스는 지구를 시원하게 해 주는 기체야.」","correct":true,"mis_target":"SC4-2-u2-X44"},{"t":"친구 나 — 「곤충은 가축보다 먹이를 훨씬 적게 먹어.」","mis":"SC4-2-u2-X43"},{"t":"친구 다 — 「곤충 요리는 원래 모습이 잘 드러나지 않게 만들어.」","mis":"SC4-2-u2-X45"}],"explanation":["온실 가스의 뜻을 떠올려요.","온도를 상승시켜요.","친구 가가 잘못 말했어요."],"asset":{"type":"passage","lines":["조상들은 메뚜기나 누에 번데기를 즐겨 먹었다.","곤충은 가축과 달리 먹이를 훨씬 적게 먹는다.","곤충은 온실 가스를 거의 배출하지 않는다.","친구 다 — 「곤충이면 아무거나 먹어도 되겠다.」"],"title":"초록반 일지 ⑧ 곤충 요리 탐구"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u2_review_b#23','sci',4,2,'u2','','g4_2_sci_u2_review_b','unit_review','SC4-2-u2-C10',4,'essay','teacher','초록반 일지 ③을 보고 생산자, 소비자, 분해자를 하나씩 골라 양분을 얻는 방법과 함께 쓰고, 나무 밑동의 버섯이 어느 무리인지 까닭과 함께 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"SC4-2-u2-C10","difficulty":4,"kind":"essay","stem":"초록반 일지 ③을 보고 생산자, 소비자, 분해자를 하나씩 골라 양분을 얻는 방법과 함께 쓰고, 나무 밑동의 버섯이 어느 무리인지 까닭과 함께 쓰세요.","answer_guide":{"answer":"예: 검정말은 생산자로 햇빛을 이용하여 스스로 양분을 만든다. 붕어는 소비자로 다른 생물을 먹어 양분을 얻는다. 세균은 분해자로 죽은 몸이나 배출물을 분해한다. 버섯은 스스로 양분을 만들지 못하고 죽은 몸이나 배출물을 분해하여 양분을 얻으므로 분해자이다.","scoring_points":["세 무리를 하나씩 바르게 골랐는가","양분을 얻는 방법을 썼는가","버섯이 분해자인 까닭을 썼는가"]},"explanation":["일지를 읽어요.","세 무리를 써요.","버섯을 써요."],"asset":{"type":"passage","lines":["부들, 검정말 — 햇빛을 이용하여 스스로 양분을 만든다.","붕어, 개구리 — 다른 생물을 먹어 양분을 얻는다.","곰팡이, 세균 — 죽은 몸이나 배출물을 분해한다.","연못가 나무 밑동에서 버섯을 보았다."],"title":"초록반 일지 ③ 연못 생물 나누기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u2_review_b#24','sci',4,2,'u2','','g4_2_sci_u2_review_b','unit_review','SC4-2-u2-C16',4,'mc','auto','친구가 「크게 자라는 생물이 늘 작은 생물을 먹으니, 큰 생물만 사라지지 않으면 생태계는 괜찮아.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?',ARRAY['SC4-2-u2-X25','SC4-2-u2-X24','SC4-2-u2-X23']::text[],false,'{"seq":24,"concept":"SC4-2-u2-C16","difficulty":4,"kind":"mc","stem":"친구가 「크게 자라는 생물이 늘 작은 생물을 먹으니, 큰 생물만 사라지지 않으면 생태계는 괜찮아.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?","options":[{"t":"「먹이 관계는 크기로 정해지지 않고, 생물들은 서로 얽혀 있어서 어느 생물이 줄어도 다른 생물에게 영향을 줘.」","correct":true},{"t":"「맞아, 작은 생물은 없어도 돼.」","mis":"SC4-2-u2-X25"},{"t":"「먹이 관계는 한 줄뿐이라 영향이 없어.」","mis":"SC4-2-u2-X24"},{"t":"「한 생물이 사라지면 모두 한꺼번에 사라져.」","mis":"SC4-2-u2-X23"}],"explanation":["골리앗타이거피시와 먹이그물을 떠올려요.","크기가 아니에요.","첫 번째가 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u2_review_b#25','sci',4,2,'u2','','g4_2_sci_u2_review_b','unit_review','SC4-2-u2-C28',4,'essay','teacher','초록반 일지 ⑦을 보고 팻말 ①과 ②가 각각 무엇을 빼는지 쓰고, 상어처럼 생물요소인데도 지날 수 없는 까닭을 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"SC4-2-u2-C28","difficulty":4,"kind":"essay","stem":"초록반 일지 ⑦을 보고 팻말 ①과 ②가 각각 무엇을 빼는지 쓰고, 상어처럼 생물요소인데도 지날 수 없는 까닭을 쓰세요.","answer_guide":{"answer":"예: 팻말 ①은 흙, 물, 햇빛처럼 살아 있지 않은 비생물요소를 뺀다. 팻말 ②는 올바른 먹이사슬을 이루지 못하는 것을 뺀다. 상어는 생물요소이지만 옥수수 → 메뚜기 → 참새 → 새매의 먹이사슬을 이루지 못하므로 지날 수 없다.","scoring_points":["팻말 ①이 빼는 것을 썼는가","팻말 ②가 빼는 것을 썼는가","상어가 지날 수 없는 까닭을 썼는가"]},"explanation":["일지를 읽어요.","팻말을 차례로 따져요.","까닭을 써요."],"asset":{"type":"passage","lines":["팻말 없이 — 열한 가지가 모두 지날 수 있었다.","팻말 ① 생물요소만 — 흙, 물, 햇빛이 빠졌다.","팻말 ② 올바른 먹이사슬 — 네 가지만 남았다.","남은 길 — 옥수수 → 메뚜기 → 참새 → 새매"],"title":"초록반 일지 ⑦ 숲의 미로"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u2_review_c#1','sci',4,2,'u2','','g4_2_sci_u2_review_c','unit_review','SC4-2-u2-C3',1,'ox','auto','초록반 일지 ①처럼 자연물은 땅에 떨어진 것을 주워 모아요.',ARRAY['SC4-2-u2-X03']::text[],false,'{"seq":1,"concept":"SC4-2-u2-C3","difficulty":1,"kind":"ox","stem":"초록반 일지 ①처럼 자연물은 땅에 떨어진 것을 주워 모아요.","answer":"O","reason_options":[{"t":"식물에 붙어 있는 부분을 무리하게 떼지 않기 위해서","correct":true},{"t":"떨어진 것만 작품에 붙일 수 있기 때문에","mis":"SC4-2-u2-X03"}],"mis":"SC4-2-u2-X03","explanation":["첫 줄을 읽어요.","떨어진 것을 주웠어요.","그래서 O예요."],"asset":{"type":"passage","lines":["모둠마다 땅에 떨어진 나뭇잎, 나뭇가지, 열매를 주워 모았다.","한 모둠은 숲을, 다른 모둠은 물속을 흰 종이에 꾸몄다.","숲 — 토끼, 다람쥐, 노루 / 물속 — 붕어, 송사리, 물방개","다짐 — 잘 만드는 것보다 함께 참여하기"],"title":"초록반 일지 ① 나뭇잎 작품"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u2_review_c#2','sci',4,2,'u2','','g4_2_sci_u2_review_c','unit_review','SC4-2-u2-C8',1,'ox','auto','초록반 일지 ②의 친구 가처럼 작은 연못도 생태계라고 할 수 있어요.',ARRAY['SC4-2-u2-X06']::text[],false,'{"seq":2,"concept":"SC4-2-u2-C8","difficulty":1,"kind":"ox","stem":"초록반 일지 ②의 친구 가처럼 작은 연못도 생태계라고 할 수 있어요.","answer":"O","reason_options":[{"t":"생물요소와 비생물요소를 모두 포함하고 있기 때문에","correct":true},{"t":"연못은 물이 고여 있기만 하면 되기 때문에","mis":"SC4-2-u2-X06"}],"mis":"SC4-2-u2-X06","explanation":["넷째 줄을 읽어요.","두 요소가 다 있어요.","그래서 O예요."],"asset":{"type":"passage","lines":["학교 연못을 조사했다.","살아 있는 것 — 붕어, 개구리, 부들, 검정말","살아 있지 않은 것 — 햇빛, 물, 공기, 흙, 온도","친구 가 — 「작은 연못도 생태계구나.」"],"title":"초록반 일지 ② 학교 연못 조사"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u2_review_c#3','sci',4,2,'u2','','g4_2_sci_u2_review_c','unit_review','SC4-2-u2-C13',1,'ox','auto','초록반 일지 ③에서 본 버섯은 스스로 양분을 만들어요.',ARRAY['SC4-2-u2-X18']::text[],false,'{"seq":3,"concept":"SC4-2-u2-C13","difficulty":1,"kind":"ox","stem":"초록반 일지 ③에서 본 버섯은 스스로 양분을 만들어요.","answer":"X","reason_options":[{"t":"버섯은 스스로 양분을 만들지 못하고 분해하여 양분을 얻기 때문에","correct":true},{"t":"버섯은 식물처럼 생겼기 때문에","mis":"SC4-2-u2-X18"}],"mis":"SC4-2-u2-X18","explanation":["넷째 줄을 읽어요.","나무 밑동은 햇빛이 잘 들지 않아요.","그래서 X예요."],"asset":{"type":"passage","lines":["부들, 검정말 — 햇빛을 이용하여 스스로 양분을 만든다.","붕어, 개구리 — 다른 생물을 먹어 양분을 얻는다.","곰팡이, 세균 — 죽은 몸이나 배출물을 분해한다.","연못가 나무 밑동에서 버섯을 보았다."],"title":"초록반 일지 ③ 연못 생물 나누기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u2_review_c#4','sci',4,2,'u2','','g4_2_sci_u2_review_c','unit_review','SC4-2-u2-C14',1,'ox','auto','초록반 일지 ④의 「벼 → 메뚜기」에서 화살표는 잡아먹히는 생물에서 잡아먹는 생물 쪽으로 그렸어요.',ARRAY['SC4-2-u2-X20']::text[],false,'{"seq":4,"concept":"SC4-2-u2-C14","difficulty":1,"kind":"ox","stem":"초록반 일지 ④의 「벼 → 메뚜기」에서 화살표는 잡아먹히는 생물에서 잡아먹는 생물 쪽으로 그렸어요.","answer":"O","reason_options":[{"t":"메뚜기가 벼를 먹으므로 벼에서 메뚜기 쪽으로 그리기 때문에","correct":true},{"t":"화살표는 언제나 왼쪽에서 오른쪽으로만 그리기 때문에","mis":"SC4-2-u2-X20"}],"mis":"SC4-2-u2-X20","explanation":["첫 줄을 읽어요.","먹히는 벼에서 시작해요.","그래서 O예요."],"asset":{"type":"passage","lines":["한 줄로 이은 것 — 벼 → 메뚜기 → 개구리 → 뱀","메뚜기는 벼뿐 아니라 질경이도 먹는다.","메뚜기는 개구리뿐 아니라 직박구리의 먹이도 된다.","다람쥐는 도토리를 먹는다."],"title":"초록반 일지 ④ 먹이 관계 모형"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u2_review_c#5','sci',4,2,'u2','','g4_2_sci_u2_review_c','unit_review','SC4-2-u2-C23',1,'ox','auto','초록반 일지 ⑤처럼 조사한 자료의 출처를 적어요.',ARRAY['SC4-2-u2-X33']::text[],false,'{"seq":5,"concept":"SC4-2-u2-C23","difficulty":1,"kind":"ox","stem":"초록반 일지 ⑤처럼 조사한 자료의 출처를 적어요.","answer":"O","reason_options":[{"t":"옳은 정보인지 확인할 수 있기 때문에","correct":true},{"t":"출처를 적으면 자료가 길어져 좋기 때문에","mis":"SC4-2-u2-X33"}],"mis":"SC4-2-u2-X33","explanation":["넷째 줄을 읽어요.","출처를 적었어요.","그래서 O예요."],"asset":{"type":"passage","lines":["하천에 버려진 쓰레기 — 수질오염","자동차에서 나오는 배기가스 — 대기오염, 수질오염","논밭에 지나치게 많이 쓴 농약 — 토양오염, 수질오염","조사한 자료마다 출처를 적었다."],"title":"초록반 일지 ⑤ 환경오염 조사"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u2_review_c#6','sci',4,2,'u2','','g4_2_sci_u2_review_c','unit_review','SC4-2-u2-C26',1,'ox','auto','초록반 일지 ⑥처럼 사진을 찍으러 갈 때에는 다치지 않게 조심해요.',ARRAY['SC4-2-u2-X37']::text[],false,'{"seq":6,"concept":"SC4-2-u2-C26","difficulty":1,"kind":"ox","stem":"초록반 일지 ⑥처럼 사진을 찍으러 갈 때에는 다치지 않게 조심해요.","answer":"O","reason_options":[{"t":"장소를 찾아갈 때 위험한 곳이 있을 수 있기 때문에","correct":true},{"t":"사진만 잘 나오면 되기 때문에","mis":"SC4-2-u2-X37"}],"mis":"SC4-2-u2-X37","explanation":["셋째 줄을 읽어요.","안전이에요.","그래서 O예요."],"asset":{"type":"passage","lines":["장소 — 풀이 없어지고 길이 넓어진 학교 뒷산 등산로","실천 방법 — 안내 팻말 세우기, 정해진 길로만 다니기","사진을 찍으러 갈 때 다치지 않게 조심했다.","친구 나 — 「반짝이를 더 붙여야 최고의 자료가 돼.」"],"title":"초록반 일지 ⑥ 생태계 지킴이"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u2_review_c#7','sci',4,2,'u2','','g4_2_sci_u2_review_c','unit_review','SC4-2-u2-C28',1,'ox','auto','초록반 일지 ⑦에서 팻말 ②까지 붙이니 네 가지만 남았어요.',ARRAY['SC4-2-u2-X40']::text[],false,'{"seq":7,"concept":"SC4-2-u2-C28","difficulty":1,"kind":"ox","stem":"초록반 일지 ⑦에서 팻말 ②까지 붙이니 네 가지만 남았어요.","answer":"O","reason_options":[{"t":"올바른 먹이사슬을 이루는 것만 지날 수 있기 때문에","correct":true},{"t":"팻말 ②는 비생물요소만 남기기 때문에","mis":"SC4-2-u2-X40"}],"mis":"SC4-2-u2-X40","explanation":["셋째 줄을 읽어요.","먹이사슬을 이뤄요.","그래서 O예요."],"asset":{"type":"passage","lines":["팻말 없이 — 열한 가지가 모두 지날 수 있었다.","팻말 ① 생물요소만 — 흙, 물, 햇빛이 빠졌다.","팻말 ② 올바른 먹이사슬 — 네 가지만 남았다.","남은 길 — 옥수수 → 메뚜기 → 참새 → 새매"],"title":"초록반 일지 ⑦ 숲의 미로"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u2_review_c#8','sci',4,2,'u2','','g4_2_sci_u2_review_c','unit_review','SC4-2-u2-C30',1,'ox','auto','초록반 일지 ⑧처럼 곤충은 가축과 달리 먹이를 훨씬 적게 먹어요.',ARRAY['SC4-2-u2-X43']::text[],false,'{"seq":8,"concept":"SC4-2-u2-C30","difficulty":1,"kind":"ox","stem":"초록반 일지 ⑧처럼 곤충은 가축과 달리 먹이를 훨씬 적게 먹어요.","answer":"O","reason_options":[{"t":"곤충을 기를 때 가축보다 먹이가 훨씬 적게 들기 때문에","correct":true},{"t":"곤충은 먹이를 전혀 먹지 않기 때문에","mis":"SC4-2-u2-X43"}],"mis":"SC4-2-u2-X43","explanation":["둘째 줄을 읽어요.","가축과 견줘요.","그래서 O예요."],"asset":{"type":"passage","lines":["조상들은 메뚜기나 누에 번데기를 즐겨 먹었다.","곤충은 가축과 달리 먹이를 훨씬 적게 먹는다.","곤충은 온실 가스를 거의 배출하지 않는다.","친구 다 — 「곤충이면 아무거나 먹어도 되겠다.」"],"title":"초록반 일지 ⑧ 곤충 요리 탐구"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u2_review_c#9','sci',4,2,'u2','','g4_2_sci_u2_review_c','unit_review','SC4-2-u2-C3',2,'ox','auto','나뭇잎 작품은 완성도가 높아야 좋은 작품이에요.',ARRAY['SC4-2-u2-X04']::text[],false,'{"seq":9,"concept":"SC4-2-u2-C3","difficulty":2,"kind":"ox","stem":"나뭇잎 작품은 완성도가 높아야 좋은 작품이에요.","answer":"X","reason_options":[{"t":"주변을 살펴보고 그곳에 사는 생물을 알아보는 것이 목표이기 때문에","correct":true},{"t":"잘 만든 작품만 발표할 수 있기 때문에","mis":"SC4-2-u2-X04"}],"mis":"SC4-2-u2-X04","explanation":["활동의 목표를 떠올려요.","완성도를 따지지 않아요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u2_review_c#10','sci',4,2,'u2','','g4_2_sci_u2_review_c','unit_review','SC4-2-u2-C6',2,'ox','auto','숲, 강, 바다 세 곳에는 햇빛, 공기, 온도가 모두 있어요.',ARRAY['SC4-2-u2-X12']::text[],false,'{"seq":10,"concept":"SC4-2-u2-C6","difficulty":2,"kind":"ox","stem":"숲, 강, 바다 세 곳에는 햇빛, 공기, 온도가 모두 있어요.","answer":"O","reason_options":[{"t":"사는 생물은 곳마다 달라도 햇빛, 공기, 온도는 세 곳 모두에 있기 때문에","correct":true},{"t":"세 곳에 사는 생물이 모두 같기 때문에","mis":"SC4-2-u2-X12"}],"mis":"SC4-2-u2-X12","explanation":["세 곳을 견준 것을 떠올려요.","생물이 아닌 것은 거의 같아요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u2_review_c#11','sci',4,2,'u2','','g4_2_sci_u2_review_c','unit_review','SC4-2-u2-C10',2,'ox','auto','메뚜기는 생산자예요.',ARRAY['SC4-2-u2-X14']::text[],false,'{"seq":11,"concept":"SC4-2-u2-C10","difficulty":2,"kind":"ox","stem":"메뚜기는 생산자예요.","answer":"X","reason_options":[{"t":"메뚜기는 다른 생물을 먹어 양분을 얻는 소비자이기 때문에","correct":true},{"t":"메뚜기는 풀숲에 살기 때문에","mis":"SC4-2-u2-X14"}],"mis":"SC4-2-u2-X14","explanation":["메뚜기가 양분을 얻는 방법을 떠올려요.","풀을 먹어요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u2_review_c#12','sci',4,2,'u2','','g4_2_sci_u2_review_c','unit_review','SC4-2-u2-C16',2,'ox','auto','먹이 관계가 단순할수록 생태계가 큰 변화 없이 유지돼요.',ARRAY['SC4-2-u2-X24']::text[],false,'{"seq":12,"concept":"SC4-2-u2-C16","difficulty":2,"kind":"ox","stem":"먹이 관계가 단순할수록 생태계가 큰 변화 없이 유지돼요.","answer":"X","reason_options":[{"t":"먹이 관계가 복잡할수록 다른 생물을 먹이로 먹을 수 있어 생태계가 유지되기 때문에","correct":true},{"t":"먹이가 하나뿐이어야 찾기 쉽기 때문에","mis":"SC4-2-u2-X24"}],"mis":"SC4-2-u2-X24","explanation":["먹이그물을 떠올려요.","복잡할수록 좋아요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u2_review_c#13','sci',4,2,'u2','','g4_2_sci_u2_review_c','unit_review','SC4-2-u2-C14',2,'mc','auto','「토끼풀 → 토끼 → 여우 → 호랑이」에서 토끼를 먹는 생물은 무엇인가요?',ARRAY['SC4-2-u2-X20','SC4-2-u2-X22']::text[],false,'{"seq":13,"concept":"SC4-2-u2-C14","difficulty":2,"kind":"mc","stem":"「토끼풀 → 토끼 → 여우 → 호랑이」에서 토끼를 먹는 생물은 무엇인가요?","options":[{"t":"여우","correct":true},{"t":"토끼풀","mis":"SC4-2-u2-X20"},{"t":"호랑이만","mis":"SC4-2-u2-X22"},{"t":"아무도 먹지 않는다","mis":"SC4-2-u2-X20"}],"explanation":["토끼 다음을 봐요.","화살표가 가리켜요.","여우예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u2_review_c#14','sci',4,2,'u2','','g4_2_sci_u2_review_c','unit_review','SC4-2-u2-C19',2,'ox','auto','환경오염은 사람과 관계없이 저절로 생기는 현상이에요.',ARRAY['SC4-2-u2-X27']::text[],false,'{"seq":14,"concept":"SC4-2-u2-C19","difficulty":2,"kind":"ox","stem":"환경오염은 사람과 관계없이 저절로 생기는 현상이에요.","answer":"X","reason_options":[{"t":"환경오염은 인간 활동으로 생태계가 훼손되고 더럽혀지는 현상이기 때문에","correct":true},{"t":"자연은 스스로 더러워지기 때문에","mis":"SC4-2-u2-X27"}],"mis":"SC4-2-u2-X27","explanation":["환경오염의 뜻을 떠올려요.","인간 활동 때문이에요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u2_review_c#15','sci',4,2,'u2','','g4_2_sci_u2_review_c','unit_review','SC4-2-u2-C25',2,'ox','auto','생태계 지킴이는 계획하고 발표한 방법을 생활 속에서 실천해요.',ARRAY['SC4-2-u2-X35']::text[],false,'{"seq":15,"concept":"SC4-2-u2-C25","difficulty":2,"kind":"ox","stem":"생태계 지킴이는 계획하고 발표한 방법을 생활 속에서 실천해요.","answer":"O","reason_options":[{"t":"실천해야 생태계복원과 보전에 도움이 되기 때문에","correct":true},{"t":"계획만 세우면 저절로 보전되기 때문에","mis":"SC4-2-u2-X35"}],"mis":"SC4-2-u2-X35","explanation":["실천해요를 떠올려요.","생활 속에서 해요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u2_review_c#16','sci',4,2,'u2','','g4_2_sci_u2_review_c','unit_review','SC4-2-u2-C29',2,'ox','auto','곤충 요리는 주로 곤충의 원래 모습이 잘 드러나지 않는 형태로 만들어요.',ARRAY['SC4-2-u2-X41']::text[],false,'{"seq":16,"concept":"SC4-2-u2-C29","difficulty":2,"kind":"ox","stem":"곤충 요리는 주로 곤충의 원래 모습이 잘 드러나지 않는 형태로 만들어요.","answer":"O","reason_options":[{"t":"먹는 사람이 거부감 없이 먹을 수 있게 하기 위해서","correct":true},{"t":"곤충의 원래 모습은 맛이 없기 때문에","mis":"SC4-2-u2-X41"}],"mis":"SC4-2-u2-X41","explanation":["곤충 요리를 떠올려요.","모습이 잘 안 보여요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u2_review_c#17','sci',4,2,'u2','','g4_2_sci_u2_review_c','unit_review','SC4-2-u2-C7',3,'mc','auto','초록반 일지 ②의 연못에서 물이 사라진다면 어떤 일이 생길까요?',ARRAY['SC4-2-u2-X12','SC4-2-u2-X07']::text[],false,'{"seq":17,"concept":"SC4-2-u2-C7","difficulty":3,"kind":"mc","stem":"초록반 일지 ②의 연못에서 물이 사라진다면 어떤 일이 생길까요?","options":[{"t":"붕어, 검정말처럼 물속에 사는 생물이 살아갈 공간과 생명 유지에 필요한 것을 잃는다","correct":true},{"t":"흙만 있으면 붕어는 그대로 살 수 있다","mis":"SC4-2-u2-X12"},{"t":"물은 생물요소라서 다시 자란다","mis":"SC4-2-u2-X07"},{"t":"아무 일도 생기지 않는다","mis":"SC4-2-u2-X12"}],"explanation":["물이 하는 일을 떠올려요.","생명과 공간이에요.","첫 번째예요."],"asset":{"type":"passage","lines":["학교 연못을 조사했다.","살아 있는 것 — 붕어, 개구리, 부들, 검정말","살아 있지 않은 것 — 햇빛, 물, 공기, 흙, 온도","친구 가 — 「작은 연못도 생태계구나.」"],"title":"초록반 일지 ② 학교 연못 조사"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u2_review_c#18','sci',4,2,'u2','','g4_2_sci_u2_review_c','unit_review','SC4-2-u2-C12',3,'mc','auto','초록반 일지 ③의 연못에서 곰팡이와 세균이 사라진다면 어떤 일이 생길까요?',ARRAY['SC4-2-u2-X17','SC4-2-u2-X16']::text[],false,'{"seq":18,"concept":"SC4-2-u2-C12","difficulty":3,"kind":"mc","stem":"초록반 일지 ③의 연못에서 곰팡이와 세균이 사라진다면 어떤 일이 생길까요?","options":[{"t":"죽은 몸이나 배출물이 분해되지 않고 쌓이며, 생산자가 이용할 물질이 생기지 않는다","correct":true},{"t":"연못이 더 깨끗해진다","mis":"SC4-2-u2-X17"},{"t":"부들이 더 잘 자란다","mis":"SC4-2-u2-X17"},{"t":"곰팡이와 세균은 생물이 아니라 아무 변화가 없다","mis":"SC4-2-u2-X16"}],"explanation":["분해자가 하는 일을 떠올려요.","분해한 물질을 생산자가 써요.","첫 번째예요."],"asset":{"type":"passage","lines":["부들, 검정말 — 햇빛을 이용하여 스스로 양분을 만든다.","붕어, 개구리 — 다른 생물을 먹어 양분을 얻는다.","곰팡이, 세균 — 죽은 몸이나 배출물을 분해한다.","연못가 나무 밑동에서 버섯을 보았다."],"title":"초록반 일지 ③ 연못 생물 나누기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u2_review_c#19','sci',4,2,'u2','','g4_2_sci_u2_review_c','unit_review','SC4-2-u2-C16',3,'mc','auto','초록반 일지 ④에서 벼가 모두 사라져도 메뚜기가 살아갈 수 있는 까닭은 무엇인가요?',ARRAY['SC4-2-u2-X22','SC4-2-u2-X20','SC4-2-u2-X24']::text[],false,'{"seq":19,"concept":"SC4-2-u2-C16","difficulty":3,"kind":"mc","stem":"초록반 일지 ④에서 벼가 모두 사라져도 메뚜기가 살아갈 수 있는 까닭은 무엇인가요?","options":[{"t":"메뚜기는 벼뿐 아니라 질경이도 먹기 때문에","correct":true},{"t":"메뚜기는 아무것도 먹지 않기 때문에","mis":"SC4-2-u2-X22"},{"t":"메뚜기가 개구리를 먹기 때문에","mis":"SC4-2-u2-X20"},{"t":"먹이 관계가 한 줄뿐이기 때문에","mis":"SC4-2-u2-X24"}],"explanation":["둘째 줄을 읽어요.","다른 풀도 먹어요.","첫 번째예요."],"asset":{"type":"passage","lines":["한 줄로 이은 것 — 벼 → 메뚜기 → 개구리 → 뱀","메뚜기는 벼뿐 아니라 질경이도 먹는다.","메뚜기는 개구리뿐 아니라 직박구리의 먹이도 된다.","다람쥐는 도토리를 먹는다."],"title":"초록반 일지 ④ 먹이 관계 모형"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u2_review_c#20','sci',4,2,'u2','','g4_2_sci_u2_review_c','unit_review','SC4-2-u2-C21',3,'mc','auto','초록반 일지 ⑤의 오염이 계속되면 생태계에 어떤 일이 생길까요?',ARRAY['SC4-2-u2-X30']::text[],false,'{"seq":20,"concept":"SC4-2-u2-C21","difficulty":3,"kind":"mc","stem":"초록반 일지 ⑤의 오염이 계속되면 생태계에 어떤 일이 생길까요?","options":[{"t":"생물이 숨 쉬기 어려워지고 생태계의 안정이 깨져 여러 생물이 살기 어려워진다","correct":true},{"t":"오염 물질이 저절로 사라진다","mis":"SC4-2-u2-X30"},{"t":"생물의 수가 늘어난다","mis":"SC4-2-u2-X30"},{"t":"사람에게만 영향이 있다","mis":"SC4-2-u2-X30"}],"explanation":["오염의 영향을 떠올려요.","생존을 위협해요.","첫 번째예요."],"asset":{"type":"passage","lines":["하천에 버려진 쓰레기 — 수질오염","자동차에서 나오는 배기가스 — 대기오염, 수질오염","논밭에 지나치게 많이 쓴 농약 — 토양오염, 수질오염","조사한 자료마다 출처를 적었다."],"title":"초록반 일지 ⑤ 환경오염 조사"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u2_review_c#21','sci',4,2,'u2','','g4_2_sci_u2_review_c','unit_review','SC4-2-u2-C25',3,'mc','auto','초록반 일지 ⑥의 활동을 마친 뒤 학급 게시판에 할 일로 알맞은 것은 무엇인가요?',ARRAY['SC4-2-u2-X36','SC4-2-u2-X35']::text[],false,'{"seq":21,"concept":"SC4-2-u2-C25","difficulty":3,"kind":"mc","stem":"초록반 일지 ⑥의 활동을 마친 뒤 학급 게시판에 할 일로 알맞은 것은 무엇인가요?","options":[{"t":"실천 방법을 올리고 친구들의 실천 방법에 칭찬하는 댓글을 쓴다","correct":true},{"t":"친구의 사진과 집 주소를 함께 올린다","mis":"SC4-2-u2-X36"},{"t":"다른 모둠 방법을 비난한다","mis":"SC4-2-u2-X36"},{"t":"발표했으니 실천은 하지 않는다","mis":"SC4-2-u2-X35"}],"explanation":["실천해요를 떠올려요.","칭찬과 개인 정보예요.","첫 번째예요."],"asset":{"type":"passage","lines":["장소 — 풀이 없어지고 길이 넓어진 학교 뒷산 등산로","실천 방법 — 안내 팻말 세우기, 정해진 길로만 다니기","사진을 찍으러 갈 때 다치지 않게 조심했다.","친구 나 — 「반짝이를 더 붙여야 최고의 자료가 돼.」"],"title":"초록반 일지 ⑥ 생태계 지킴이"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u2_review_c#22','sci',4,2,'u2','','g4_2_sci_u2_review_c','unit_review','SC4-2-u2-C30',3,'mc','auto','초록반 일지 ⑧에서 곤충이 친환경 먹을거리인 까닭을 바르게 고른 것은 무엇인가요?',ARRAY['SC4-2-u2-X43']::text[],false,'{"seq":22,"concept":"SC4-2-u2-C30","difficulty":3,"kind":"mc","stem":"초록반 일지 ⑧에서 곤충이 친환경 먹을거리인 까닭을 바르게 고른 것은 무엇인가요?","options":[{"t":"가축과 달리 먹이를 훨씬 적게 먹고 온실 가스를 거의 배출하지 않는다","correct":true},{"t":"가축보다 먹이를 훨씬 많이 먹는다","mis":"SC4-2-u2-X43"},{"t":"온실 가스를 아주 많이 배출한다","mis":"SC4-2-u2-X43"},{"t":"곤충은 아무것도 먹지 않는다","mis":"SC4-2-u2-X43"}],"explanation":["둘째와 셋째 줄을 읽어요.","먹이와 온실 가스예요.","첫 번째예요."],"asset":{"type":"passage","lines":["조상들은 메뚜기나 누에 번데기를 즐겨 먹었다.","곤충은 가축과 달리 먹이를 훨씬 적게 먹는다.","곤충은 온실 가스를 거의 배출하지 않는다.","친구 다 — 「곤충이면 아무거나 먹어도 되겠다.」"],"title":"초록반 일지 ⑧ 곤충 요리 탐구"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u2_review_c#23','sci',4,2,'u2','','g4_2_sci_u2_review_c','unit_review','SC4-2-u2-C16',4,'essay','teacher','초록반 일지 ④를 보고 먹이사슬 하나를 화살표로 쓰고, 메뚜기가 사라졌을 때 개구리와 벼에게 일어날 변화를 쓰세요. 그리고 먹이 관계가 복잡하면 좋은 까닭을 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"SC4-2-u2-C16","difficulty":4,"kind":"essay","stem":"초록반 일지 ④를 보고 먹이사슬 하나를 화살표로 쓰고, 메뚜기가 사라졌을 때 개구리와 벼에게 일어날 변화를 쓰세요. 그리고 먹이 관계가 복잡하면 좋은 까닭을 쓰세요.","answer_guide":{"answer":"예: 벼 → 메뚜기 → 개구리 → 뱀. 메뚜기가 사라지면 개구리는 일시적으로 줄어들고 벼는 일시적으로 늘어난다. 먹이 관계가 복잡하면 한 생물의 수가 변해도 다른 생물을 먹이로 먹을 수 있어 생태계가 큰 변화 없이 유지된다.","scoring_points":["먹이사슬을 화살표 방향에 맞게 썼는가","개구리와 벼의 변화를 바르게 썼는가","복잡하면 좋은 까닭을 썼는가"]},"explanation":["일지를 읽어요.","화살표 방향을 봐요.","변화와 까닭을 써요."],"asset":{"type":"passage","lines":["한 줄로 이은 것 — 벼 → 메뚜기 → 개구리 → 뱀","메뚜기는 벼뿐 아니라 질경이도 먹는다.","메뚜기는 개구리뿐 아니라 직박구리의 먹이도 된다.","다람쥐는 도토리를 먹는다."],"title":"초록반 일지 ④ 먹이 관계 모형"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u2_review_c#24','sci',4,2,'u2','','g4_2_sci_u2_review_c','unit_review','SC4-2-u2-C22',4,'mc','auto','「농약과 플라스틱은 한 방울, 한 조각도 쓰면 안 되니 마을의 모든 개발을 멈춰야 해.」라는 말을 가장 알맞게 고친 것은 무엇인가요?',ARRAY['SC4-2-u2-X31','SC4-2-u2-X27']::text[],false,'{"seq":24,"concept":"SC4-2-u2-C22","difficulty":4,"kind":"mc","stem":"「농약과 플라스틱은 한 방울, 한 조각도 쓰면 안 되니 마을의 모든 개발을 멈춰야 해.」라는 말을 가장 알맞게 고친 것은 무엇인가요?","options":[{"t":"「지나치게 많이 쓰는 것이 문제야. 오염 물질의 양을 줄이고 개발과 생태계보전 사이에 균형을 이루어야 해.」","correct":true},{"t":"「농약을 많이 쓸수록 좋아.」","mis":"SC4-2-u2-X31"},{"t":"「개발만 하면 생태계는 저절로 지켜져.」","mis":"SC4-2-u2-X31"},{"t":"「환경오염은 사람과 관계없어.」","mis":"SC4-2-u2-X27"}],"explanation":["균형을 떠올려요.","과다 사용이 문제예요.","첫 번째가 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u2_review_c#25','sci',4,2,'u2','','g4_2_sci_u2_review_c','unit_review','SC4-2-u2-C29',4,'essay','teacher','초록반 일지 ⑧을 보고 곤충이 친환경 미래 식량인 까닭을 두 가지 쓰고, 친구 다의 말을 바르게 고쳐 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"SC4-2-u2-C29","difficulty":4,"kind":"essay","stem":"초록반 일지 ⑧을 보고 곤충이 친환경 미래 식량인 까닭을 두 가지 쓰고, 친구 다의 말을 바르게 고쳐 쓰세요.","answer_guide":{"answer":"예: 곤충은 가축과 달리 먹이를 훨씬 적게 먹고, 온실 가스를 거의 배출하지 않는다. 곤충이면 아무거나 먹을 수 있는 것이 아니라 먹을 수 있는 종류로 인정한 곤충만 먹어야 한다.","scoring_points":["까닭 하나를 썼는가","까닭 또 하나를 썼는가","친구 다의 말을 바르게 고쳤는가"]},"explanation":["일지를 읽어요.","까닭을 써요.","고쳐 써요."],"asset":{"type":"passage","lines":["조상들은 메뚜기나 누에 번데기를 즐겨 먹었다.","곤충은 가축과 달리 먹이를 훨씬 적게 먹는다.","곤충은 온실 가스를 거의 배출하지 않는다.","친구 다 — 「곤충이면 아무거나 먹어도 되겠다.」"],"title":"초록반 일지 ⑧ 곤충 요리 탐구"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u2_review_d#1','sci',4,2,'u2','','g4_2_sci_u2_review_d','unit_review','SC4-2-u2-C3',1,'mc','auto','초록반 일지 ①의 다짐으로 알맞은 것은 무엇인가요?',ARRAY['SC4-2-u2-X04','SC4-2-u2-X03']::text[],false,'{"seq":1,"concept":"SC4-2-u2-C3","difficulty":1,"kind":"mc","stem":"초록반 일지 ①의 다짐으로 알맞은 것은 무엇인가요?","options":[{"t":"잘 만드는 것보다 함께 참여하기","correct":true},{"t":"가장 화려한 작품 뽑기","mis":"SC4-2-u2-X04"},{"t":"사진처럼 똑같이 그리기","mis":"SC4-2-u2-X04"},{"t":"나무에 붙은 잎 많이 따기","mis":"SC4-2-u2-X03"}],"explanation":["넷째 줄을 읽어요.","참여가 중요해요.","첫 번째예요."],"asset":{"type":"passage","lines":["모둠마다 땅에 떨어진 나뭇잎, 나뭇가지, 열매를 주워 모았다.","한 모둠은 숲을, 다른 모둠은 물속을 흰 종이에 꾸몄다.","숲 — 토끼, 다람쥐, 노루 / 물속 — 붕어, 송사리, 물방개","다짐 — 잘 만드는 것보다 함께 참여하기"],"title":"초록반 일지 ① 나뭇잎 작품"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u2_review_d#2','sci',4,2,'u2','','g4_2_sci_u2_review_d','unit_review','SC4-2-u2-C4',1,'mc','auto','연못, 어항, 화단처럼 작은 곳에 있는 생물과 영향을 주는 요소를 통틀어 무엇이라고 하나요?',ARRAY['SC4-2-u2-X05']::text[],false,'{"seq":2,"concept":"SC4-2-u2-C4","difficulty":1,"kind":"mc","stem":"연못, 어항, 화단처럼 작은 곳에 있는 생물과 영향을 주는 요소를 통틀어 무엇이라고 하나요?","options":[{"t":"생태계","correct":true},{"t":"먹이사슬","mis":"SC4-2-u2-X05"},{"t":"환경오염","mis":"SC4-2-u2-X05"},{"t":"분해자","mis":"SC4-2-u2-X05"}],"explanation":["통틀어 부르는 말이에요.","작은 곳도 돼요.","생태계예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u2_review_d#3','sci',4,2,'u2','','g4_2_sci_u2_review_d','unit_review','SC4-2-u2-C11',1,'mc','auto','초록반 일지 ③에서 붕어, 개구리는 어떤 무리에 들어가나요?',ARRAY['SC4-2-u2-X15','SC4-2-u2-X17','SC4-2-u2-X13']::text[],false,'{"seq":3,"concept":"SC4-2-u2-C11","difficulty":1,"kind":"mc","stem":"초록반 일지 ③에서 붕어, 개구리는 어떤 무리에 들어가나요?","options":[{"t":"소비자","correct":true},{"t":"생산자","mis":"SC4-2-u2-X15"},{"t":"분해자","mis":"SC4-2-u2-X17"},{"t":"비생물요소","mis":"SC4-2-u2-X13"}],"explanation":["둘째 줄을 읽어요.","다른 생물을 먹어요.","소비자예요."],"asset":{"type":"passage","lines":["부들, 검정말 — 햇빛을 이용하여 스스로 양분을 만든다.","붕어, 개구리 — 다른 생물을 먹어 양분을 얻는다.","곰팡이, 세균 — 죽은 몸이나 배출물을 분해한다.","연못가 나무 밑동에서 버섯을 보았다."],"title":"초록반 일지 ③ 연못 생물 나누기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u2_review_d#4','sci',4,2,'u2','','g4_2_sci_u2_review_d','unit_review','SC4-2-u2-C15',1,'mc','auto','초록반 일지 ④처럼 여러 먹이사슬이 그물처럼 얽힌 것을 무엇이라고 하나요?',ARRAY['SC4-2-u2-X21']::text[],false,'{"seq":4,"concept":"SC4-2-u2-C15","difficulty":1,"kind":"mc","stem":"초록반 일지 ④처럼 여러 먹이사슬이 그물처럼 얽힌 것을 무엇이라고 하나요?","options":[{"t":"먹이그물","correct":true},{"t":"먹이사슬","mis":"SC4-2-u2-X21"},{"t":"생산자","mis":"SC4-2-u2-X21"},{"t":"비생물요소","mis":"SC4-2-u2-X21"}],"explanation":["그물처럼 얽혀요.","여러 사슬이에요.","먹이그물이에요."],"asset":{"type":"passage","lines":["한 줄로 이은 것 — 벼 → 메뚜기 → 개구리 → 뱀","메뚜기는 벼뿐 아니라 질경이도 먹는다.","메뚜기는 개구리뿐 아니라 직박구리의 먹이도 된다.","다람쥐는 도토리를 먹는다."],"title":"초록반 일지 ④ 먹이 관계 모형"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u2_review_d#5','sci',4,2,'u2','','g4_2_sci_u2_review_d','unit_review','SC4-2-u2-C20',1,'mc','auto','초록반 일지 ⑤에서 두 가지 환경오염과 관련 있는 것은 무엇인가요?',ARRAY['SC4-2-u2-X28','SC4-2-u2-X27']::text[],false,'{"seq":5,"concept":"SC4-2-u2-C20","difficulty":1,"kind":"mc","stem":"초록반 일지 ⑤에서 두 가지 환경오염과 관련 있는 것은 무엇인가요?","options":[{"t":"자동차에서 나오는 배기가스","correct":true},{"t":"하천에 버려진 쓰레기","mis":"SC4-2-u2-X28"},{"t":"출처를 적은 자료","mis":"SC4-2-u2-X27"},{"t":"관련 있는 것이 없다","mis":"SC4-2-u2-X28"}],"explanation":["줄마다 세어 봐요.","쉼표가 있어요.","배기가스예요."],"asset":{"type":"passage","lines":["하천에 버려진 쓰레기 — 수질오염","자동차에서 나오는 배기가스 — 대기오염, 수질오염","논밭에 지나치게 많이 쓴 농약 — 토양오염, 수질오염","조사한 자료마다 출처를 적었다."],"title":"초록반 일지 ⑤ 환경오염 조사"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u2_review_d#6','sci',4,2,'u2','','g4_2_sci_u2_review_d','unit_review','SC4-2-u2-C27',1,'mc','auto','초록반 일지 ⑥의 실천 방법으로 알맞은 것은 무엇인가요?',ARRAY['SC4-2-u2-X38']::text[],false,'{"seq":6,"concept":"SC4-2-u2-C27","difficulty":1,"kind":"mc","stem":"초록반 일지 ⑥의 실천 방법으로 알맞은 것은 무엇인가요?","options":[{"t":"정해진 길로만 다니기","correct":true},{"t":"뒷산 입구를 아예 막기","mis":"SC4-2-u2-X38"},{"t":"등산로를 더 넓히기","mis":"SC4-2-u2-X38"},{"t":"다른 산으로 옮겨 가기","mis":"SC4-2-u2-X38"}],"explanation":["둘째 줄을 읽어요.","길을 지켜요.","첫 번째예요."],"asset":{"type":"passage","lines":["장소 — 풀이 없어지고 길이 넓어진 학교 뒷산 등산로","실천 방법 — 안내 팻말 세우기, 정해진 길로만 다니기","사진을 찍으러 갈 때 다치지 않게 조심했다.","친구 나 — 「반짝이를 더 붙여야 최고의 자료가 돼.」"],"title":"초록반 일지 ⑥ 생태계 지킴이"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u2_review_d#7','sci',4,2,'u2','','g4_2_sci_u2_review_d','unit_review','SC4-2-u2-C28',1,'mc','auto','숲의 미로에서 팻말 없이 지날 수 있었던 것은 몇 가지인가요?',ARRAY['SC4-2-u2-X40','SC4-2-u2-X39']::text[],false,'{"seq":7,"concept":"SC4-2-u2-C28","difficulty":1,"kind":"mc","stem":"숲의 미로에서 팻말 없이 지날 수 있었던 것은 몇 가지인가요?","options":[{"t":"열한 가지","correct":true},{"t":"여덟 가지","mis":"SC4-2-u2-X40"},{"t":"네 가지","mis":"SC4-2-u2-X39"},{"t":"세 가지","mis":"SC4-2-u2-X40"}],"explanation":["일지 첫 줄을 읽어요.","모두 지날 수 있어요.","열한 가지예요."],"asset":{"type":"passage","lines":["팻말 없이 — 열한 가지가 모두 지날 수 있었다.","팻말 ① 생물요소만 — 흙, 물, 햇빛이 빠졌다.","팻말 ② 올바른 먹이사슬 — 네 가지만 남았다.","남은 길 — 옥수수 → 메뚜기 → 참새 → 새매"],"title":"초록반 일지 ⑦ 숲의 미로"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u2_review_d#8','sci',4,2,'u2','','g4_2_sci_u2_review_d','unit_review','SC4-2-u2-C31',1,'mc','auto','곤충 요리 전문가가 하는 일은 무엇인가요?',ARRAY['SC4-2-u2-X45','SC4-2-u2-X43']::text[],false,'{"seq":8,"concept":"SC4-2-u2-C31","difficulty":1,"kind":"mc","stem":"곤충 요리 전문가가 하는 일은 무엇인가요?","options":[{"t":"새로운 곤충 요리 방법을 개발한다","correct":true},{"t":"곤충을 모두 잡아 없앤다","mis":"SC4-2-u2-X45"},{"t":"가축을 더 많이 기른다","mis":"SC4-2-u2-X43"},{"t":"곤충 모습을 그대로 드러낸다","mis":"SC4-2-u2-X45"}],"explanation":["직업을 떠올려요.","개발해요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u2_review_d#9','sci',4,2,'u2','','g4_2_sci_u2_review_d','unit_review','SC4-2-u2-C2',2,'mc','auto','나뭇잎으로 표현할 때 자연물로 나타내기 어려운 눈, 코, 입은 어떻게 하나요?',ARRAY['SC4-2-u2-X03','SC4-2-u2-X02']::text[],false,'{"seq":9,"concept":"SC4-2-u2-C2","difficulty":2,"kind":"mc","stem":"나뭇잎으로 표현할 때 자연물로 나타내기 어려운 눈, 코, 입은 어떻게 하나요?","options":[{"t":"그림 도구로 그려서 완성한다","correct":true},{"t":"나무에서 잎을 더 따서 붙인다","mis":"SC4-2-u2-X03"},{"t":"비워 둔 채 발표한다","mis":"SC4-2-u2-X02"},{"t":"사진을 찍어 붙인다","mis":"SC4-2-u2-X02"}],"explanation":["셋째 차례를 떠올려요.","그림을 그려요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
