INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u2_review_d#11','sci',4,2,'u2','','g4_2_sci_u2_review_d','unit_review','SC4-2-u2-C13',2,'mc','auto','버섯과 생태계에서 비슷한 역할을 하는 생물은 무엇인가요?',ARRAY['SC4-2-u2-X18']::text[],false,'{"seq":11,"concept":"SC4-2-u2-C13","difficulty":2,"kind":"mc","stem":"버섯과 생태계에서 비슷한 역할을 하는 생물은 무엇인가요?","options":[{"t":"곰팡이","correct":true},{"t":"새매","mis":"SC4-2-u2-X18"},{"t":"토끼풀","mis":"SC4-2-u2-X18"},{"t":"잠자리","mis":"SC4-2-u2-X18"}],"explanation":["버섯은 분해자예요.","분해하는 생물을 찾아요.","곰팡이예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u2_review_d#12','sci',4,2,'u2','','g4_2_sci_u2_review_d','unit_review','SC4-2-u2-C15',2,'mc','auto','먹이사슬과 먹이그물의 다른 점으로 알맞은 것은 무엇인가요?',ARRAY['SC4-2-u2-X21','SC4-2-u2-X20','SC4-2-u2-X22']::text[],false,'{"seq":12,"concept":"SC4-2-u2-C15","difficulty":2,"kind":"mc","stem":"먹이사슬과 먹이그물의 다른 점으로 알맞은 것은 무엇인가요?","options":[{"t":"먹이사슬은 한 줄로 이어지고 먹이그물은 여러 사슬이 그물처럼 얽혀 있다","correct":true},{"t":"둘은 이름만 다르고 같은 것이다","mis":"SC4-2-u2-X21"},{"t":"먹이사슬에는 화살표가 없다","mis":"SC4-2-u2-X20"},{"t":"먹이그물에서는 한 생물이 한 가지만 먹는다","mis":"SC4-2-u2-X22"}],"explanation":["모양을 견줘요.","사슬과 그물이에요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
