INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u2_review_d#14','sci',4,2,'u2','','g4_2_sci_u2_review_d','unit_review','SC4-2-u2-C19',2,'mc','auto','환경오염의 종류를 바르게 묶은 것은 무엇인가요?',ARRAY['SC4-2-u2-X27']::text[],false,'{"seq":14,"concept":"SC4-2-u2-C19","difficulty":2,"kind":"mc","stem":"환경오염의 종류를 바르게 묶은 것은 무엇인가요?","options":[{"t":"대기오염, 수질오염, 토양오염","correct":true},{"t":"먹이사슬, 먹이그물, 생태계","mis":"SC4-2-u2-X27"},{"t":"생산자, 소비자, 분해자","mis":"SC4-2-u2-X27"},{"t":"햇빛, 공기, 온도","mis":"SC4-2-u2-X27"}],"explanation":["오염의 종류예요.","공기, 물, 흙이에요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u2_review_d#15','sci',4,2,'u2','','g4_2_sci_u2_review_d','unit_review','SC4-2-u2-C24',2,'mc','auto','생태계복원에 대해 바르게 말한 것은 무엇인가요?',ARRAY['SC4-2-u2-X34']::text[],false,'{"seq":15,"concept":"SC4-2-u2-C24","difficulty":2,"kind":"mc","stem":"생태계복원에 대해 바르게 말한 것은 무엇인가요?","options":[{"t":"원래의 모습을 잃은 곳을 원래대로 회복하는 일이다","correct":true},{"t":"한 번도 없던 곳을 새로 만드는 일이다","mis":"SC4-2-u2-X34"},{"t":"모두 치워 없애는 일이다","mis":"SC4-2-u2-X34"},{"t":"다른 곳으로 옮기는 일이다","mis":"SC4-2-u2-X34"}],"explanation":["복원의 뜻을 떠올려요.","원래대로예요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u2_review_d#16','sci',4,2,'u2','','g4_2_sci_u2_review_d','unit_review','SC4-2-u2-C31',2,'mc','auto','곤충 요리 전문가가 미래 직업으로 자리 잡을 수 있는 까닭으로 알맞은 것은 무엇인가요?',ARRAY['SC4-2-u2-X43','SC4-2-u2-X41','SC4-2-u2-X42']::text[],false,'{"seq":16,"concept":"SC4-2-u2-C31","difficulty":2,"kind":"mc","stem":"곤충 요리 전문가가 미래 직업으로 자리 잡을 수 있는 까닭으로 알맞은 것은 무엇인가요?","options":[{"t":"곤충 요리가 빈곤과 환경 문제를 함께 해결할 먹을거리로 관심을 받기 때문에","correct":true},{"t":"곤충은 온실 가스를 많이 배출하기 때문에","mis":"SC4-2-u2-X43"},{"t":"곤충은 먹을거리가 될 수 없기 때문에","mis":"SC4-2-u2-X41"},{"t":"예로부터 아무도 곤충을 먹지 않았기 때문에","mis":"SC4-2-u2-X42"}],"explanation":["친환경 미래 식량을 떠올려요.","두 문제를 해결해요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u2_review_d#17','sci',4,2,'u2','','g4_2_sci_u2_review_d','unit_review','SC4-2-u2-C9',3,'mc','auto','초록반 일지 ②에서 처음 보는 생물을 만났을 때 어느 요소인지 정하는 가장 알맞은 방법은 무엇인가요?',ARRAY['SC4-2-u2-X09','SC4-2-u2-X08']::text[],false,'{"seq":17,"concept":"SC4-2-u2-C9","difficulty":3,"kind":"mc","stem":"초록반 일지 ②에서 처음 보는 생물을 만났을 때 어느 요소인지 정하는 가장 알맞은 방법은 무엇인가요?","options":[{"t":"살아 있는지 아닌지를 살펴본다","correct":true},{"t":"조사 목록에 있는지 외운 것과 견준다","mis":"SC4-2-u2-X09"},{"t":"연못에 있으니 무조건 비생물요소로 정한다","mis":"SC4-2-u2-X09"},{"t":"움직이지 않으면 비생물요소로 정한다","mis":"SC4-2-u2-X08"}],"explanation":["나누는 기준을 떠올려요.","살아 있는지예요.","첫 번째예요."],"asset":{"type":"passage","lines":["학교 연못을 조사했다.","살아 있는 것 — 붕어, 개구리, 부들, 검정말","살아 있지 않은 것 — 햇빛, 물, 공기, 흙, 온도","친구 가 — 「작은 연못도 생태계구나.」"],"title":"초록반 일지 ② 학교 연못 조사"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u2_review_d#18','sci',4,2,'u2','','g4_2_sci_u2_review_d','unit_review','SC4-2-u2-C9',3,'mc','auto','초록반 일지 ③에서 생물을 세 줄로 나눈 기준은 무엇인가요?',ARRAY['SC4-2-u2-X13']::text[],false,'{"seq":18,"concept":"SC4-2-u2-C9","difficulty":3,"kind":"mc","stem":"초록반 일지 ③에서 생물을 세 줄로 나눈 기준은 무엇인가요?","options":[{"t":"양분을 얻는 방법","correct":true},{"t":"몸집의 크기","mis":"SC4-2-u2-X13"},{"t":"사는 곳","mis":"SC4-2-u2-X13"},{"t":"이름의 글자 수","mis":"SC4-2-u2-X13"}],"explanation":["세 줄을 견줘요.","만들고, 먹고, 분해해요.","양분을 얻는 방법이에요."],"asset":{"type":"passage","lines":["부들, 검정말 — 햇빛을 이용하여 스스로 양분을 만든다.","붕어, 개구리 — 다른 생물을 먹어 양분을 얻는다.","곰팡이, 세균 — 죽은 몸이나 배출물을 분해한다.","연못가 나무 밑동에서 버섯을 보았다."],"title":"초록반 일지 ③ 연못 생물 나누기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u2_review_d#19','sci',4,2,'u2','','g4_2_sci_u2_review_d','unit_review','SC4-2-u2-C14',3,'mc','auto','초록반 일지 ④의 「벼 → 메뚜기 → 개구리 → 뱀」을 잘못 고친 것은 무엇인가요?',ARRAY['SC4-2-u2-X22','SC4-2-u2-X20']::text[],false,'{"seq":19,"concept":"SC4-2-u2-C14","difficulty":3,"kind":"mc","stem":"초록반 일지 ④의 「벼 → 메뚜기 → 개구리 → 뱀」을 잘못 고친 것은 무엇인가요?","options":[{"t":"뱀 → 개구리 → 메뚜기 → 벼","correct":true},{"t":"벼 → 메뚜기 → 직박구리","mis":"SC4-2-u2-X22"},{"t":"질경이 → 메뚜기 → 개구리 → 뱀","mis":"SC4-2-u2-X22"},{"t":"도토리 → 다람쥐","mis":"SC4-2-u2-X20"}],"explanation":["화살표 방향을 따져요.","먹히는 쪽에서 시작해요.","첫 번째가 잘못되었어요."],"asset":{"type":"passage","lines":["한 줄로 이은 것 — 벼 → 메뚜기 → 개구리 → 뱀","메뚜기는 벼뿐 아니라 질경이도 먹는다.","메뚜기는 개구리뿐 아니라 직박구리의 먹이도 된다.","다람쥐는 도토리를 먹는다."],"title":"초록반 일지 ④ 먹이 관계 모형"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u2_review_d#20','sci',4,2,'u2','','g4_2_sci_u2_review_d','unit_review','SC4-2-u2-C22',3,'mc','auto','초록반 일지 ⑤의 오염을 줄이는 노력으로 가장 알맞게 짝지은 것은 무엇인가요?',ARRAY['SC4-2-u2-X31','SC4-2-u2-X30']::text[],false,'{"seq":20,"concept":"SC4-2-u2-C22","difficulty":3,"kind":"mc","stem":"초록반 일지 ⑤의 오염을 줄이는 노력으로 가장 알맞게 짝지은 것은 무엇인가요?","options":[{"t":"배기가스 — 가까운 거리는 걷기 / 농약 — 가능한 한 적게 쓰기","correct":true},{"t":"배기가스 — 자동차 더 타기 / 농약 — 더 많이 쓰기","mis":"SC4-2-u2-X31"},{"t":"하천 쓰레기 — 하천에 더 버리기 / 농약 — 마음껏 쓰기","mis":"SC4-2-u2-X31"},{"t":"배기가스 — 그냥 두기 / 농약 — 그냥 두기","mis":"SC4-2-u2-X30"}],"explanation":["원인을 줄여요.","덜 쓰는 쪽이에요.","첫 번째예요."],"asset":{"type":"passage","lines":["하천에 버려진 쓰레기 — 수질오염","자동차에서 나오는 배기가스 — 대기오염, 수질오염","논밭에 지나치게 많이 쓴 농약 — 토양오염, 수질오염","조사한 자료마다 출처를 적었다."],"title":"초록반 일지 ⑤ 환경오염 조사"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u2_review_d#21','sci',4,2,'u2','','g4_2_sci_u2_review_d','unit_review','SC4-2-u2-C28',3,'mc','auto','초록반 일지 ⑦에서 팻말을 붙일수록 지날 수 있는 것이 줄어드는 차례로 알맞은 것은 무엇인가요?',ARRAY['SC4-2-u2-X40','SC4-2-u2-X39']::text[],false,'{"seq":21,"concept":"SC4-2-u2-C28","difficulty":3,"kind":"mc","stem":"초록반 일지 ⑦에서 팻말을 붙일수록 지날 수 있는 것이 줄어드는 차례로 알맞은 것은 무엇인가요?","options":[{"t":"열한 가지 → 여덟 가지 → 네 가지","correct":true},{"t":"열한 가지 → 열한 가지 → 네 가지","mis":"SC4-2-u2-X40"},{"t":"열한 가지 → 여덟 가지 → 여덟 가지","mis":"SC4-2-u2-X39"},{"t":"네 가지 → 여덟 가지 → 열한 가지","mis":"SC4-2-u2-X40"}],"explanation":["줄을 차례로 읽어요.","셋, 넷이 빠져요.","첫 번째예요."],"asset":{"type":"passage","lines":["팻말 없이 — 열한 가지가 모두 지날 수 있었다.","팻말 ① 생물요소만 — 흙, 물, 햇빛이 빠졌다.","팻말 ② 올바른 먹이사슬 — 네 가지만 남았다.","남은 길 — 옥수수 → 메뚜기 → 참새 → 새매"],"title":"초록반 일지 ⑦ 숲의 미로"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u2_review_d#22','sci',4,2,'u2','','g4_2_sci_u2_review_d','unit_review','SC4-2-u2-C29',3,'mc','auto','초록반 일지 ⑧의 첫 줄로 알 수 있는 것은 무엇인가요?',ARRAY['SC4-2-u2-X42','SC4-2-u2-X41']::text[],false,'{"seq":22,"concept":"SC4-2-u2-C29","difficulty":3,"kind":"mc","stem":"초록반 일지 ⑧의 첫 줄로 알 수 있는 것은 무엇인가요?","options":[{"t":"곤충을 먹는 일은 예로부터 해 온 일이다","correct":true},{"t":"곤충은 앞으로 처음 먹게 될 먹을거리이다","mis":"SC4-2-u2-X42"},{"t":"조상들은 곤충을 싫어했다","mis":"SC4-2-u2-X42"},{"t":"곤충은 영양가가 없다","mis":"SC4-2-u2-X41"}],"explanation":["「조상들」을 봐요.","이미 먹어 왔어요.","첫 번째예요."],"asset":{"type":"passage","lines":["조상들은 메뚜기나 누에 번데기를 즐겨 먹었다.","곤충은 가축과 달리 먹이를 훨씬 적게 먹는다.","곤충은 온실 가스를 거의 배출하지 않는다.","친구 다 — 「곤충이면 아무거나 먹어도 되겠다.」"],"title":"초록반 일지 ⑧ 곤충 요리 탐구"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u2_review_d#23','sci',4,2,'u2','','g4_2_sci_u2_review_d','unit_review','SC4-2-u2-C20',4,'essay','teacher','초록반 일지 ⑤를 보고 원인 하나가 두 가지 환경오염을 일으키는 예를 쓰고, 그 오염이 생태계에 미치는 영향과 줄이기 위한 노력을 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"SC4-2-u2-C20","difficulty":4,"kind":"essay","stem":"초록반 일지 ⑤를 보고 원인 하나가 두 가지 환경오염을 일으키는 예를 쓰고, 그 오염이 생태계에 미치는 영향과 줄이기 위한 노력을 쓰세요.","answer_guide":{"answer":"예: 자동차에서 나오는 배기가스는 대기오염과 수질오염을 일으킨다. 대기오염이 심해지면 생물이 숨 쉬기 어려워진다. 가까운 거리는 걸어가거나 자전거를 타고 다녀 배기가스를 줄인다.","scoring_points":["두 가지 오염을 일으키는 예를 썼는가","생태계에 미치는 영향을 썼는가","줄이기 위한 노력을 썼는가"]},"explanation":["일지를 읽어요.","두 가지를 찾아요.","영향과 노력을 써요."],"asset":{"type":"passage","lines":["하천에 버려진 쓰레기 — 수질오염","자동차에서 나오는 배기가스 — 대기오염, 수질오염","논밭에 지나치게 많이 쓴 농약 — 토양오염, 수질오염","조사한 자료마다 출처를 적었다."],"title":"초록반 일지 ⑤ 환경오염 조사"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u2_review_d#24','sci',4,2,'u2','','g4_2_sci_u2_review_d','unit_review','SC4-2-u2-C28',4,'mc','auto','숲의 미로에 「곰팡이」 칸이 있어요. 팻말 ①과 ②를 모두 지킬 때 곰팡이에 대해 가장 알맞게 말한 것은 무엇인가요?',ARRAY['SC4-2-u2-X40','SC4-2-u2-X39','SC4-2-u2-X25']::text[],false,'{"seq":24,"concept":"SC4-2-u2-C28","difficulty":4,"kind":"mc","stem":"숲의 미로에 「곰팡이」 칸이 있어요. 팻말 ①과 ②를 모두 지킬 때 곰팡이에 대해 가장 알맞게 말한 것은 무엇인가요?","options":[{"t":"「곰팡이는 생물요소라 팻말 ①은 지나지만, 옥수수 → 메뚜기 → 참새 → 새매의 먹이사슬에 들지 않아 지날 수 없어.」","correct":true},{"t":"「곰팡이는 살아 있지 않아서 팻말 ①에서 빠져.」","mis":"SC4-2-u2-X40"},{"t":"「곰팡이는 생물요소라서 끝까지 지날 수 있어.」","mis":"SC4-2-u2-X39"},{"t":"「곰팡이는 작아서 지날 수 없어.」","mis":"SC4-2-u2-X25"}],"explanation":["팻말 두 줄을 차례로 따져요.","생물요소지만 사슬에 없어요.","첫 번째가 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_sci_u2_review_d#25','sci',4,2,'u2','','g4_2_sci_u2_review_d','unit_review','SC4-2-u2-C22',4,'essay','teacher','나의 생태계 지킴이 실천 방법을 두 가지 쓰고, 실천 방법마다 그렇게 생각한 까닭을 함께 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"SC4-2-u2-C22","difficulty":4,"kind":"essay","stem":"나의 생태계 지킴이 실천 방법을 두 가지 쓰고, 실천 방법마다 그렇게 생각한 까닭을 함께 쓰세요.","answer_guide":{"answer":"예: 가까운 거리는 걸어가거나 자전거를 타고 다니겠다. 자동차를 많이 이용하면 대기오염을 일으켜 생물이 숨 쉬기 어려워지기 때문이다. 일회용품 사용을 줄이고 분리배출을 하겠다. 쓰레기가 줄어들면 흙과 물이 덜 오염되기 때문이다.","scoring_points":["실천 방법 두 가지를 썼는가","실천 방법마다 까닭을 썼는가","방법과 까닭이 서로 이어지는가"]},"explanation":["실천 방법을 정해요.","까닭을 써요.","이어지는지 살펴요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
